/* 平成25年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h25.committeeSessions.push(...[{"id":"h25-20131105-5","meetingId":"h25-cm11","date":"2013年11月5日","dateIso":"2013-11-05","committee":"総務委員会","time":"午後 １時００分～午後 ２時３０分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件抜き出しています。","topics":[{"id":"topic-01","title":"担当課長の設置","agenda":"担当課長の設置","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"オリンピック・パラリンピック調整担当課長は、行財政改革担当課長が兼務されるということで、任務がさらに増えて、ご苦労さまですということなのですけれども、そして、その中で、この担当ができるということは、担当に配置される職員というのはどのようになるのか、職員の配置について、両方あわせて、わかったら教えていただきたいと思います。","respondent":"柏原行財政改革担当課長","answer":"職員につきましては、現段階ではこれに対する特別な配置等々は考えてはございません。ただし、これから東京都や国の動き、今後７年間、また動きが大きく出てくると思いますので、そういった動きを見ながら、そういった時期に必要な場合は検討していくことになろうかと思います。","id":"exchange-001"}]},{"id":"topic-02","title":"平成２５年特別区人事委員会勧告の概要","agenda":"平成２５年特別区人事委員会勧告の概要","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もう一つは、今回の引下げでは、国家公務員が復興財源の確保というところで引き下げられたのがあると思うのですけれども、それとの連動というか、関係というのはどうなのかということについてもお聞かせいただきたいと思います。とりあえず２点お願いします。","respondent":"堀越人事課長","answer":"実施されてきたところ、平成２１年に国において、自宅にかかる住居手当の廃止を行いまして、今、全国の自治体の中でも約６割程度が自宅にかかる住居手当を廃止しているという状況にあります。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"優秀な人材を確保するという、こっちの雇う側からすると、そうだと思うのですが、生活する職員の側からという観点でも、月額そのものを引き上げていくということも必要なのではないかと私は思いますけれども、そこはペンディングにしておきます。","respondent":"堀越人事課長","answer":"国につきましては、実際比較するときに、今、給与減額をしているということで、減額前の給料で計算した結果を用いまして、減額前と比較した結果が０.０２％ということですので、その結果を見て、改定を行わないという形で、実際にそういう形で国では判断しているです。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"今回の特別区人事委員会勧告の中身というのは、例年の民間との較差を解消するというところで出されてきていると捉えていいのかということを、ちょっと確認をお願いします。そんな中で、職員の頑張りに支えられて、区役所業務が成り立っているというのが実態なのではないかと思うのですけれども。","respondent":"堀越人事課長","answer":"市場原理による給与決定は困難であるとか、一方で、職員は勤労者ですので、適正な給与を確保していく必要があるということ、そういう中で、やはり民間の情勢と均衡を図っていくというのが当然あるべき姿だと思っていますので、今お話がございましたけれども。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"特に賃上げこそが日本のデフレ不況からの脱出というところで、民間の賃上げも求め、さらに公務員の賃下げはしないということでぜひやっていただきたいと、私は意見として申し上げておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"浅野委員","kind":"質問・要望","question":"新たな住宅手当制度ということで出ているので、ちょっと気になったのですけれども、昨年の勧告には、状況を考慮して検討するとあったのですけれども、状況を考慮してやられたと思うのですが、これは公民較差の中の数字に入っている額なのか、それとも外なのかということをちょっと教えていただきたいのです。","respondent":"堀越人事課長","answer":"今お話がありましたように、昨年の勧告において、あり方について検討していくという旨の言及がございました。","id":"exchange-006"},{"speaker":"浅野委員","kind":"質問","question":"もう一つですけれども、人事制度、勤務環境の整備等に関する報告の中で、１番目の１の(2)、受験者獲得策の強化ということで、特に技術系の職種についてのことが記載されていますけれども、技術系の方を採るというのは、品川区としても結構難しいのかなと、これを読むだけでは感じるのですけれども、昨年の人事委員会勧告を読みますと、職務の意欲等を的確に伝えるなど。","respondent":"堀越人事課長","answer":"来年度に向けまして、試験のいろいろな、本人の負担等も考えまして、今、１次試験ですと、択一試験の中で知能分野、知識分野のいろいろな出題の割合等もありますので、多少細かい話になって恐縮ですが、その中で選択しやすい形での改正等を検討しているという話も聞いてあります。","id":"exchange-007"},{"speaker":"須貝委員","kind":"質問","question":"今の浅野委員の質問と似たところもあるのですが、聞き洩らしたかもしれないので、もう一度お聞きしたいと思うのですが、月例給は公民較差を解消するという理由でこういうふうになりました、特別給もこういうふうになりました、しかし、新たな住居手当制度については、公民較差は実際あるのか、ここには何も載っていないということで非常に矛盾を感じるのですが、片一方は下げるならば。","respondent":"堀越人事課長","answer":"給料とボーナスにつきましては、この後、組合交渉とかがありますけれども、例年どおりのスケジュールでいけば、１１月下旬に妥結して、また条例改正をお願いして、来年、年明けに改定後の給料で実施という形で考えてあります。","id":"exchange-008"},{"speaker":"須貝委員","kind":"意見","question":"聞きたかったのは、そうやって公民較差をなくすということで、バランスで動いているのはわかるのですが、ところどころこういうふうに手当が増額したり、また引下げを緩和したりということになると、そこら辺、全体として矛盾が生じるのではないか、その辺についてちょっともう一回。","respondent":"堀越人事課長","answer":"矛盾が生じるのではないかというお話ですけれども、そういう形ではなくて、全体として０.１４％を解消できるような形にしまして、その後、各職員の給料表の級ごとの配分につきましてはそういう形で少し差を設けて、全体としては公民較差を解消するという形で。","id":"exchange-009"},{"speaker":"須貝委員","kind":"意見","question":"民間会社の一部は除いて、一部は確かに厳しいところはありますが、そうすると、採用に対してはもう十分優秀な人材が来ていると思うのですが、人事委員会の勧告も勤務環境の整備等に関する報告もそうなのですが、ちょっと矛盾しているのかなと思うのですが、その辺について、ちょっとご見解をお聞かせください。","respondent":"中山総務部長","answer":"人事委員会勧告の考え方の中に、国家公務員の給与水準のような官民較差はかなり分析して、ある種、その時々の緻密な分析の中で修正するということと、もう一つ、特別区、あるいは品川区にとっても、組織として望ましい給与なり。","id":"exchange-010"},{"speaker":"須貝委員","kind":"質問・要望","question":"１つ、４ページの勤務環境の整備なのですが、メンタルヘルスの推進、超過勤務は一部の方にはあると思うのですが、これはそれなりの残業手当、振替休日等はとっていると思うのですが、メンタルヘルスに関して、これは民間でもそうですが、今や公務員、この品川区役所においても、さまざまなメンタル的な問題で休まれている方が少しずつ増えている、また、下がるということがなく、そのままずっと増え続けるか。","respondent":"堀越人事課長","answer":"予防するというものです。もし、メンタルヘルスで不調を訴えた場合には、適切な対応をしていくということと、今後再発を防いでいくという考え方が大きくありまして、先ほど申し上げました若い職員、新規採用職員からそういった形での研修をしております。","id":"exchange-011"},{"speaker":"須貝委員","kind":"質問・要望","question":"最後に意見だけ、人は宝なので、品川区にも優秀な人材がたくさん採られていると思います。管理職の方が適宜、個人とちょっと話をしたり、頻繁に話をして、何とかそれを早期に解決して、本当に優秀な管理職に育て上げるように努力していただきたいと思います。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"}]},{"id":"topic-03","title":"平塚橋会館・シルバーセンター・西中延区営住宅解体工事請負契約","agenda":"平塚橋会館・シルバーセンター・西中延区営住宅解体工事請負契約","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この解体工事というのは、いつから始まって、近隣への説明会とかはいつごろされるものか、わかったら教えてください。","respondent":"小林施設整備課長","answer":"解体工事説明会につきましては、１０月１８日に実施したところです。工事の着手につきましては、１１月１日から着手しております。","id":"exchange-013"},{"speaker":"浅野委員","kind":"質問","question":"今回解体ということですけれども、４ページの上にもあるのですけれども、交通誘導員をここに置かれるというふうに見えるのですけれども、交通誘導員の役割というのは、ここが通用口になっていて、例えば、そこから車両が出たり入ったりというところを想定されているのか、それと、税務署のほうにも交通誘導員というのがあって、ここも確かに門がありまして、ここからの車等の出入り、まあ。","respondent":"小林施設整備課長","answer":"これは２カ所書いてあるのですが、原則、補助２６号線の北というか、右上が搬出入の出入り口、メーンゲートになっております。基本的には、補助２６号線から出入りしております。","id":"exchange-014"},{"speaker":"浅野委員","kind":"確認","question":"補助２６号線がメーンとなっているということで、税務署側がサブということで、それほど大きい車が出入りすることはないということでよろしいのかということを１つ確認したいのと、私の記憶によりますと、この補助２６号線は、たしか両側が荏原平塚学園の通学路に当たっていると思うのです。","respondent":"小林施設整備課長","answer":"１点目のご質問の税務署側は、基本的にはここの出入りはいたしません。通学路の質問ですが、通学路については、８時から８時半の朝の部分については、現場の車については出入りいたしません。あくまでも子どもを優先しております。","id":"exchange-015"},{"speaker":"浅野委員","kind":"質問","question":"学校側と何らかの形で調整とか、父兄への説明会とか、やっていないのであれば、これからだとは思うのですけれども、スタートするのですよね。そういう関係はどうなっているでしょうか。","respondent":"小林施設整備課長","answer":"学校とは綿密に打ち合わせをしております。今回の工事説明会も目の前の荏原平塚学園の校舎をお借りしまして、そちらで工事説明会を開いたところです。ＰＴＡについては、学校のほうから周知徹底を図ってもらうようなことでやっております。","id":"exchange-016"},{"speaker":"浅野委員","kind":"意見","question":"事故というのは、これだけは何が起こるかわからないということもありますので、工事関係者も含めて、安全確保に努めていただければと思います。騒音の問題もありますので、なるべく静かに、学校のほうまで聞こえるというふうになったら、大変なことになると思いますけれども、業者にも配慮をするようにお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"いながわ委員","kind":"確認","question":"ちょっとお伺いしたいのが、先ほどの話で１１月１日から工事が始まっているということで、またこれからいろいろ大きな音が出て、ダンプの出入りも激しくなるのかなという中で、工期が来年３月３１日ということなのですが、説明もしたということですが、改めて確認なのですけれども、これからどんどん日が落ちて、せわしない１２月が来る中で、先ほど浅野委員からも話がありましたけれども。","respondent":"小林施設整備課長","answer":"１点目のご質問、交通誘導員の関係ですが、当然コンクリートのがら等の搬出時については、交通誘導員を増員いたしまして、２名態勢で行います。","id":"exchange-018"},{"speaker":"いながわ委員","kind":"質問","question":"作業中、洗浄をちゃんとしていくというのですけれども、このエリアだと、４メートルの交通誘導員のところから入ったところで洗浄するのですか。よくそういった洗浄場というのは、別に設けたりはしているのですけれども、そういう記載がないのですが、どこで洗浄しているのですか。","respondent":"小林施設整備課長","answer":"場合によっては、ついたと仮定したときには、補助２６号線のゲートの手前に駐車場がありますので、わざわざつくるところは想定しておりません。ガンでタイヤを清掃して、確認ができた段階で補助２６号線に誘導するということでお話ししております。","id":"exchange-019"},{"speaker":"いながわ委員","kind":"質問・要望","question":"最近本当に多く見受けるので、そこはちゃんと指導していただくことと、あとは交通渋滞を巻き起こさないような誘導をするように徹底していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"}]},{"id":"topic-04","title":"南品川四丁目で発見された不発弾の処理","agenda":"南品川四丁目で発見された不発弾の処理","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"不発弾が発見されてからこの爆破処理まで、本当に大変なご苦労だったとお聞きしましたけれども、今までにないような、災害対策基本法に基づいた対応という状況になったと思うのですけれども、この中でどういう検討がされたのかというところで改めてお聞かせいただきたいのですが、区の本部長以下区職員の２８０名というところなのですが、これは主にどういう課の職員がされたのかということと。","respondent":"工藤危機管理室長","answer":"現地は区の職員２８０名ですけれども、区の当日の業務はいろいろと指揮、情報や広報をする班、また避難所を運営する班、避難の誘導をする班、道路を規制する班等、それぞれ班体制を組みまして、そこのところから区の職員を募って対応したところです。これが現地の対応です。","id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"なかなかあることではないと思うのですが、前に不発弾処理計画というのもいただきましたけれども、ここの中でも、災害対策基本法第２条第１号の中にさまざまな問題についてというところがありまして、その中の爆発というのがここに当たるということで、市町村長の責任で住民の生命、身体を守るということで今回この対応をされたということなのですけれども、そういう点でいえば、防災対策というか。","respondent":"工藤危機管理室長","answer":"今回の部分をもとにまたいろいろと踏まえて対応していきたいと考えています。","id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"とても丁寧にやっていただいて、終わった後でのさまざまな教訓というのをまとめて、次に活かせるようにぜひしていただけたらと思っているのですけれども、説明会にしても、個別訪問にしても、本当に丁寧にやっていただいたと思うのですが、この７００世帯、１,１５０人に個別訪問ということなのですが、これはどれぐらいの体制で、どんなに大変だったかというのをちょっと教えていただきたいのと。","respondent":"工藤危機管理室長","answer":"入院、もしくは入所しているという方が１６名、実際のところ、３７名中、特別な支援が必要な方が８名ということで、この８名に対してヘルパーを派遣したり、ショートステイの利用をお願いしたり、車で避難所に移動したりということで、個別に対応した。","id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"パイプ椅子で、ストーブを囲んでずっといるという感じで、避難所の中がちょっと寒々とした感じがしたということだったのですけれども、そこら辺の対応という点では、また２時近くになったにもかかわらず、食事も出なかったということなのですけれども、そこら辺の対応がもうちょっと、人数も結果的には、小学校の体育館は２３人ということでしたので、地域センターのほうはよくわからないのですけれども。","respondent":"工藤危機管理室長","answer":"ただ、お話にもありましたけれども、避難所の責任者もその辺は十分加味して、ストーブをすぐたいた、また毛布も配って対応したですので、私どもとしましては、限られた環境の中で最善を尽くしたとは思っております。","id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"避難までの事前の準備、個別訪問から、高齢者福祉課や障害者福祉課などとも連携しながらの全庁挙げてのさまざまなきめ細やかな、一人一人に対応するというところでの丁寧な対応ということで、ぜひここから震災対策にも教訓として活かしていただきたいということと、避難所では、これが震災だともっと大変になるところが想像されますので、そこら辺は今回の教訓も踏まえながら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"数日前なのですけれども、故障車を運んでいる米軍の車両が、どうも道を間違えて入ってきてしまったみたいで、大崎高校の前から曲がることができなくて、ストップした状態になって、五、六時間ぐらいにわたってずっと車が通ることもできないし、大変な状況になっていたとお聞きしたのですけれども、この点について、一体どういう状況だったのか、自治体に何か情報が入っていたら。","respondent":"工藤総務課長","answer":"その結果、結論を申し上げますと、１３トンの車だということで、レッカー移動がなかなかできないということで、レッカー車がなかなか来なかったということで、警察で別の牽引方法で車両を受けて、道路から取り除いたということで、５時５０分だと思いますけれども。","id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"米軍ということで、意思疎通というのがすごく大変な状況みたいで、近隣の方も何が起こっているのかわからない、ただ、米軍だという状況なのですけれども、米軍が一般道を通るときというのは、そういうのは全く自由に通るという感じで、自治体への連絡とかもなくて通るのか、また今回みたいに事故が起きたときの対応というのも、どういうふうに対処されるのかというあたりは。","respondent":"工藤総務課長","answer":"そういった部分では、特に私ども品川区には報告はございません。ただ、今回の場合には、複数で通行していて、１つの車両が道を間違えて左に入ったという話は聞いております。","id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"英語を話せる方が近所から来られて、いろいろ聞いたところによると、海兵隊が富士の演習場に行くときに道路を間違えて、行き過ぎたのではないかということと、曲がったらということで、米軍の方と話をしたということもちょっと聞いたのですけれども、そういう状況というのは、区としては全く、今言われたようなことしかわからないし、米軍ということになると、全くわからない、事故が起こっても。","respondent":"中山総務部長、須藤委員長","answer":"ですから、基本的には、そういうものを一自治体として把握し、また住民に説明する必要はないと考えておりますけれども、警察を通じてとか、そういう情報が入ってくる部分については適切に把握していくと区としては考えているところです。以上でその他を終了いたします。以上で、本日の予定は全て終了いたしました。これをもちまして、総務委員会を閉会といたします。","id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/599487?Template=document&Id=1964#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":25495,"voices":72}},{"id":"h25-20131106-14","meetingId":"h25-cm11","date":"2013年11月6日","dateIso":"2013-11-06","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ４時２９分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件抜き出しています。","topics":[{"id":"topic-01","title":"平成２５年陳情第１５号、東五反田４丁目の国有地活用","agenda":"平成２５年陳情第１５号、東五反田４丁目の国有地活用","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"それで、この陳情に出ているように、グループホームを建設する際にはサービスコーナーや、公園とか多目的ルームとか防災施設のようなものというふうに、そこが趣旨なんだろうと思うんですけれども、実際この地域には、公的施設でこういうものをつくってほしいという趣旨に合致するような施設がどこにどれだけあるのか、そのあたりを教えていただきたいなと思います。","respondent":"柏原行財政改革担当課長","answer":"こちらの陳情にあります、例えばサービスコーナー、地域センターのミニ出張所というような表現もされてありますけれども、こちらの地域ですと、大崎第一地域センターがまず西五反田の３丁目にあります。","id":"exchange-001"},{"speaker":"南委員","kind":"質問","question":"地域センターで戸籍にかかわること、住民登録だとか印鑑証明だとか、そういう事務をここではできるにしても、そのほかの図書のサービスも含めて幾つかはできるんですけれども、それ以外のことは区役所までおいでにならないとできないという関係もあって、利便性という点では一定の配慮があっていいんじゃないかなと思っているんですけれども、サービスコーナーの設置については。","respondent":"柏原行財政改革担当課長","answer":"サービスコーナーの部分ですけれども、今現在は大井町と武蔵小山のところにありますが、こちらにつきましては、例えば区民の方の利便性といったところを考慮しまして、区役所とか地域センターとか来るまでちょっと遠いであるとか、時間的なものを考慮いたしまして。","id":"exchange-002"},{"speaker":"南委員","kind":"質問","question":"そういう点についての見解を伺いたいなと思います。","respondent":"柏原行財政改革担当課長","answer":"サービスコーナー等々における地域性の部分であろうかと思いますけれども、確かにそういった、例えばサービスコーナー的な行政サービスといった部分においては、地域センターが西五反田の３丁目にありますので、こちらに行くのはなかなか大変だろうという認識はしています。","id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"これは当然といえば当然だと思うんですけれども、新しく国の土地を購入して、どこが設置主体かはまだわかりませんけれども、とにかく高齢者の施設をつくっていくという決断をされた時点で、そこの地域を、そういう計画を区が持ったんであれば、地域のニーズがある、そこのところをよくしんしゃくしていただいて、つくっていただきたいという趣旨ですから。","respondent":"柏原行財政改革担当課長","answer":"今後、限られた面積の中で、では何ができるのかというところになりますと、例えばグループホームという想定等々が今ありますけれども、そういったところで運営していかなくてはいけないといったことを考えたときに、こんな施設もこんな施設も入れるかというのは。","id":"exchange-004"},{"speaker":"南委員","kind":"質問・要望","question":"五反田駅はエレベーターも設置されたんだと思うんですけれども、それでも乗りかえていくのは大変な一日仕事になっちゃうと思いますので、そういう点でぜひ、サービスコーナーについては区民全体に、年齢に限らず皆さん、全世代を対象にしたサービスですから、そういうことをきちんと受けとめていっていただきたいということを、強く要望しておきたいと考えていますけれども。","respondent":"柏原行財政改革担当課長","answer":"繰り返しになりますけれども、こちらは土地面積も小さい、それからグループホーム等々でやっていくために、ある程度制限といいますか、限られた延べ床面積を有効的に使わなくてはいけないといった部分がありますので、いろいろご要望等々はあるのだろうとは思いますけれども。","id":"exchange-005"},{"speaker":"南委員","kind":"質問・要望","question":"ぜひ地域ニーズはしっかり把握していただいて、それで検討していただきたいとさっきから繰り返しているので、これだけにしますけれども、ぜひよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"あべ委員","kind":"質問","question":"幾つかお伺いしたいと思います。陳情にあるこの地域のエリアなんですけれども、陳情書に東五反田４丁目、５丁目および上大崎とある大体この地域のことを、この地域と呼ぶことにすると、先ほども近隣に公共施設が幾つあるか、どういったものがあるかという質問が出ていたんですけれども、計画も幾つかあるかなと思います。","respondent":"柏原行財政改革担当課長","answer":"こちらにつきましても、例えば防災の倉庫的なものであるとか、子育て支援施設、それから行政サービス機能というのも検討の中に入っているところで、中身そのものの細かい検討は今後ですけれども、昨年でしたか、建設委員会等々でも。","id":"exchange-007"},{"speaker":"あべ委員","kind":"質問","question":"確かに今、陳情の出ているこの地域というのは、区役所から非常に不便な地域だと考えていますが、仮に目黒駅にサービスコーナー的なものができるのであれば、それはかなり改善されるかなと思うんですけれども、この計画について、ちょっと所管が厳しいところかもしれませんけれども、もろにかぶるところでもありますので、現段階での状況を教えてほしいと思います。","respondent":"桑村企画部長","answer":"前から目黒の辺につきましては、行政サービスコーナーの要求、ご要望があったのも私どもは知っておりますし、検討はしておりますけれども、正直言って、その意味での委員会報告をしているわけではございませんし、またやめるという報告もしていませんので。","id":"exchange-008"},{"speaker":"あべ委員","kind":"質問・要望","question":"なので、私もこのエリアのどこかに行政サービスコーナーがあればいいなと思うのですが、それが五反田駅あるいは目黒駅といったところでご検討はしていただきたいなという気持ちは持っております。今の段階ではまだ建物もない段階で、そこまで確約するのは難しいかもしれないですけれども、その方向でも物を考えていただくことは可能かどうか、ご答弁いただけるでしょうか。","respondent":"柏原行財政改革担当課長","answer":"例えば福祉的な用途ということで、ある程度の幅が可能かどうかというのは、これからの国との話ですけれども、比較的そこは厳しめに国は考えているようですので、例えばグループホームと何々というふうにある程度明記した形で出して、それ以外の用途で使うと。","id":"exchange-009"},{"speaker":"原委員","kind":"質問・要望","question":"一番基本的なところで、品川区の中で西というか北というか、北西に位置している場所ですよね。そうすると、ここの場所について、区自体は基本的にどういうふうに考えているか、まずお聞かせいただきたいんですけれども。","respondent":"柏原行財政改革担当課長","answer":"ちょっと抽象的な言い方になってくるかもしれないんですけれども、こちら、山手線の内側というところで、建物等々も大きいお屋敷があって、そういった地域であって、わりと静かな住宅街といった環境にあると思ってございまして、施設的なところで申しますと。","id":"exchange-010"},{"speaker":"原委員","kind":"質問・要望","question":"ですから、これは私自身の感覚的なものになってしまうのかもわかりませんけれども、国もこれから高齢者向けの、厚生労働省が基本になって、２４時間のいろいろなセンター管理とか、いろいろ法律的なものも変わってくると思いますので、そうすると、今回当該物件、実際にＮＴＴ東日本関東病院がありますので、その辺との兼ね合い的なものができたならば、すごくありがたいなと思うんですけれども。","respondent":"柏原行財政改革担当課長","answer":"そういったところも踏まえて、そういった施設が足りないといいますか、ない地域でもございましたので、今回こういう物件が出てきたところを捉まえて、そういった面での重視といいますか、区としても一つそこにてこ入れができるのではないかと思いますので。","id":"exchange-011"},{"speaker":"原委員","kind":"質問・要望","question":"これは聞くことではなくて、お願い事なんですけれども、うちの鈴木博委員もそうなんだと思いますが、どうしてもこういったケア関係というのは、区だけ単独ではできませんので、都とか国とかの関係等もありますので、そういう意味合いからしてでも、とにかく連除法的なものを含めて連絡を密にしていって、こういったものが高齢者とか福祉というところに貢献していっていただきたいなと切に願いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"浅野委員","kind":"質問・要望","question":"このような形で、区民の方からも陳情いただいておりますけれども、ちょっと立ち返って、先ほど答弁もありましたが、高齢者施設ということで申請をされているということで、これが例えば要望のある多目的ルームとか、いろいろありますけれども、どこまで高齢者施設と、福祉施設と言えるかというところになってくると、かなり難しいだろうし。","respondent":"柏原行財政改革担当課長","answer":"はっきりしたボリュームチェック的なところは、まだ今の段階ですからなかなかと思いますけれども、机上の想定の中では２ユニットまでグループホームをつくったり、それプラスアルファの部分というのは何らかの制約をされるだろうとは考えてあります。","id":"exchange-013"},{"speaker":"浅野委員","kind":"質問・要望","question":"そうしますと、ここで入れるのかと言われると、ちょっと違うのかなという感じもしますし、また適地というものがそう簡単には出ると思わないですけれども、適地が出たときというんでしょうか、考えられるときに、また検討するというのも１つの手かなという気がします。そういう意味では、グループホームというのがこの場所にはよいのかなと考えます。そこは意見ということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"渡部委員","kind":"意見","question":"１点だけです。８月１日の段階で、厚生労働省年金局から照会があったということで、私どもが２回ここで審議をしてきたと思います。行財政改革ですので。で、当然このような陳情が上がった経緯の中で、行政として８月の照会で、議会でもまだ２回しかできないような状況。ご地元の町会長ですとか当該地域に対して、そこの土地を取得しますよというようなアナウンスはかけましたか、かけていませんか。","respondent":"柏原行財政改革担当課長","answer":"例えば地元の町会長等々に、具体的にこういった形でということでの照会はかけてございません。","id":"exchange-015"},{"speaker":"南委員","kind":"質問","question":"もともとの報告事項にあった、この国有地の購入を基本とするという、ここについてもこの質疑の中で触れていいんですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"南委員","kind":"質問","question":"先ほど陳情だけだったので、こちらについて質問したいと思って手を挙げました。それで、購入するということは、私は前向きに評価して受けとめたんですけれども、同じ国有地でも、今回購入と決めたのはどういうことなのかなというのを聞きたかったんです。今回購入したというのは、そことの関係で、どういう判断で購入したのかなというのを率直な疑問として感じたので、それを伺いたいと思います。","respondent":"柏原行財政改革担当課長","answer":"ちなみに南品川は、あちらの物件の対応は保育の施設ということで考えてありますので、今後の人口の動向であるとか、そういったところを考えたときに、定期借地という判断をしたところです。","id":"exchange-017"},{"speaker":"南委員","kind":"確認","question":"それと、今は購入を決定したというレベルなので、それ以上のことは聞いても、まだこれからだという答弁かなと思うんですけれども、事業主体というのはどういうふうに考えているんですか。","respondent":"柏原行財政改革担当課長","answer":"事業主体につきましては、今の段階ではお答えできる状況ではないです。","id":"exchange-018"},{"speaker":"南委員","kind":"質問","question":"したがって、この価格調整についてはこれからのスケジュールで、今聞いても、あまり正しい価格は出てこないと思うんですけれども、この地域的な価格の想定される金額、一定のレベル以上の金額になるんだろうと思うんですが、そういう金額を承知しながら買うというふうにしたというあたりを、もう一度伺いたいなと思います。","respondent":"桑村企画部長","answer":"前回の行財政改革特別委員会でもいろいろご議論いただきましたけれども、委員の皆さんからもかなり購入のご意見があったということもあって、その意味でいろいろなことを勘案させていただいて、国としっかり金額が折り合っているわけじゃありませんけれども。","id":"exchange-019"},{"speaker":"あべ委員","kind":"質問","question":"今後の見通しなんですけれども、１０月の末に厚生労働省に回答して、確定するのがいつごろで、その後というようなスケジュールが、わかる範囲で教えていただければと思います。","respondent":"柏原行財政改革担当課長","answer":"スケジュールの部分ですけれども、相手方が財務省であれば、ある程度きっちりとしたスケジュール感を出してきてくれているんですが、厚生労働省は何分、こういったところの事例がないということで、あれなんですけれども、この後に、品川区にしますよという決定の回答は。","id":"exchange-020"},{"speaker":"渡部委員","kind":"確認","question":"内容に書かれていますことも、確認はしています。あくまでもこの東五反田４丁目の国有地の活用についてということであれば、さまざま書いていただいてありますが、あくまでもグループホームの設置を推し進めていくんだというところで、下のほうに、仮にこの土地でかなわないのであればというのは、全く別問題と考えますので、今回、私ども自民党としては、結論を出して不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"浅野委員","kind":"質問","question":"理由につきましては、こちらの土地を検討する中で、グループホーム２ユニット、私どもの質問の中でも、２ユニットでないと、１つの事業者がやるにしても採算はとれないだろうということで、１ユニットというのは当然難しいですし、３ユニットというとフロアが足りないという、さまざまな要因から、また高齢者の需要、これから高齢者がさらに増えていくことを考えるならば、こういう施設を。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"あべ委員","kind":"質問・要望","question":"こうした形で地域の要望を寄せていただいたこと自体は、いいことだなと思うんですけれども、ただ、先ほども申しましたように、ここの陳情の中で主に出てきているサービスコーナーというのは、もう少し駅前等、利便性のいい場所につくるのが筋であろうと考えています。ただ残念ながら、今回の当該の土地については、ご希望には沿えないかなという意味で、不採択と考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"原委員","kind":"意見","question":"本日決めるということで、内容につきましては、各委員からご意見が出ているとおりでございまして、私も、まず行政、頑張ったなという思いです。この陳情に関しましては、本当にいろいろなものをたくさん、とにかくできる限りのことを地域の方のために入れたいというのはわかるんですが、やはりスケール的に難しいだろうという形で、不採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"南委員","kind":"質問・要望","question":"私は採択を主張したいと思います。気持ちは先ほどの質問のところでも表明してきたつもりなんですけれども、この地域には公共施設が少ないということ、そして、品川区役所まで行かないと、あるいはガードまでくぐって、しばらく川のほとりを歩いていかないと、地域センターには到達しないということで、利便性から見るとかなり疎外されている地域じゃないかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"南委員","kind":"質問・要望","question":"これからもこういうことは、今までもありましたけれども、こういうことが出てくるということもあり得るんですが、区民の方々の共有財産でもあるし、そういう点で一定の判断基準はあってしかるべきだと思いますので、その点を確認したいので、もう少し説明をしていただきたいと思います。","respondent":"柏原行財政改革担当課長","answer":"ただ、こういったことを受けて、先ほどもちょっと触れましたけれども、跡地の有効活用といった面、それから防災面、地域の実情等々を考えて、検討に入るところです。","id":"exchange-026"},{"speaker":"南委員","kind":"質問","question":"そうしますと、この朋優学院は、校舎の新築に当たって補完避難所機能を高めるという内容も、改修・改築計画には含まれているという理解でいいんですか。","respondent":"柏原行財政改革担当課長","answer":"既に今、補完避難所と指定していますので、それが建物が新しくなるといいますか、耐震化、それから老朽化を直すために建替えするわけですから、補完避難所としての機能は高まるです。","id":"exchange-027"},{"speaker":"南委員","kind":"質問・要望","question":"決定ではないということだったんですけれども、いつの時点で、しばらく来年の９月までは利用のところがあるのであれですけれども、そこまでの期間、どの程度の時点で本格決定するというふうになっていくのか、もしその間に、例えば利用状況等々が出てきた場合にはどうだとか、ちょっとあれですけれども、それと、地域でかなり、豊葉の杜中学校のある地域では。","respondent":"柏原行財政改革担当課長","answer":"スケジュール感のところですけれども、こちらにつきまして、平成２７年３月というふうにご要望が出てあります。","id":"exchange-028"},{"speaker":"南委員","kind":"質問","question":"時間も押しちゃっているので恐縮なんですけれども、地域の防災に対する要求のところがよくわからなかったので、学校の施設あるいは校庭等々で、防災に対して非常に、事があったときにはもちろんそこは活用するんですけれども、日常的に訓練も含めて、防災にかかわる町会としての事業展開ができるようなスペースも確保してほしいというふうに私は理解しているんですけれども、そのあたりのことは。","respondent":"柏原行財政改革担当課長","answer":"こちらの地域から伺っているお話は、まずここが避難所であるということで、何かあった際には避難所としての機能を確実にできるようにしておくということ、それがまず第１点です。","id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/812388?Template=document&Id=5956#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":21958,"voices":76}},{"id":"h25-20131107-17","meetingId":"h25-cm11","date":"2013年11月7日","dateIso":"2013-11-07","committee":"震災対策特別委員会","time":"午後 １時００分～午後 ３時１５分","status":"正式会議録","sourceType":"formal","overview":"震災対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/433468?Template=document&Id=6442#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=17&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":1177,"voices":10}},{"id":"h25-20131125-6","meetingId":"h25-cm11","date":"2013年11月25日","dateIso":"2013-11-25","committee":"区民委員会","time":"午前１０時００分～午前１１時２４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件抜き出しています。","topics":[{"id":"topic-01","title":"第６６号議案 平成２５年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"第６６号議案 平成２５年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"９月８日にＩＯＣ総会で東京開催が決定されました。この事業の開催に当たって、生活や環境の調和のとれた無理のない取り組みを進めることが必要だと思いますけれども、例えば便乗した無理な箱物建設や住民追い出しなど、こうしたことはオリンピック憲章と反すると私は思いますけれども、そういう点についてはどのように考えていらっしゃるのか、まず総論を伺いたいと思います。","respondent":"安藤文化スポーツ振興課長兼オリンピック・パラリンピック推進担当課長","answer":"今回２０２０年に向けて補正予算を組んだものについては、９月に決まりましたその熱い思いを、今、継続して、ここで子どもたちを中心にひのき舞台で活躍する夢を持っていただこうというもので、実際に計上させていただいているものです。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"今後、具体化していくに当たって、やはりどういう視点が大事なのか、その点を改めて伺いたいと思います。私はこのオリンピック・ムーブメントの意味を、子どもたちにも実感できるような事業にしていただきたいと思うのです。そして、その意味合いからも、今回一般財源を投入するというわけですから、あえて伺いたいのは、なぜ一般財源なのかというところも、その意味合いからもご説明いただきたいと思います。","respondent":"安藤文化スポーツ振興課長兼オリンピック・パラリンピック推進担当課長","answer":"さまざまなところで、ただ技術の提供だけにとどまらないで、そういうスポーツをやっていく上での考え方等の部分も今後は事業の中で入れていきまして、そういうものを皆様には経験していただいて、オリンピック・ムーブメントの考え方を広めていきたいと考えています。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"１点だけ。当初予定の休館の時期よりも、今回の休館の時期のほうが長くなるので、ちょっとそこの事情と、それを踏まえた利用者への案内の説明を改めて伺いたいと思うのと、これに伴って、ほかの天井部分はどうなのかというのも思いますので、ほかの施設のこういうホールの天井部分についてはどういう状況になるのか、そこだけ説明していただきたいと思います。","respondent":"米田商業・観光課長、安藤文化スポーツ振興課長兼オリンピック・パラリンピック推進担当課長","answer":"当然それがまた英語の多言語化を行い、あるいはほかの多言語化マップを見つつ、ほかの言語の作成も必要であろうということがありましたら、これはまた次年度以降の判断になってくるかと考えているところです。そしてその天井部分を改修するということで、期間もこの４月１日から３カ月半ぐらい、まだ設計もこれからかけるものですから、今、予定がとりあえず３カ月半という形で設定をさせていただいたところです。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問","question":"それについてはどこがどう旗振りになるのか、所管が正直わからないまま伺っているところは申しわけないとは思っておりますけれども、ぜひそういうところにもこの多言語化という意味合いに含めることが必要だと思いますけれども、その点についてはどのように取り組んでいこうとしていらっしゃるのか、お考えだけ伺いたいと思います。","respondent":"米田商業・観光課長、安藤文化スポーツ振興課長兼オリンピック・パラリンピック推進担当課長","answer":"確かにちょっとどこがということはありますが、基本的にオリンピック・パラリンピックへ向けた動きというのは全庁挙げて取り組んでいくということで、担当課長等の設置もされておると。庁内の調整だとか、そういうものについては担当課長がやると、対外的な部分については私がやるというようになってありますが、またそれとは別に、庁内で検討委員会も第１回が９月２０日には立ち上がってあります。","id":"exchange-004"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"先ほど中塚委員からも出ましたが、これは一般会計で、今回オリンピック・パラリンピック関連の補正予算が出ていますけれども、今までも例えばオリンピック・パラリンピックの東京招致の事業とかいうのは、基本的には東京都でやっているものが多くて、区でやるものに関しても東京都から何らかの補助金等が出てきたものが多いと思うのですが、これはなぜこの時期に、あえて一般会計で区単独でこの事業を幾つか。","respondent":"安藤文化スポーツ振興課長兼オリンピック・パラリンピック推進担当課長","answer":"しかし、今、決定されて、先ほどちょっとお話しましたように、東京都のほうも、今、そこが変わって、この１０月にスポーツ局のほうもオリンピック準備部局として一つの看板ができました。","id":"exchange-005"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"わかりました。次に、１個ずつ、各事業についてお伺いしますが、まず初めに、日本の伝統文化・おもてなしについてですが、この事業は区が直接やっていくのか、それとも国際友好協会に委託をしていくのか、その点を教えていただきたいのと、先ほど何か恵方巻きの食材に関しては実費だということでしたが、屋形船の借り上げ等がありましたね。その実費等で負担をされるのかどうかを教えていただきたい。","respondent":"寺嶋協働・国際担当課長","answer":"３点目の在住の方と海外からいらっしゃる方、まさにご指摘のとおりですが、基本的には日本に住んでいる、区内に住んでいる外国人の方、ご家族の方で参加していただくということがベースになっているのですが、先ほど申しましたこの委託を予定されている。","id":"exchange-006"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"荏原文化センターですが、これはいろいろ耐震化を各施設されていて、今回、８月５日付で建築基準法施行令の改正がされたということで、やらざるを得なくなったということだと思いますが、まず、荏原文化センターの耐震化をされているのですが、今後荏原文化センターをどのように、どこまで今後活用していくのかというような展望がもしあれば、教えていただきたいのと、近くにスクエア荏原が開設されて。","respondent":"安藤文化スポーツ振興課長兼オリンピック・パラリンピック推進担当課長","answer":"今後荏原文化センターをどのように、いつまでですが、これは荏原文化センターに限ってのことでよろしいでしょうか。","id":"exchange-007"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"わかりました。その耐震化をやりますときに、さまざまな基準値があると思うのです。もちろんその基準値をクリアするために耐震化をやりますけれども、できたら今後も基準値というのは変わる可能性があるでないですか。これは要望で終わります。それと、区内の小学校高学年４５人程度となっていますが、これの選考方法というのはどのように考えているのか、その点を教えてください。","respondent":"安藤文化スポーツ振興課長兼オリンピック・パラリンピック推進担当課長","answer":"対象の選考方法ですが、今、公益財団法人スポーツ協会のほうでもジュニアの育成をやってあります。そんな中で、今、非常に頑張ってやっている子どもたちを対象にするのか、ちょっと選考方法についても検討するです。","id":"exchange-008"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"わかりました。パラリンピックは、ぜひ力を入れていって、やっていただきたいと思います。最後、観光資源の整備のところですが、まず、ビーチバレー大井町大会の開催、７００万円という、これ１日ですよね。非常に大きな額が計上されていますが、まずこの内訳を教えていただきたいと思うので、よろしくお願いいたします。","respondent":"米田商業・観光課長","answer":"大体ですけれども、いわゆる会場の設置から撤去までが約３００万円。それから、その他企画運営ですとか、あるいはそれに関する印刷物等、それからあとはある程度有名な選手を呼んでくる場合の出演料ということで、計上させてあります。","id":"exchange-009"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"少し、このビーチバレーを大井町の駅前でやるというのに非常に違和感を感じるのですが、まず、これは砂を道路に設置をしてやるということでよろしいのでしょうか。３月ぐらいに予定されているのかと思いますが、まだ肌寒い時期にビーチバレーを駅前でやるというのが、本当にこのオリンピックのためになるのかどうかも含めて、必要なのかどうか、その辺の考え方を教えていただきたいと思います。","respondent":"米田商業・観光課長","answer":"そちらのなるべく駅に近いところ、人の通りが多いところに会場を設置して、いわゆる品川区内で開催される競技、実際の開催される場所は別ですけれども、そちらで実施というのもちょっと今のところ現実的ではないので、まず、品川区と言えばどこかということで一つ大井町が選ばれ。","id":"exchange-010"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"そういうので向こうに行って、向こうでビーチバレーを見てもらうとか、そういったほうが、逆にもっと「あ、こっちでやるんだ」と場所を皆様に知ってもらう意味でも、それこそオリンピック・パラリンピックのあれになるし、例えば水陸両用バスを使うことによって、新たな観光のアピールにもなるのかと僕は思いますけれども、今回、予算計上されていますけれども。","respondent":"米田商業・観光課長","answer":"今、ご提案いただいた趣旨等については、多分このビーチバレーのイベントというものも、２０２０年まで継続して何かしらまたこの取り組みを通じて今後どうしていこうかというようなことは検討されるものだと思いますので、そういうときに。","id":"exchange-011"},{"speaker":"山元委員","kind":"質問・要望","question":"もう一つは観光資源ですけれども、今、石田委員もおっしゃっていて、本当に開催されるところでやはりそういうものをやっていただきたいと思うのと同時に、あと一つここで聞きたいのは、区内大使館の協力の国際ＰＲのブースとか商店街の模擬店というのは、同時ではなくて、日にちを変えた開催というか、どういうふうにやるのか教えていただきたいのと、それから、特にこの模擬店等には。","respondent":"安藤文化スポーツ振興課長兼オリンピック・パラリンピック推進担当課長、米田商業・観光課長","answer":"そういうものも一から設計していかなくてはいけないという部分。それと、あとは温水プールも特定天井に当たるということで、温水プールのほうもあわせて設計を委託ということで含めさせていただいてあります。いわゆるイベントの一つの盛り上げということで、さまざまなところがやはりこのオリンピック・パラリンピックの歓迎の機運があるよということで、この辺の各団体については今後の調整というようなことになってまいりますので。","id":"exchange-012"},{"speaker":"藤原委員","kind":"質問","question":"細かく伺いますが、まず、日本の伝統文化・おもてなしの国際交流で、節分の豆まきをやるということですが、節分に豆をまくというのを伝統文化としているわけですから、その起源を把握しておかないといけないと思うのですが、節分に豆をまく起源を教えてださい。","respondent":"寺嶋協働・国際担当課長","answer":"この予算案の計上に当たりまして、いろいろ調べましたけれども、諸説あるということで、具体的に何年のいつごろからということではないのですけれども、いわゆる陰陽、占いみたいというとちょっと語弊があるかもしれませんけれども、あれに基づいておりまして。","id":"exchange-013"},{"speaker":"藤原委員","kind":"提案","question":"大井町でビーチバレーをするというご提案が出ていますけれども、これは先ほども少し課長から出ていましたけれども、２０２０年にどう結びついていくのですか。今、これをやることが、２０２０年のオリンピック・パラリンピックに具体的にどういう効果のためにやるのかというのは、区が予算をつけるわけですから押さえておかないといけない。なっているかもしれないし、ならないかもしれない。","respondent":"米田商業・観光課長、安藤文化スポーツ振興課長兼オリンピック・パラリンピック推進担当課長","answer":"今後もこの実施を踏まえて、いわゆる商業ですとか、あるいは観光の部門の関係、あるいはそれ以外のところで、どのようなオリンピック・パラリンピックに向けた、いわゆる外国人の方、それから国内の方の受け入れの醸成について。しかし、区としては私が務めします職務については、行政の継続性と申しましょうか、しっかり後進にバトンタッチをしていきながら進めていきたいと考えています。","id":"exchange-014"},{"speaker":"吉田委員","kind":"意見","question":"おもてなしの国際交流のところで、予算のところにガイド通訳要員とかありますし、例えばそういった商店街の活性化のパンフレット等も英語でつくるというお話だったのですけれども、この間、外国からいらっしゃる方のアンケートがありまして、一番困るのが日本に来て言葉が通じない、英語で話かけても皆様わからなくて、買い物もままならないという話があったのですけれども。","respondent":"寺嶋協働・国際担当課長、米田商業・観光課長","answer":"これは専門的なその部分の通訳等、保険をかけてという意味ではないのですけれども、専門の方を１名と２名を配置するとありますけれども、ご質問の趣旨については、これは１つの事業としてはやりますけれども。あと、全体的には今後の話になってくると思いますけれども、いわゆる指さしである程度翻訳できるような、「これ下さい」というのが外国語で書いてあり、日本語に訳したものが並列してあるというようなもので。","id":"exchange-015"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"おもてなしのところで、品川神社が候補に挙がっていますけれども、その理由を教えていただきたいのと、要望ですけれども、２０２０年までに、例えばこういった事業をぜひボランティアで、そういった子たちが、２０２０年に本当に開催するときにその子たちがボランティアとして活躍できるように、その辺、こういった事業からボランティアの獲得といった連携というのは。","respondent":"寺嶋協働・国際担当課長","answer":"このエリアが北品川だけというのはそういう意味でありまして、まずそこを今回、そこで活動されている方たちを中心に、比較的得意な分野においてやっていただくというのが、今回ですけれども、これは７年間ありますので、ある意味モデル的になってしまうのですが。","id":"exchange-016"},{"speaker":"鈴木（真）委員","kind":"質問","question":"そういうものは考えているのでしょうか。それとも、それでは対象にならないのかどうか、そこら辺をまず１点目にお聞きしたいと思います。その効果というものは、区としてどういうふうに検証なさっているのか、それをまず教えていただけますか。","respondent":"寺嶋協働・国際担当課長、米田商業・観光課長","answer":"そういった場合には、おそらく補助金対象になるであろうということは、今後の検討委員会の結果を踏まえてですけれども、ある程度想定がつく分ですが、こういった気運醸成とかで。機内情報誌の関係のいわゆる効果ですけれども、こちらについては、やはり写真を伴って見せることに対して、特に外国の方への影響というのはある程度あり得るということで、特にそれがその外国の方が日本に求めるものと合っている場合。","id":"exchange-017"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"財調の関係は担当が違うので、非常に答えにくいと思いますけれども、ただ、さっき課長も話していたように、２３区統一しないと要望が通らないかもしれないので、ぜひ品川区としては持っていけるように各部署からも努力していただきたいということを一つ、これは要望します。それから、例えば羽田空港の観光案内所だと。そこら辺を考えると、何で恵方巻きが競って出てくるのか、ちょっとそこら辺だけ確認を。","respondent":"寺嶋協働・国際担当課長、中川原地域振興事業部長","answer":"ただ、もうここ１０年弱ぐらいになると思うのですが、ある意味商業ベースでもありますけれども、東京のほうの各コンビニエンスストア等々で入ってきて、結果的にある程度、まだ全国規模になったとは言いませんけれども。申請する期間が短かったこともあり、すみません、考える時間が少なかったということで、それなりに頑張りましたけれども、ただ、オリンピック・パラリンピックは７年といっても非常に早く過ぎるし、今、私たちが説明したことは。","id":"exchange-018"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"部長の、随分よくわかりました。その中で、ちょっと繰り返しになってしまいますけれども、品川区としての財源として、やはりこれからずっとやっていくと、一般財源の中でどこまで持ちこたえられるかというのもあるから、その辺は財源を確保できる形、当然交付金は交付金でもらうとしても、別の形もいろいろ考えておいていただきたいと、これは要望しておきます。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/972690?Template=document&Id=2682#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":28293,"voices":70}},{"id":"h25-20131125-7","meetingId":"h25-cm11","date":"2013年11月25日","dateIso":"2013-11-25","committee":"厚生委員会","time":"午前１０時００分～午後２時３１分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を86件抜き出しています。","topics":[{"id":"topic-01","title":"はじめに、(1)の第６７号議案、品川介護福祉専門学校修学資金貸付条例の一部を改正する条例","agenda":"はじめに、(1)の第６７号議案、品川介護福祉専門学校修学資金貸付条例の一部を改正する条例","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"幾つか、お伺いをしたいと思います。一つ目が、修学資金の貸付けなんですけれども、現状、どのぐらいの方が、何％ぐらいの方が利用されているのかということ。それから、条件の中に、休学、または停学による修学資金の貸付けの停止ということなんですけれども、これは現状、どれぐらい発生をしているのか、教えてください。","respondent":"永尾高齢者福祉課長","answer":"休学等により停止になった場合につきましては、毎年１名から２名というような割合になっており、少人数ということで推移しています。","id":"exchange-001"},{"speaker":"あくつ委員","kind":"質問","question":"８９.４％の方が利用されているということで、非常に利用率も高いし、この事業自体、品川区にとっての介護行政のための非常に必要な事業だと思いますので、ありがたい制度だなと思います。今回の条文の中に、第１６条、区長が特別な理由があると認めたときは、当該延滞金を免除するという免除規定がありますけれども、特別な理由というのは、どういったものを想定されていらっしゃるんでしょうか。","respondent":"永尾高齢者福祉課長","answer":"そういうことも考えますと、一律に延滞金を取るということは、本人の今後の生活に対しても非常に苦しい部分が出てきますので、返済の方法なども相談しながら、その状況に合わせて延滞金を免除するとしています。","id":"exchange-002"},{"speaker":"井上委員","kind":"質問","question":"この専門学校が設立された経緯と、それからこの事業についてなんですが、専門学校を運営していくうえに、区が支出している経費と、補助金などが充てられているのかどうか、ちょっと大きなところで質問させてください。","respondent":"永尾高齢者福祉課長","answer":"品川介護福祉専門学校への助成につきましては、今、ご説明いたしました状況を踏まえますと、やはり区のほうで人件費、運営費の助成等が必要だというところで、３,０００万円を、人件費、運営費の助成に充てております。","id":"exchange-003"},{"speaker":"井上委員","kind":"質問","question":"今おっしゃった介護福祉士の取得ということなんですが、ほかにこの専門学校で資格取得ができるものがあるんでしょうか。","respondent":"永尾高齢者福祉課長","answer":"この介護福祉専門学校で受ける資格というのは介護福祉士なんですけれども、こちらの学校の講師や、いろいろな設備も活用するということで、社会福祉士の養成コースという通信制の講座もやっているところです。","id":"exchange-004"},{"speaker":"井上委員","kind":"質問","question":"社会福祉士の通信の講座というのは、今までの３,０００万円とか、そういったところの費用とは別のものでされているのか。それから、同程度の資格を取れる学校として、今、ほかの専門学校やたくさん養成講座があるんですけれども、その中で、授業料としては、今回値上げをして１４０万円ということなんですが、高いのか、同程度なのか、そういったところはいかがでしょうか。","respondent":"永尾高齢者福祉課長","answer":"１４０万円の授業料の件ですけれども、他の学校の資料等は、ちょっと手持ちはないんですけれども、土地代、建物代は区のほうで助成しておりますので、ほかのところに比べれば随分安い金額になっているかと考えています。","id":"exchange-005"},{"speaker":"井上委員","kind":"質問","question":"事務事業概要では、在籍数のみなんですけれども、願書受付人数、試験を受けられる方たちがどのぐらいいて、以前も入学者数、在籍者数が少ないというような指摘があって、随分努力されて、平成２４年度実績では、定員８０名のところを７４名となっているんですけれども、そして３回ほど受験をされているようですが、どのぐらいの方が入学試験をされて、この在籍人数になっているのか、教えてください。","respondent":"永尾高齢者福祉課長","answer":"設立当初は、かなり応募の方がいらっしゃいまして、４０名のところ、１００名を超えたというような話は聞いておりますけれども、ここ五、六年の間は、なかなか希望される方がいらっしゃらなくて、介護福祉専門学校のほうでも、各高校を回ったり。","id":"exchange-006"},{"speaker":"井上委員","kind":"質問","question":"貸付けの返済者割合と、免除になった方たちは、品川区の事業所で３年間働かれた方というふうに思うんですけれども、そうでない、先ほどの返済者の割合ですよね。決算書では、１,６００万円ほどの返還金が毎年計上されているように思うんですけれども、そうすると、貸付けを受けて、品川区内の施設に就労されなかったという方になると思うんですが、どのぐらいの推移で行かれているんでしょうか。","respondent":"永尾高齢者福祉課長","answer":"返還する場合なんですけれども、１回はそこの指定施設に入っても、その後に、３年たたないうちに辞めてしまったり、ちょっと精神的なことでほかの施設に移ったりという方もいらっしゃいますので、途中の方も何名か入るというような形になっております。","id":"exchange-007"},{"speaker":"井上委員","kind":"意見","question":"今、ちょっと答弁をいただいたんですけれども、免除者の中で、３年に満たなかった方たちは返済をされているということになると思うんですけれども、大きな授業料の負担を、区がしているので、３年以降の定着率というのも押さえておかないといけないと思うんですけれども、先ほどの数名ということではなくて、きちんと実際の状況をお知らせください。","respondent":"永尾高齢者福祉課長","answer":"実際に学校の卒業生で、思ったよりも大変だとか、人間関係が難しいとか、いろいろなところで、卒業した後もご相談に見えていて、教務の先生方がいつも丁寧に対応をしながらつなげていたりというような状況は、現実としてあります。","id":"exchange-008"},{"speaker":"井上委員","kind":"質問","question":"３年間そこで働けば免除になるわけで、その先、いかに定着支援をしていくかということで、継続するのはすごく大変で、やっとの思いで３年間というのは、心情的にもわかるし、そういう職場だと思うんですけれども、とにかく３年勤めれば、授業料免除になるからそれでいいというふうにならないように、職場のほうの定着支援もしなきゃいけないんですが、その辺のデータをちゃんと押さえていますか。","respondent":"永尾高齢者福祉課長","answer":"実際の数字について、今は手元に用意されていませんけれども、３年我慢をして続けると、結構職場の中でも、実務者の中心的な存在になりますので、そのまま継続されるというケースが多いかと考えています。","id":"exchange-009"},{"speaker":"井上委員","kind":"質問","question":"そこの部分については、非常勤の人たちの中で、正規で頑張り通すってすごく大変だと思って、逆に責任が重くなってしまうという方たちもいるので、その辺は、学校のほうでもお願いしたいと思います。貸付け申請の審査の内容については、どんな条件があるのかということと、今まで、貸付けが認められなかったケースというのは、どういったものがあるんでしょうか。","respondent":"永尾高齢者福祉課長","answer":"継続して貸付金を受けるためには、ある程度学業のほうをきちんとやっていただく必要がありますので、例えば、入学した前期については、条件についての審査になりますけれども、後期分につきましては、科目で落ちているものがないかとか、その方の欠席、出席状況とか。","id":"exchange-010"},{"speaker":"井上委員","kind":"質問","question":"今、お伺いしていると、授業料が全額貸付けで、３年勤めれば返済免除という、ほかの貸付けに比べれば大変好条件で、なおかつ、先ほどほかのところの授業料のところでお伺いしたんですが、少し調べたら、やっぱり１年間で１００万円とか、もっと高い。通信教育ではあるけれどもというところで、資格取得の数が少ないというところでの人気がどうかと、私個人的には思うんです。","respondent":"永尾高齢者福祉課長","answer":"各学校を回ってみると、学校のほうも、大学に何名進学したというような名前で子どもたちを集めているところもありますので、そういうところで専門学校がちょっと苦戦してしまうのかなと思っているところです。","id":"exchange-011"},{"speaker":"井上委員","kind":"質問","question":"そうすると、区が介護福祉士の養成事業に取り組んでいくということについて、長期的に何かお考えがありますでしょうか。","respondent":"永尾高齢者福祉課長","answer":"今後ですけれども、介護福祉士の資格の取得についての改正なども控えておりますので、また介護保険法の改正などもあります。そういうものも踏まえながら、どういうふうに人材を育成していくかということは、今後、検討していきたいと考えております。","id":"exchange-012"},{"speaker":"井上委員","kind":"質問","question":"そこのところについては、これだけ見たら、何だという話だと思うんですけれども、そこについては、何か検討とか、お考え、説明とか、どういうふうに考えているんでしょうか。","respondent":"永尾高齢者福祉課長","answer":"ただ、この１４０万円を２４で割ると割り切れないということもございまして、そしてまた貸付け自体も、前期と後期で貸付けをしているという現状がありますので、月額という表現ではなくて、総トータルの金額という表現に、今回、変更をいたしました。","id":"exchange-013"},{"speaker":"たけうち委員","kind":"質問・要望","question":"先ほど来、いろいろ質疑があって、区内の社会福祉法人等で３年間勤務されない方が意外と少ないんですけれども、その中で、返還できなくて、実際の滞納率というんですか、それを教えていただきたいんです。","respondent":"永尾高齢者福祉課長","answer":"平成２４年度までの対象の方で、収納されていない方は、人数といたしましては、現在、５人になっています。それにつきましては、分割の申込み等を５人ともがしています。","id":"exchange-014"},{"speaker":"渡部委員","kind":"質問","question":"幾つか教えてください。基本的には、在学される方はみんな、この貸付けを希望されて入ってくるのかが、まず１点。それから、専門学校ですから、高校新卒に限らず、１回社会に出られてから入ってくる方とか、逆に、大学を卒業された後にまた入る方とか、どれぐらいいらっしゃるのか、その辺の割合がもしわかれば教えてほしいというのが１点。","respondent":"永尾高齢者福祉課長","answer":"入学生のうち、貸付けをする人数ですけれども、例えば平成２３年でいけば、４０名の入学者のうち３８名が貸付け、平成２４年は４０名のうち３７名、平成２５年は３５名のうちを２８名となっています。","id":"exchange-015"},{"speaker":"渡部委員","kind":"質問","question":"最初の質問はわかりました。ということは、毎年２名から何名かの方は、はなから奨学金、３年働いて免除になるということを何も当てにせず、自費で純粋に品川区の介護福祉専門学校に来ようとされている方なんですか。それとも、申請はされているけれども、先ほどの何かの理由で落されている方なんですか。","respondent":"永尾高齢者福祉課長","answer":"最初から当てにしないで入っている方がほとんどです。もともと田舎に帰ってやりたいという方だとか、資格は取るけれども、縛られるのはちょっとというような方が多いと考えています。","id":"exchange-016"},{"speaker":"渡部委員","kind":"質問","question":"最後に、品川区の指定福祉施設というのは、考え方としては、どこがどこがというよりも、品川区内で働いてもらう分には、これは３年間働いていただくと、ほぼ免除になるという考えでいいんでしょうか。","respondent":"永尾高齢者福祉課長","answer":"基本的には、品川区の事業所で働いていただく方は、３年間で免除という考え方をとっております。","id":"exchange-017"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"授業料が１２０万円から１４０万円に引き上げられることに伴っての貸付け額を引き上げるというところで、そもそも授業料が引き上がる理由を教えてください。","respondent":"永尾高齢者福祉課長","answer":"痰吸引等の医療ケアというのがそこにまたさらに追加されますので、教育課程が変更になります。それに伴いまして、教育の内容もかなり充実した内容になりますので、授業料のほうも、それに合わせて上げていくところです。","id":"exchange-018"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"そうすると、授業内容が充実というのは、教員の態勢とか、授業でいう材料とか、そういったものが変わってくるということなんでしょうか。","respondent":"永尾高齢者福祉課長","answer":"医療ケアを行うことになりますと、吸引シミュレータだとか、経管栄養シミュレータとか、そういう整備も必要になるということがあります。それでまた、指導に関しても、それなりの教員が必要というところで、授業料についても値上げをすることになりました。","id":"exchange-019"},{"speaker":"井上委員","kind":"質問","question":"先ほど、区内事業者に就職すれば大丈夫ということだったんですが、今まで、区内であるにもかかわらず、免除にならなかった要件とか、ケースはあったのでしょうか。","respondent":"永尾高齢者福祉課長","answer":"こちらのほうでは、学校からそういうケースというのは、具体的には聞いておりません。","id":"exchange-020"},{"speaker":"井上委員","kind":"質問・要望","question":"それはそれでオーケーなら、それはそれで結構なんですが、いかがでしょうか。","respondent":"永尾高齢者福祉課長","answer":"就職先につきましては、介護福祉専門学校と区とが連携を密にしておりますので、その中で、そういうお声があれば指定施設にするかどうかという検討をしていきたいと考えています。","id":"exchange-021"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"先ほど、卒業と同時に国家試験を受ける資格が得られるということで、そうすると、国家試験にもし落ちてしまって介護福祉士になれなかった場合は、どうなってくるんでしょうか。","respondent":"永尾高齢者福祉課長","answer":"その部分が非常に、学校のほうも苦慮しているところで、国家試験に合格できるような学生の育成をしなければいけないというところで、問題意識を持っているところです。ただ、国家試験に合格しなければ、当然のことながら介護福祉士にはなれないということになります。","id":"exchange-022"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"そうすると、貸付けを受けても、３年間福祉士として働けないということになるんですよね。そうすると、打ち切りになるということなんでしょうか。","respondent":"永尾高齢者福祉課長","answer":"現状の制度でいくと、そういう考え方もとれると思うんですけれども、ただその国家試験の内容だとか、合格率とか、そういうものがまだやっていなくてわからないことがありますので、平成２６年度から入学される方は２年間ありますので、その間に情報を収集して。","id":"exchange-023"},{"speaker":"井上委員","kind":"意見","question":"賛成なんですけれども、一言意見を述べたいと思います。先ほどの、３回試験をするにも定員がなかなか集まらないというところの原因をしっかりと把握して、対策をとっていただくこと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"私も賛成ですけれども、一言。１年１０万円、２年で２０万円の値上げというところでは、これは区が負担してもいいのではないかと思うんです。さらに国家試験にもし落ちてしまったらというところでも、そういったリスクを考えると、さらに入学生も集まりづらくなるのかなという危惧もありますので、生徒への負担軽減というのは、さらにちょっと検討していただきたいということを含めて、賛成をします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"}]},{"id":"topic-02","title":"の第６８号議案、品川区立在宅サービスセンター条例の一部を改正する条例","agenda":"の第６８号議案、品川区立在宅サービスセンター条例の一部を改正する条例","exchanges":[{"speaker":"井上委員","kind":"質問","question":"在宅サービスセンターなんですけれども、今回、認知症の通所が２階にできるということで、これは今まで北品川でも、同一のサービスが行われていたものなのか、新規のものなのか。それから、北品川サービスセンターで行われていた方たちの定員みたいなところは、どのぐらい拡大されると考えられるのでしょうか。","respondent":"永尾高齢者福祉課長","answer":"認知症の部分ですけれども、今回の移転に伴いまして、面積が広がるということで、新たに始めるものです。これまでやっていたサービスセンターの定員に変更はございません。定員３５名ということです。","id":"exchange-026"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"今、広くなるということだったんですけれども、広くなったことで、かかる経費が増えてくるとかはあるんでしょうか。それから、これを建設するにあたって、こういった形に建設してほしいと、区も一緒に入られたのでしょうか。","respondent":"永尾高齢者福祉課長","answer":"この建設にあたりまして、レイアウト等につきましては、品川区と、指定管理者である福栄会と協議しまして、使い勝手のよい形でレイアウトを考えているところです。","id":"exchange-027"}]},{"id":"topic-03","title":"の第７３号議案、指定管理者の指定","agenda":"の第７３号議案、指定管理者の指定","exchanges":[{"speaker":"井上委員","kind":"質問・要望","question":"東大井の部分では、通いと、泊まりと、グループホームと、ケアホームになっているんですけれども、ここの部分では訪問介護というのは入らない仕組みなんでしょうか。すみません、小規模とちょっと理解をしていないので、そこの説明をお願いしたいと思います。","respondent":"永尾高齢者福祉課長","answer":"こちらの東大井地域密着型多機能ホームにつきましては、協議会は特に設置しておりません。訪問介護についても、地域密着型多機能ホームでは設置の義務は、特にございません。","id":"exchange-028"},{"speaker":"井上委員","kind":"質問","question":"前回、モニタリングの資料をいただいたときに、１年未満での退職者が多く、職員の定着等、人員不足について早急に改善が必要であるという指摘に対して、今回、指定にあたって、それはどのような改正で、評価をすると選定したんでしょうか。","respondent":"永尾高齢者福祉課長","answer":"事業系別プロセスごとの研修として、基礎課程の研修だとか、入居系の職員の現任研修だとか、そのほかに東大井多機能ホーム独自の研修や勉強会を実施しているという実績があります。","id":"exchange-029"},{"speaker":"井上委員","kind":"質問","question":"指定管理の再委託についてなんですけれども、食事の部分が再委託先というふうに、前回のモニタリングのところに表記をされているんですが、どの程度の再委託が認められるのかということ。こういった部分で、万が一食中毒とか、そういった問題が発生したときに、ここはどういうふうなルールをもって責任が発生するように、仕組みとしてなっているんでしょうか。","respondent":"永尾高齢者福祉課長","answer":"給食とか、清掃については、再委託をしています。こちらには、看護師が常勤換算で２名いますので、万が一の場合には、看護師の対応も可能です。ただ、そういうことが起こらないようにということで、施設内でのマニュアルもつくっているのを確認しています。","id":"exchange-030"},{"speaker":"井上委員","kind":"質問・要望","question":"指定管理の事業者に言っても、自分はお世話になっている身だから、ということもあるんですが、そういったときの窓口を整備をしているのか。そしてそれをちゃんと利用者のところに、口頭だけではなく、文書とか、そういったもので、そういったときには、ここを通してこういう救済の仕組みがありますという制度は、ちゃんと整えてあるんでしょうか。","respondent":"永尾高齢者福祉課長","answer":"区では、事故に起こったことに対しては、事故報告書というのを常にいただいており、内部での確認をきちんとしています。第三者評価も実施しております。その中で、そういう報告があれば、区のほうでも実際に実地指導等を行っているところです。","id":"exchange-031"},{"speaker":"あくつ委員","kind":"質問・要望","question":"事故の報告の件数が多いとか、少ないとか、そういったものは、これは高齢者ですから、当然起こり得ることだと、私も思いますし、絶対というのはなかなか難しいのかなと思うんですけれども、極端な話をしますと、高齢者の施設で、介護をする方によってお亡くなりになる方が非常に多いような事件、たまに逮捕されたりする事件がありますけれども、自治体が絡んでいるかどうかは、また別として。","respondent":"永尾高齢者福祉課長","answer":"ただ、事故報告が上がってきたときに、その原因だとか、その後の対応だとか、そういうところをきちんと注意をして、迅速な対応ができていないようであれば、区も事業者を呼び出して指導する等の措置をとっているところです。","id":"exchange-032"},{"speaker":"たけうち委員","kind":"質問","question":"社会福祉法人ではなくて株式会社ということで、株式会社ならではメリット、デメリットとか、何か区のほうでお気づきのことがあったら、なければいいんですけれども、特徴的なものがあれば教えてください。","respondent":"永尾高齢者福祉課長","answer":"基本的には、やっぱりさまざまな担い手が福祉を支えているというような現状ですので、その施設のよさが、事業者として生かせるかというところが重要だと考えています。","id":"exchange-033"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"この多機能ホームの職員数は、皆さん正規職員なのか、そこの正規率、またこの間、離職率なんかもわかれば伺いたいんですけれども。","respondent":"永尾高齢者福祉課長","answer":"先ほどのご質問にもございましたとおり、施設内の研修会、勉強会は、月１回重視して行っているということで、施設長みずからが意見を聞きながら、介護職の離職につながらないようなご相談を受けているというような状況になっております。","id":"exchange-034"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"そうすると、常勤の部分を教えていただいたんですけれども、非常勤数というのはどうなってくるのか、ちょっとわからなかったので、わかれば教えてください。離職率が、ここ２年ほど多かったというところでの、離職の理由というのはわかっているのでしょうか。","respondent":"永尾高齢者福祉課長","answer":"事業の中身の説明だとか、そのほか、処遇についてもちゃんと説明をしたうえで適任を選択すればよかったという声を聞いているところです。","id":"exchange-035"},{"speaker":"渡部委員","kind":"質問","question":"今回、指定管理の議案が多数出ておりますけれども、全体に係わる質問なんですけれども、いいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"渡部委員","kind":"質問","question":"全体的な話をお伺いしたいんですけれども、指定管理をされる場合、特に今回新たにではなくて、継続してされる場合に、どのようなときに、いわゆる継続性を重んじる、どのようなときに新規にプロポーザルをかけるのか、仕組みがどのようになっているのか。これの構成員がどのような形で、例えば、これはこういうところに係るから、こういう選び方をするみたいな、何か基準があれば教えてほしいと思います。","respondent":"永尾高齢者福祉課長、中山障害者福祉課長","answer":"それからまた、安全で安定した運営をするというところを考えますと、やはり、公募ではなくて選定をするということが適しているのかと思います。第７７号議案につきましては、健康センターのほうになります。私のほうから、第７５、第７６号議案に企画部が入っていないのではないかということについて、お答えいたします。","id":"exchange-037"},{"speaker":"井上委員","kind":"質問・要望","question":"賛成です。一言意見を追加したいと思います。先ほどの事故についての問題なんですけれども、事故の報告書を上げてもらって、第三者評価もあるということだったんですが、課長の答弁で、この施設は最終的には区の施設だから、区に責任が発生をするというようなところで、区に改善を求めるという部署が、今ないわけですよね。やはり、事業者も、第三者評価も、設置者である区も、やっぱり身内なんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"共産党は反対です。ですので、そういったところが保証されていない、そして５年間という短い期間の更新だったりすれば、やはり正規社員が、人材育成として、公共施設の職員としての自覚や専門性が身につかない、なかなか難しいのではないかとも感じますので、やはりこういった福祉施設に株式会社はなじまないと、引き続き反対をいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"}]},{"id":"topic-04","title":"の第７４号議案、指定管理者の指定","agenda":"の第７４号議案、指定管理者の指定","exchanges":[{"speaker":"井上委員","kind":"意見","question":"ここの部分で、障害者の居場所というか、その支援と、障害者生活支援センター、基幹相談支援センターということで、ここにはあるんですけれども、そこの指定管理者として品川総合福祉センターなんですが、今いろいろ制度が変わっているんですけれども、具体的にこの中で、事業として指定管理に任せている業種というのを、全て挙げていただけたいと思います。","respondent":"中山障害者福祉課長","answer":"３点目が地域活動支援センターということで、こちらＩ型なんですけれども、さまざまなボランティアの活用も行いながら、障害程度区分にかかわらず、趣味ですとか、創作活動、あるいはさまざまな教室などを行っているところです。","id":"exchange-040"},{"speaker":"井上委員","kind":"質問","question":"最後の生活支援センターの中で、まずここが基幹相談支援センターということで位置づけているのではないかと思うんですが、そこはどのようになっているのでしょうか。","respondent":"中山障害者福祉課長","answer":"ここを中心に、地域の相談支援センターということで、こちらの会館にあります障害者生活支援センターのほか、精神のほうの支援センターたいむ、それからこの４月から福栄会のほうに新たに障害者相談支援センターを開設したということになっております。","id":"exchange-041"},{"speaker":"井上委員","kind":"質問・要望","question":"ここだと、品川総合福祉センターを利用している人たちのことはよくわかるんですけれども、そういう要望があったんですが、そういったことについては、区のほうに言うのか。一法人への相談みたいになることに、ほかの法人を使っている利用者はなかなか相談がしにくいという声に対しての問題意識というのはあるのでしょうか。","respondent":"中山障害者福祉課長","answer":"そこは三つの相談支援センター、それから区の基幹型と入りまして、相談のレベルアップだけではなく、事業者間の情報収集などというものも行っておりますので、その機能を活用しながら、利用者のお声をできるだけ細かく聞いていくような体制に努めていきたいと考えています。","id":"exchange-042"},{"speaker":"井上委員","kind":"意見","question":"やっぱりたいむでいけば、福栄会が基本相談とか、計画相談とか、法人が品福と、福栄会等とか、そうではないところを利用される方々もいますので、やはり自分が利用しているところではないところの情報が共有されることも必要だし、本人ではなくて、家族もいろいろなところがわかって、なおかつ選考できるとか、先ほど、そういう状況にないように努められていますというでしたが。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"},{"speaker":"あくつ委員","kind":"提案","question":"Ｂ型では、水耕栽培事業をモデルとし、ブランチ型ファームを関連機関に置き、ＩＴ（パソコン）による生産管理を行う、とあるんですけれども、これは、これまでの実績を生かし、地域の企業とのつながりを強みとして事業提案されている、とあるんですけれども、これは、今までも実績としてやられていることなのか、その辺について教えていただきたいと思います。","respondent":"中山障害者福祉課長","answer":"この間、げんきのほうでも、区内企業といろいろご相談する中で、株式会社ミウラのほうで既にやられている書類や図面の電子化サービスについて、業務を請け負うような形で実施ができるという運びになっているものです。","id":"exchange-044"},{"speaker":"あくつ委員","kind":"質問・要望","question":"新しい試みということなんですけれども、Ｂ型のほうもどういう内容なのか、もう少し詳しく教えていただければと思います。水耕栽培事業って、この前も厚生委員会で視察したところでも、ちょうどやっていたんですけれども、そういうものか、ちょっとこの辺も詳しく事業内容をご説明していただきたいと思います。","respondent":"中山障害者福祉課長","answer":"そのための練習として、あそこの地下に倉庫がありますので、倉庫でもそういった管理ができればというような中身のお話です。","id":"exchange-045"},{"speaker":"井上委員","kind":"質問","question":"この公開プロポーザルなんですけれども、９月１３日から２５日ということだったんですが、他の案件では、公開プロポーザルの期間はどのぐらい取っているのかについて、教えてください。","respondent":"中山障害者福祉課長","answer":"恐らく高齢者の施設なんかですと、建設とセットになっているので、これよりは期間が長いかと思われます。こちらのほうは、もう既に施設があるところに事業の中身だけの提案ということでしたので、この期間で設定をさせていただいたところです。","id":"exchange-046"},{"speaker":"井上委員","kind":"質問","question":"これから出る健康センターなんかは、１カ月ぐらいちゃんと公開プロポーザルをしているという意味では、２週間に満たない募集というのは、私は短か過ぎると思っています。そんなに短くならなければならなかった理由と、この募集期間が短か過ぎることによって応募件数が１件になってしまったというような影響があったか、どうかについて、お伺いします。","respondent":"中山障害者福祉課長","answer":"１者の提案しかなかったということにつきましては、この募集要綱の期間の短さということはあるかもしれませんが、やはり就労継続Ａ型事業の提案というのが、非常にハードルが高かったのかなと感じているところです。","id":"exchange-047"},{"speaker":"井上委員","kind":"質問","question":"ここには、ホームページへの掲載と書かれていまして、やはり公開プロポーザルをするにあたっては、発達障害で、既に他の自治体などで発達支援センターを運営しているところからとか、いろいろな情報はあると思うので、そういったところに働きかけはしなかったのかどうか。ただ、ホームページに書いて待たれていただけなのか、その辺を教えてください。","respondent":"中山障害者福祉課長","answer":"こういう事業を品川区がやりますということにつきましては、特に具体的な話はしておりませんけれども、区内の法人をはじめ、発達障害の支援をしているような、ちょっと今名前がすぐに出てこないんですが、そういったところの事業者から問い合わせがあったときにも。","id":"exchange-048"},{"speaker":"井上委員","kind":"提案","question":"指定管理者制度活用に係る基本方針の中では、公開プロポーザル方式など、複数の事業者から提案を受けることを原則するというふうにありますよね。そこについて、どのようにお考えでしょうか。","respondent":"中山障害者福祉課長","answer":"当然、１者だからそこしかないだろうという考え方でないのはもちろんです。なので、審査におきましては、シビアな視点でしっかりと審査をさせていただいたところです。","id":"exchange-049"},{"speaker":"井上委員","kind":"質問","question":"シビアに審査をしたということなので、お伺いをしたいのですけれども、第３回定例会で可決いたしました発達障害支援施設設置条例の指定管理者の指定手続第１０条第２項の２に、支援施設の適切な維持および管理ならびに管理に係る経費の縮減を図る、というふうに書かれていますけれども、比較対象がない中で、経費の縮減というのはどういうふうに判断をしたのでしょうか。","respondent":"中山障害者福祉課長","answer":"今までの法人が運営している事業所の経費節減もそうですし、今回の提案の中では、人材確保のところについては、積極的に人材を充てていくという姿勢が見られているんですけれども、通常の運営費に当たります、例えば光熱水費ですとか、その他維持管理については。","id":"exchange-050"},{"speaker":"井上委員","kind":"提案","question":"それはそうでしょうと思うんですけれども、そういったところで、地域との連携を円滑にするというようなこととか、縮減というのが、区がこのぐらいと想定していることに対して、こういう提案がありましたとか、そういう協議の場での議論なのか、何か言われたとおりで全然見えないんですけれども、そこら辺がどうなんでしょう。","respondent":"中山障害者福祉課長","answer":"プロポーザルの中で審査した項目としましては、プログラムの有効性、それから運営の確実性、連携と協働の視点、これが発達障害者支援施設のほうで、その視点でチェックいたしました。グループホームの運営についても、同様です。","id":"exchange-051"},{"speaker":"井上委員","kind":"質問","question":"それからまた、人材確保、ここのスタッフ構成は、多分グループホームのほうは管理人が一人というような態勢でいくのかもしれないんですが、両者のスタッフは、何人でこの事業を遂行していくのかというところは、どのように審査をされて、結果がどうなっているのでしょうか。","respondent":"中山障害者福祉課長","answer":"下の就労支援施設は、４人ないし５人常時職員がいるような形になります。それから、２階の成人のサロンのところになりますが、こちらのほうに心理職、それから社会福祉士の資格を持つ者を３名、採用しています。その人員配置に合わせまして、この間、かなり研修をやっています。","id":"exchange-052"},{"speaker":"井上委員","kind":"質問","question":"ちみなに、法人のげんきは、就労支援センターで５人のスタッフで事業が行われているんですけれども、これは全然別の形で、こちらの施設で、今言われたのは７名ですけれども、７名のスタッフが確保されて進められるということなのか。その就労支援センターのほうとの関係は、どうなっているのでしょうか。","respondent":"中山障害者福祉課長","answer":"就労支援センターのほうの職員はそのままです。そこの職員がこちらに来るということはありません。それから、こちらの法人のほうで、ほかの関連するＮＰＯのぴゅあサポートの事業のほうからお一人、こちらのほうに来るということは聞いております。","id":"exchange-053"},{"speaker":"井上委員","kind":"質問","question":"発達障害施設の施設長は、どのような方がなられるのかということ。それから、げんきが就労支援センターで、法人化前にＮＰＯのぴゅあサポートが、就労支援センターということではなくても、相談とか、訓練などが、対象者が長らく愛の手帳を持つ知的障害者に限定されていましたけれども、いつから、手帳を持たない人たちに利用が拡大されてきたのか、教えてください。","respondent":"中山障害者福祉課長","answer":"法人げんきのほうで、就労の相談、就労支援事業のところで長らく知的障害の人中心だったということなんですけれども、昨年度以降、精神障害、身体障害、そういった方たちの受け入れも行っているところです。","id":"exchange-054"},{"speaker":"井上委員","kind":"質問","question":"社会福祉法人げんきに委託をして、指定管理にするのに、ＮＰＯのぴゅあサポートの方が施設長という、その関係は少しおかしいのかなと思うんです。その方が法人のスタッフになって、そういう形をとるということですか。","respondent":"中山障害者福祉課長","answer":"すみません、表現が悪くて申しわけありません。法人げんきの職員が、そこの施設長になるということになります。それから、手帳のない方にも支援が広がったのはいつからかというのは、先ほどの平成２４年度からということになっております。","id":"exchange-055"},{"speaker":"井上委員","kind":"質問","question":"今回は、発達障害の支援施設ということで、平成２５年度の社会福祉法人げんきの発達障害者の就労支援施設なんだけれども、事業継続Ａ、Ｂということは、就労支援という形なんだろうと思うんですけれど、就労支援の、発達障害者の実績はどのぐらいあるのでしょうか。","respondent":"中山障害者福祉課長","answer":"ただ、先日、ご視察いただいたセンターの工夫の中でも、実はその方は知的障害の手帳をお持ちの方でしたけれども、独自の作業工程の工夫ですとか、プログラムの工夫をすることで、発達障害への対応をしているところは、ご視察いただけたのかなと思っているところです。","id":"exchange-056"},{"speaker":"井上委員","kind":"意見","question":"目的は、発達障害者の自立および社会参加に資する支援を行うことにより、発達障害者の福祉の増進を図る、というところで、発達障害の支援をされてきたというところが、これからの分野でもあるので、非常に難しいと思うんですけれども、ここはどういうふうな能力を有しているからということで決められたのか、ちょっと肝だと思うんですが、説明をお願いしたいと思います。","respondent":"中山障害者福祉課長","answer":"そういった中では、区のほうも、この施設に対して、あるいはこの法人に対してしっかりと連携を組みながら、一歩一歩着実に成人期の発達障害の方の支援ができるようなところは、区のほうも十分に責任を持って対応していきたいと考えているところです。","id":"exchange-057"},{"speaker":"井上委員","kind":"提案","question":"さっき、あくつ委員からあった、就労Ｂのところで、ブランチ型ファームというのは、それが地下というのがよくわからなかったので、そこの説明をお願いします。それから、事業経費をどのぐらいでしていただくように、区からの提案をされたのか、それによって結構プロポーザルの事業者とかも変わるのかなと思うんですけれども、そこはどういう提案を、こちらからはされているのでしょうか。","respondent":"中山障害者福祉課長","answer":"最近では、企業の中に受付の広い窓口のところの一角に、そういったファームを設けているところもあるというお話でした。それから、運営の金額ですが、障害者福祉課のほうのプロポーザルの実施要領の中では、特段金額については載せさせていただいておりません。","id":"exchange-058"},{"speaker":"井上委員","kind":"質問","question":"一つなので。先ほどの企画のお話もありましたけれども、全体を通して初めての施設であって、実際に幼少期から就労までという特別教育の連続した支援をしていくという中で、ここになぜ教育委員会を入れなかったのか。私は入れるべき、これからもしそういうことがあれば、入れていかなければいけないというふうに思いますけれども、そこについて、なぜ入っていないのか、教えてください。","respondent":"中山障害者福祉課長","answer":"特別支援学校のほうにも、対象となる方がいらっしゃるということも聞いておりますので、最初にこの就労につなげるところについては、区のほうもかかわって、どういった方がここの施設で安定的に継続的に訓練サービスが受けられるかというところは。","id":"exchange-059"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"１点だけ、今、態勢だったりとか、社会福祉法人げんきの品川区での実績なんかも、いろいろ聞かせていただいたんですけれども、ほんとうに発達障害に特化した新たな施設というところで、区も連携して、という言葉がたくさん出てきたんですけれども、連携の具体的なところ、今、協議会的なものが、げんきと一緒に開かれているのか、そういったところを、ちょっとお聞きしたいんですけれども。","respondent":"中山障害者福祉課長","answer":"最初の仕事としましては、近隣への事業者説明というところにも、げんきと区と両方で参りますし、その後の具体的な事業の準備、それから、例えばグループホームの入居者であるとか、就労Ａ、Ｂのほうにつながる方、サービスを受けられる方の選定であるとか。","id":"exchange-060"},{"speaker":"井上委員","kind":"質問・要望","question":"今ほんとうに第１条の目的のところで、連携を取って、区も一緒に育てていくという言葉をいただきましたので、ぜひそこのところはしっかりと期待をされている施設として育てていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"共産党は、当初の設置条例と同時に行われた指定管理の運営のところで、株式会社が入ってくるのではないかといったところを危惧して反対をいたしましたけれども、今でも、本来区がやるべきではないかとは思うんですが、げんきの今までの経験と、立ち上げにあたって区が丁寧に支援をしていく、目を離さずに十分にやっていくというところで、丁寧にやっていっていただきたいと思っています。それで賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"}]},{"id":"topic-05","title":"の１の(7)、指定管理者の指定","agenda":"の１の(7)、指定管理者の指定","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"今回の申請から修繕体制を強化することを目的にということで、住友不動産リフォームが参加するということなんですけれども、どういったことを、この共同事業体として、修繕体制の強化を新しく参加した理由に挙げているのかというところ。これは、区としての募集の条件の中に、そういったものが入っていたのかどうか、あわせて教えてください。","respondent":"江部健康課長","answer":"この点について、特に募集要項でこれを強化することというような特記事項などは載せておりませんが、事業内容全体の中には、維持管理の中で、こういうところで経費がかかるということは、具体的に金額を明示している中でのことですので、事業全体の中での協議で。","id":"exchange-063"},{"speaker":"あくつ委員","kind":"質問・要望","question":"指定管理者側の健康センターに対する強い意欲が認められることということで、５年間やってこられて、その上で、経験値から必要なことということで、多分こういう提示があったと思うんですけれども、５年前と比べて、新しく脱衣所等というところもあると思うんですが、そのほか、今回の選考の中で、区として、指定管理者の選定の公募の条件として新しく求めたところがそれ以外であるのであれば。","respondent":"江部健康課長","answer":"したがいまして、光熱水費の削減ということは、テーマとして出しております。それにつきまして、５年間で２５０万円の削減を提案をしてきております。","id":"exchange-064"},{"speaker":"井上委員","kind":"質問","question":"３点目は、以前にこのセンターの中で、健康づくりをする市民団体が施設の中の会議室とかを使われていたんじゃないかなと思いまして、それができなくなったという経緯があると聞いているんですが、その部分について、健康づくりをしている団体への、地域での活動も含めた健康づくりの支援というところがありますけれども、ここについては、どういったことで選定した理由の中に含まれているんでしょうか。","respondent":"江部健康課長","answer":"ただ、スポーツ施設だけではなく、貸館という部分では、７階のホール、それから３階の会議室は、一般の方が申し込みをされておりまして、そこは利用していただけるものと思います。","id":"exchange-065"},{"speaker":"井上委員","kind":"提案","question":"ここの事業の中で、以前だと、双子のお子さんたちの教室とか、区民であってもなかなか利用できないような、そういうことで、この事業をここでやってほしいという提案とか、そういうものがあるのか。今、すべて事業メニューは指定管理者からのものなのか。そういう仕組みは持っているけれども、やっていないのかとか、その辺はいかがでしょうか。","respondent":"江部健康課長","answer":"それで、あと、前にあった双子の教室云々というところは、ちょっと私、今、お答えできません。","id":"exchange-066"},{"speaker":"たけうち委員","kind":"質問","question":"先ほどのあくつ委員のところにちょっと関連するんですが、新しくリフォームが加わるということで、結構なことなんですが、そうすると、指定管理料の中で小規模修繕をやる場合に力を発揮されるという認識でいいのか、それとも、いろいろ大規模なものになってきて、別途区のほうからお金が出るような場合にも、何かそれをにらんでのお話なのか、その辺のところでちょっとお聞きしたい。","respondent":"江部健康課長","answer":"ただいまのご指摘のように、施設修繕をする場合に、小規模の１件１３０万円未満のものについては、指定管理料の中に入ったものということで位置づけておりまして、その他の大規模については、健康課で予算を持ちまして、委託で発注をするという形になりますけれども。","id":"exchange-067"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"この公募のところで、３団体が説明会には来たと伺ったんですけれども、それが最終的には１団体だけしか来なかったというのは何でかなというところと、あと、指定管理になる経緯、前回コナミがやっていたと伺っているんですけれども、なぜ指定管理にしたのかというところも、ちょっとその経緯だけ伺いたいです。お願いします。","respondent":"江部健康課長","answer":"８月、３０日間募集期間がある中で、途中で８月１６日の日に、事業者に対する現場での説明会を行っております。そちらに３者、３団体が参加されて、お話を聞いていただいたです。","id":"exchange-068"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"それで、インストラクターがころころかわってくるといったところも、なかなか区民が定着していけないところがあるという声も伺っているんですけれども、このインストラクターがかわってくるというところには、どういう構造があるのか、職員の待遇というのはどうなっているのか、ちょっとお聞かせください。","respondent":"江部健康課長","answer":"それは隠しようもないことですので、民間だからということではなく、民間の中にこそよさを求める事業かと認識しております。それから、インストラクターがかわる件につきましてですが、この５年間につきまして、複雑にかわった、多くかわったということはございません。","id":"exchange-069"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"それで、職員の待遇のところで、こういった職員の方がどの程度の賃金なのかというところまでは、区は把握できているんですか。","respondent":"江部健康課長","answer":"施設運営につきましては、指定管理者にお任せしておりますが、数名の常勤と非常勤の組み合わせで、シフト制で行われている状態だとは思います。それで、給与につきましては、把握はしておりませんが、こちらでお願いしている金額の中でやっていただいていると思います。","id":"exchange-070"},{"speaker":"井上委員","kind":"質問・要望","question":"賛成なんですけれども、一つだけ、協定書に向けての意見として一言あるんですけれども、私もFacebookの発信力というのはすごく評価をするんですけれども、表裏一体、表裏の部分があって、利用者の囲い込みというか、情報の受け取られる方だけが利用するということにならないように、その部分はきちんとチェックをしていただきたいということと、区の施設ですので、利用勝手のいい人たちだけではなく。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-071"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"反対です。一言。やはり区民の健康づくりの場ですので、そこに株式会社が入ってくる。それで、働く職員によって、区民の得られるサービスが変わってくるので、この職員の働く待遇、また賃金が把握できないということは、やはり健康づくりにはそぐわないのではないかなと思います。ですので、以前からも言ってきていますけれども、区民の健康づくりに指定管理、株式会社は反対ということで、反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-072"}]},{"id":"topic-06","title":"平成２５年陳情第１６号、食品放射性物質測定器の設置についての陳情","agenda":"平成２５年陳情第１６号、食品放射性物質測定器の設置についての陳情","exchanges":[{"speaker":"渡部委員","kind":"質問・要望","question":"１あったら安全なのか、安全ではないのかというのは、もう独自が判断せざるを得ない。もう一度確認いたします。区として、この放射能の問題に対して、今後の取り組み、どのような形で区民の方々の不安を払拭していくかというところの確認と、再度、今回の陳情の趣旨というのが、あくまでも食品放射性物質測定器の設置についてですので、これに対する考え方を再度お願いいたします。","respondent":"高山品川区保健所生活衛生課長","answer":"やはり膨大な量の物流を統計学的な保障に基づきまして、国等において抽出しまして、モニタリング検査を継続的に実施してきております。","id":"exchange-073"},{"speaker":"渡部委員","kind":"質問","question":"わかりました。陳情のタイトルと陳情項目についての質問を、今、させていただきましたが、その他、課長から、再度のご答弁をいただきました。地域の区民の皆様方がしっかりとした情報をとれるような形で、安心できるような情報発信について、今までも続けていると思いますけれども、これから、それは必要以上に、やはりきめ細かく対応を続けていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"あくつ委員","kind":"質問・要望","question":"第３回定例会におきまして、我が会派のこんの孝子議員より、同趣旨の要請をさせていただいていますので、その趣旨にのっとっての質問をさせていただきたいと思います。ちょっと質問なんですけれども、その中でも、いろいろなホームページへのアクセスが多いというところで、例えば、この窓口というのは、今保健所になっていると思うんですが、現段階でそういったご相談が今でも継続してあるのかどうか。","respondent":"高山品川区保健所生活衛生課長","answer":"それで、ご相談としまして、どのような対応をですが、平成２４年４月以降、新しい放射性物質の基準値が決められまして、そういった形で、乳幼児につきまして、乳幼児の食品については、１キログラム当たり５０ベクレルというのが一つの指標として出されておりますので、当然。","id":"exchange-075"},{"speaker":"あくつ委員","kind":"質問・要望","question":"乳幼児については、５０ベクレルということで、新たな基準値が発表されたということなんですけれども、これは本当に国が発表することで、これを区が発信すると、これが役目であるという先ほどのご答弁、ちょっと簡単かもしれませんけれども、正確な情報発信等々されていると思うんですけれども、それに対して不安を覚えている方がいるというのが、今回の要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"},{"speaker":"井上委員","kind":"提案","question":"それで、今回、ここの陳情の２３区内では、五つの区が持ち込みで検査をしているという状況の中では、当然食の問題というのは、東京都、国、そういったところでの判断が責務であるけれどもという区民への寄り添いという部分だと思うんです。みんな、全部の自治体、それは都と国が責任を持ってやるべきですと思いながらと思うんですけれども、そこのところについては、どんな見解をお持ちでしょうか。","respondent":"高山品川区保健所生活衛生課長","answer":"一方で、区民の不安な気持ちに寄り添うといったことに関して、品川区としてはどのようなという点につきましては、一つ、既にそういった持ち込み検査などを対応している区もあるわけですから、そのこと自体は、別に否定するものではないんですが、では、品川区はどうか。","id":"exchange-077"},{"speaker":"井上委員","kind":"意見","question":"そんなふうにも、私は考えているので、区民の方たちの思いには沿いたいと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-078"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"それで、給食食材の測定は、今年４月から回数を減らしてしまったし、牛乳測定は無実施とか、そういったところをもとに戻して、実施をしていくべきだということは、一般質問等でも言わせていただいているんですけれども、そういう中でも、区民の方々は、そうは言っても区はやってくださっていると、やってくれていると。ですがというところなんですよね、今回のは。それは、もう十分わかることですよね。","respondent":"高山品川区保健所生活衛生課長","answer":"２点目の放射線測定器の設置できない理由というんでしょうか、区の見解という部分ですが、できないと申しますよりも、やはり先ほどの説明の繰り返しになりますが、国と区のそれぞれの担うべき役割、責務の部分で、こういった部分は役割が分担されているんだと。","id":"exchange-079"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"ですので、わかってください、わかってくださいではなく、そこから一歩進んで、今まで一緒に測定なんかもしていただいているのであれば、食品測定、放射性物質測定器の設置をしていくべきではないかと思いますし、そんなに高額じゃないと聞いています。私も単純計算で、素人考えなので、あれですけれども、そういった一歩進んで考えていく、検討していただくということをやっていただきたいと私も思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"},{"speaker":"渡部委員","kind":"意見","question":"本日、結論を出すということでお願いいたします。態度ですが、私ども自民党でも、この陳情に関しまして、２日間にわたり協議をしてまいりました。しかしながら、今回の陳情項目というのが、あくまでも食品放射性物質測定器の設置ということが主題であり、それに対する陳情項目が上がっておりますので、私たち自民党としましては、今回、この陳情に関しましては、不採択という形にします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-081"},{"speaker":"あくつ委員","kind":"質問・要望","question":"公明党は、本日採決を主張いたします。それで、態度としては、採択とします。ただし、先ほどありましたけれども、区に食品のことで相談に乗るということは、その食品がどれぐらいの放射線なのかというのがわからなければ相談に乗れないわけで、その意味での食品の放射性物質測定器の設置だと考えます。第３回定例会一般質問でも要望させていただきましたけれども、我々は採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"},{"speaker":"井上委員","kind":"意見","question":"結論を出すということで、いいです。一つ、食品の放射性測定器を設置した場合に、大田区の場合なんですけれども、これを使いまして、学校給食の測定もされているということであれば、今品川区が行っている外部委託の給食食材測定も、こういったところでもできるということも一つ考えれば、いろいろな活用方法ができるのではないかと思いますので、採択を主張します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-083"},{"speaker":"鈴木（博）委員","kind":"質問","question":"結論を出す。それで、今日は、また一貫して、その情報発信をしておりまして、１回目と２回目の講演会は、実際に行ったんですけれども、中立的な、説得力のある講演で、非常によかったです。それで、放射線が怖いという気持ちも非常によくわかるんですが、現行のシステムで、少なくとも信頼に足るものだという点を評価すると、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-084"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"本日、結論を出すということで、共産党は採択でお願いします。ですので、やはりそういったところを出せる場所、そして、持っていけばはかってもらえる場所、危険性の認識の差はいろいろあると思うんですけれども、不安だと思う人が安心を得られる場所というのは、区が責任を持って設置していくべきだと私は思いますので、ぜひ検討をお願いしたいと思います。採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-085"}]},{"id":"topic-07","title":"の３、その他","agenda":"の３、その他","exchanges":[{"speaker":"井上委員","kind":"質問","question":"松澤議員の質問のところで、認知症対策なんですけれども、ＧＰＳの携帯について、伸びていないと。そのときに、答弁があったんですけれども、やはりこれについて、もう少し研究をして、不安に思っている方たちが利用できる方法について、少し質疑をしたいと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-086"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/588633?Template=document&Id=3372#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":59069,"voices":251}},{"id":"h25-20131125-8","meetingId":"h25-cm11","date":"2013年11月25日","dateIso":"2013-11-25","committee":"建設委員会","time":"午前１０時０６分～午後３時５２分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を103件抜き出しています。","topics":[{"id":"topic-01","title":"第６９号議案、品川区営住宅条例の一部を改正する条例","agenda":"第６９号議案、品川区営住宅条例の一部を改正する条例","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"今のご説明の中で、まず、被害者の保護等というのがついて拡大されたと。この基本の法律のところなんですけれども、ちょっとお伺いしたいのは、婚姻関係がなくても同居しているということなのですけども、先ごろ、デートＤＶとか、結構、ＤＶがもっと範囲が広がっているというところにおいて、この法自体がその辺もカバーする法律なのかどうか、ちょっと直接ではないのですが、そこが１点気になったことで。","respondent":"大串住宅担当課長","answer":"それからストックの関係です。区営住宅、先ほどご説明申し上げましたように、基本的には親族の要件が要るというのが大原則になっております。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"２点目の、ちょっと緊急性を要する場合に満室で無理だというのだと、法律はできて広がったかに見えるけども実際には実効性がないということになってしまうので、ぜひやはり絶対数が少ないというところにおいては、やはり確保の面で公営の住宅を増やしていくという、やっぱり社会情勢に合わせてしていくという意味では、こういった要求も出てくるというところで。","respondent":"大串住宅担当課長","answer":"２点ご質問をいただきましたが、それと関連するお話になるのですけれども、基本的にはこういった被害を受けられた方は、都道府県が設置しております配偶者暴力相談支援センター、あるいは一時保護ができます婦人保護施設、こういったところにご相談に行かれます。","id":"exchange-002"},{"speaker":"西本委員","kind":"質問","question":"そこの秘密の保護というか、そういうのはどういう関係性を持ってやっていこうとしているのかというのと。で、それを申請して、ではそれだったらということで、ほかの、これは何ですか、西大井の第３区営住宅ですかね、そちらの方に移ることもできるということになるのか。ちょっと運用の上でわからないところがあるのですが、そこはどうなるのでしょうか。","respondent":"大串住宅担当課長","answer":"別に、ＤＶに遭われた方がどこにお住まいかということは問いませんので、区民住宅の中にお住まいで、そういった状況に陥られた場合には、先ほど申し上げたような、一時的にはまず配偶者暴力相談支援センターですとか。","id":"exchange-003"},{"speaker":"西本委員","kind":"意見","question":"例えば、先ほども一部ありましたけど、確保するとかね。何部屋はそういう方たちのために確保するとかということができるのか、空いているときに、まあ、たまたま空いていたら使っていいですよというふうになっちゃうのか。そこら辺が、うまく救済できるような形ができ上がっていると、わりと緊急性に対応できるような形になっているのかなと思うんですけど、それに対しては何か今後、考え方としていますか。","respondent":"大串住宅担当課長","answer":"なかなか、そういった形で空きを確保できればよろしいのですが、優先度合いというか、そういったところにいけば、いろんなケースの方がいらっしゃいますので、なかなか、その方その方全てにおいて入居が確保できるような状況というのは難しいかと考えております。","id":"exchange-004"},{"speaker":"大沢委員","kind":"質問","question":"それとも、現行で要は新旧対照表の部分で、旧の条例が適用されるのか。それとも新しい条例でやるのか。そこのところはどういうふうになっているのか教えてください。","respondent":"大串住宅担当課長","answer":"こちらの新しい法律あるいは条例につきましては、ご議決いただければ、年明け１月３日から、こういった状況の方について適用範囲が広がるといったところです。","id":"exchange-005"},{"speaker":"あべ委員長","kind":"確認","question":"ほかにご質疑はありますでしょうか。副委員長、よろしいですか。私から２点確認させていただいてよろしいですか。先ほど運用の話がありましたけれども、一般にＤＶの被害で逃げて住宅を用意するという場合、例えば品川の方がそういうことに遭って、品川の住宅に逃げるというのはあまり考えられなくて、これは他の自治体を含めてかなり広域に運用されると理解してよろしいでしょうか。１点だけお願いします。","respondent":"大串住宅担当課長","answer":"おっしゃるとおりです。品川区内でこういった状況になった場合、やはり同じ、同一の品川区にいらっしゃるというのはちょっと難しいかと思います。といったところで、先ほども申し上げましたが、配偶者の相談支援センター。これは都道府県レベルで設置しているものです。","id":"exchange-006"}]},{"id":"topic-02","title":"第７０号議案、品川区廃棄物の処理および再利用に関する条例の一部を改正する条例","agenda":"第７０号議案、品川区廃棄物の処理および再利用に関する条例の一部を改正する条例","exchanges":[{"speaker":"伊藤委員","kind":"質問","question":"ちょっと部署は違うかもしれませんけれども、区の統一的な延滞金の考え方は５％というご説明ですよね。それは、その根拠をもう少し説明していただければと思うのですが。５％の根拠。わかる範囲でご答弁をお願いします。","respondent":"小林品川区清掃事務所長","answer":"明確に５％としなければいけない理由はないかと思いますが、準拠しているのは、最終的な、非強制徴収公債権は私債権との関係がありますので、強制徴収する公債権ではございませんから、最後のよりどころは民法の、債権の延滞清算利率の５％。","id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問・要望","question":"２点です。１点目は、区民への影響について教えていただきたいのが一つです。２点目なんですけれども、３定にかかった、区税にかかわるところがありましたよね。それと今回ずれているという４定でされたという理由をひとつ教えてください。","respondent":"小林品川区清掃事務所長","answer":"２点目の時期の問題ですけれども、区として基本的な考え方は、私債権の管理に関する条例でご判断をいただく予定になっておりましたので、その結果を得て改正しても、税法の改正に合わせるとすると、本法の施行が明年、平成２６年１月１日なので間に合うということで。","id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問","question":"後半なのですけれども、私債権の判断結果が出たのでそれに合わせてということは、ちょっと管外になってしまうかもしれないんですけど、ほかの区の延滞金、ほかにかかわる部分もこれから発生してくるということなのでしょうか。品川区清掃事務所長の管轄ではないんですが、延滞金にかかわる部分で、今後、ほかの部署で出てくるという可能性があるのかどうか、わかったら教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"大沢委員","kind":"質問・要望","question":"条例改正ということで、現在の金利状況云々というところですけれども、条例改正の目的とか狙い、要は１４.６％からパーセンテージが落ちていますけど、実は延滞金に対する徴収率を高めるのか。どういう目的があるのか教えていただきたい。","respondent":"小林品川区清掃事務所長","answer":"延滞金の狙いは納付促進ですが、今ご説明させていただきましたとおり、現時点では延滞金が発生してございません。ただ、手数料形態をきちっと整えておく整合性から、今回改正をお願いするところです。","id":"exchange-010"}]},{"id":"topic-03","title":"第７１号議案、品川区自転車等の放置防止および自転車等駐車場の整備に関する条例の一部を改正する条例","agenda":"第７１号議案、品川区自転車等の放置防止および自転車等駐車場の整備に関する条例の一部を改正する条例","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"駐輪場の増設は理解しているところなんですけれども、先日、新たな駐輪場、自転車駐車場の設置の向かい側の大森駅前住宅の住民の方々から、中止・反対・撤回を求めるという意見が多数寄せられているんですね。そういった面で、住民の方々の理解を得られていないと私は受けとめているのですが、この間の経過を改めて時系列的に、どういう対応を行ってきたのか教えてください。","respondent":"谷口交通安全担当課長","answer":"それから業者選定等進めまして、１１月から実施したいと考えていたところですが、大森駅前住宅の皆様から説明会を実施してほしいというご要望が再三寄せられまして、１１月１１日にこの住宅内で説明会を実施したところです。","id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問","question":"ちょっとわからなかったのが、９月補正で、１０月２１日決定をし、業者を選んで、１１月実施の予定だったと。ここまではいいですね。住民の方には、１１月１１日、ここの住宅の方に説明をされたと。１１月１１日ですね。で、１２月６日工事実施のお知らせというのはいつ配られたのか、ちょっとこれをもう一回教えてください。","respondent":"谷口交通安全担当課長","answer":"工事実施のお知らせにつきましては１１月６日に配付いたしました。大森駅前住宅の理事長の方には１１月２日に、自治会長がちょっと体を壊されているということでございましたので、理事長のほうに工事を実施しますというご連絡を申し上げたところです。","id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問","question":"こういった案件では、もし地域の方でご不満があったり、意見したいと声が聞こえてくるのですが、今回、９月補正のときに聞こえてこなかった。現時点で、多分、私のところにも、自宅にもファクスでいろいろご意見をいただいたので、理解は得られていないと思うんですが、課長はその辺、どのように受けとめていらっしゃるのか教えてください。","respondent":"谷口交通安全担当課長","answer":"いろいろ説明会の中で、明日、説明会を実施予定なんですけど、いろいろ頂戴したご要望、ご意見については、真摯に、明日も含めて回答していきたいと考えております。","id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問・要望","question":"住民に説明がないということに対して１点と、あと、今お話がありました、外部の人々による騒音。放置自転車による歩道での事故。４点目に、水神公園の駐輪場拡大が最適ではないでしょうかと書かれているので、ちょっとこの辺の検討についてもお答えいただきたい。ちょっとその辺を伺いたいのと。だから水神公園のところが、具体的に言うとどういう方向性になるのかを含めて教えていただきたいと思います。","respondent":"谷口交通安全担当課長、松代防災まちづくり事業部長","answer":"ほかに駐輪場がないのかということで、昨年から駐車スペースがないか、民地も含めまして、区道上も含めまして、ずっと検討を進めてまいりました。なかなか、そういった意味では、十分な説明とご理解という点では不足したところがあったかに思いますが、こういった点をぜひ勘案していただきまして、地域の課題をぜひ共有していただき。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった意味では、私は一つ聞きたいのが、水神口のところ、どのような対策をイメージされているのか、もうちょっと具体的にお伺いをしたいのと、私はもっと周辺を見て検討が必要ではないかなと思うんですね。そういった面で私は、あしたもお話し合いがあると伺っていますが、話し合いがされる予定なのに、その前日に決めてしまうというのはないであろうなと思うのですが、いかがでしょうか。","respondent":"松代防災まちづくり事業部長","answer":"そういった意味では、今ある公園の施設を一部改良して、今の駐輪場の、そもそも段差があって利用等になかなかしにくい面もありますので、そういった部分を少し利用しやすいような形と、今の公園設置の一部をそういった形で拡充できないかというふうに思いを持っております。","id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問・要望","question":"水神口のところをもうちょっと具体的にお伺いしたいのですが、公園法の中で広げていくというところでは、めど的には時間がかかりそうなのですが、いつぐらいまでにどのぐらいの規模増やしていけるのかというところで、今回、当日利用なんですね、１６５台ね。","respondent":"谷口交通安全担当課長、松代防災まちづくり事業部長","answer":"地下式にかかる費用、従前もちょっとご説明したことがありますけど、サイド式なんですけど、２００台の地下式をつくるに当たっては、調査研究で二、三千万かかります。で、設置に１億かかります。水神公園のもう少し具体的なですけれども、申しわけありません、具体的なところはまさに今、検討中です。","id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問・要望","question":"もちろん地下式だけではなくて、いろいろ建設するのにもかかっていくのが当然なので、余分な自転車は整理していく方向はもちろんそうなのですが、駐輪場対策って本当に、さまざまな対策をしていかないと、まちづくりにおいて、いかないので、駐輪場だけではないと思うのですが、私は本当に、ＪＲの鉄道事業者に対しての具体的な、あの地域の困難さも含めて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"伊藤委員","kind":"確認","question":"それから第２下川ビルに塾が入っているんですよね。そこには相当、放置自転車があるということは、私も何回も言っているのですけれども。さて、そういうことをずっと考えていくと、違法駐輪が多いところに駐輪場を設置して、そこに駐輪を指導するような方法をとれば合理的であると思うのですが、そういうところをなぜ検討されなかったのでしょうかということをまず確認させてください。","respondent":"谷口交通安全担当課長","answer":"それを設置することによって、各商店に対する出入りの障害であったり、自転車と歩行者の交通事故も当然懸念されますので、そこの部分は設置しないということで判断したところです。","id":"exchange-018"},{"speaker":"伊藤委員","kind":"質問","question":"もう少しちょっとお伺いしたいんですけど、日立ソリューションズの大森駅側のほうです。実はここが一番多いということはもうご存じだと思うんですけれども、そこになぜつくらなかったのでしょうか。単純な話なんですよ。多いところにつくっていただいたほうが。ましてやこの辺はいわゆる商業施設が入っているところでありますから、あえてそういうところを避けた理由をもう一度聞かせてください。","respondent":"谷口交通安全担当課長","answer":"商店に出入り口から出てくる方は当然、自転車のことは想定されていないと思われますので、出てきた方と、通行も含めての、自転車の事故は当然想定されますので。出入り口付近に設置することによる駅前の景観も含めまして、いろいろ総合的に判断したところです。","id":"exchange-019"},{"speaker":"伊藤委員","kind":"質問","question":"だから、確かにお金はかかったかもしれない、大田区の場合。だけれども相当効果があったことは確かであって、その余波がこっちに来たということも事実である。となると、私の思いとしては、駐輪場の設置ももちろん必要ですよ。大田区の施設が目の前にあるわけですから、そういうことをお考えになって、ハードなのよりソフトなところで駐輪場対策をしていくといいと思うんですが、いかがでしょう。","respondent":"谷口交通安全担当課長","answer":"委員ご指摘の大田区で、いろいろ人を配置しながら指導・啓発をやっていると伺いますけど、当然、区としましてもハード・ソフトを含めて、ハード面を整えまして、ソフト面につきましても来年度、シルバーであったり警備員を配置して指導・啓発、また撤去。","id":"exchange-020"},{"speaker":"伊藤委員","kind":"意見","question":"そうだね。その部分は理解するんだけれども、どうしてもついていけないのが、今既に違法駐輪がある場所につくらないで、ここにつくるのかという、ここの疑問がずっとついて回るんですよ。確かに法律の関係なり、それから条例上の仕切りなりでわかるんだけれども、何といったらいいのかな、もう少し外に、ハード面も含めて、総合的な駐輪場対策を検討すべきではないかということを思うんです。","respondent":"谷口交通安全担当課長","answer":"それで、終わりではございません。大森駅周辺の放置自転車対策につきましては、引き続き調査研究しながら、あらゆる手法・手段をとりながら、地域住民にはご理解が得られるように努めてまいりたいと思います。以上です。","id":"exchange-021"},{"speaker":"伊藤委員","kind":"意見","question":"だけれども、私どもとしては総合的な駐輪場対策を議論していく中で、ここにつくることについてはいろんな意見があることが象徴するのだけれども、何というかな、もっと総合的な対策を検討して、どなたの方々にもご理解し、納得していただくような対策を進めていくべきであると思っていますので、そのことについてのお考えを最後に聞かせてください。","respondent":"松代防災まちづくり事業部長","answer":"物理的には、今、言葉で言ったようなことを右から左になかなかできないのが現状ですけれども、まずそういった取り組む姿勢をご理解いただきたいということと、あわせて解決の段階、その状況状況で、まずとり得る方法をとりながら、今。","id":"exchange-022"},{"speaker":"伊藤委員","kind":"質問","question":"まとめますけど、当然、全ての区民の方々を相手にする仕事なんですよね、皆さんのお仕事というのは。ですから、その中で最大公約数といいましょうか、できるだけの努力をして、多くの方々にご理解いただいて、なおかつ負担の少ないような対処をしていく。だから、そういう単純予測に立って、これからも駐輪場対策等を進めていってくださいますようにお願いしておきます。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"大沢委員","kind":"質問・要望","question":"今、お話しいただいて、駐輪対策としての課題で、議会からも要望があった。で、９月補正でもこちらのほうで認めた。そういう流れの中としての放置自転車対策の課題。そこのところのお考えから伺いたい。先ほど、道路幅の広い、駐輪するには適した場所ということは聞きましたけれども、そこのところもお含みおきをいただきながら、もう一度、すみません、そこの件に関してお答えをいただきたいと思います。","respondent":"松代防災まちづくり事業部長","answer":"それは現実ですので、やはり禁止区域を設けるのと同様に、そういった収容施設を設けるというのが、一方でとらなければいけない対応策だろうと考えています。したがいまして、今回も直近のところで収容できる施設ということで考えたところがここです。","id":"exchange-024"},{"speaker":"大沢委員","kind":"質問・要望","question":"それは十分わかりますが、確かに区としての課題を解決すべく駐輪対策を遂行しているというのは十分わかります。そこのところの温度差をどのように埋めるか。埋めることによってさまざまな問題が対処されていくと思うんですけれども、そこのところの温度差を埋めるには、どのようにすべき、したらいいかと。どのように考えているのか教えていただきたいと思います。","respondent":"松代防災まちづくり事業部長","answer":"いろいろとご不安等がある、そういったことは、今の形で想像できること、もしくは今後起こり得るであろうというところも含めて、誠心誠意、もって、区はその後、設置するだけが目的ではございませんので。","id":"exchange-025"},{"speaker":"大沢委員","kind":"質問・要望","question":"事業の発案、着手、完了までの間に、確かにスピード感という、地域課題に迅速に対応するという区の責務の重さ、十分に感じて日夜業務に励んでいただくのはわかるんですけれども、それがかえって、スピード感が速過ぎてしまって、このように地域の方の欲するところと行政のする事業との間にスピードのそごが生じていることがまま見受けられる部分がありますので、そこのところを、対処型。","respondent":"松代防災まちづくり事業部長","answer":"確かに今、委員がおっしゃられるように、スピード感の中にも、今、いろいろと地域の方々の不安等を、我々計画を進める者がしっかりと酌み取りながら、それを説明し、理解を求め、ご理解のもとに進めるというのは、これが基本だと考えています。","id":"exchange-026"},{"speaker":"伊藤委員","kind":"質問","question":"もう一回言いましょうか。これはおそらく、今の時点では、条例が可決される前の時点では、非常に民地の近くといったらいいんですかね、大森駅前住宅等の位置関係のような、非常に区民の住宅の近くにつくられている施設はおそらくないと思われるんです、現状では。だから、そのことについてしっかりとした考えを持っていくべきだと思うんですが、いかがでしょうか。","respondent":"谷口交通安全担当課長","answer":"委員からの、民地、要は住宅の前。大森駅前住宅のような大規模マンションの前には今回初めてとなります。ただ、区内２３カ所の区営自転車駐車場がありますけれど、この中には荏原町であったり旗の台であったり、要は住宅の直近の付近にも設置しています。","id":"exchange-027"},{"speaker":"伊藤委員","kind":"質問・要望","question":"要は、今までにないところにつくろうとしているわけですから、それがやはりはっきりとした防犯上の対策なり、それからずっと部長がおっしゃっていたような理解を求める仕組みなりを、ここだけ特別というのはなかなか言いにくいのかもしれないけれども、だけどこれだけ民間の住宅が近い位置もなかなかないわけでありますから、そのことはこれからもあるかもしれない話であるから、ぜひ十分に検討して。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"西本委員","kind":"質問・要望","question":"で、これは非常に要望があったと私は認識しているし、多分ここにいらっしゃる委員の皆さんも非常に要望があって、早くここに駐輪場が必要なんだと、皆さんは主張していたと思うんですよね。その要望というのはどういう経緯があって、どれだけのものとして区として補正にかけてまで重要視して、今回、スピード感を持ってしたかということの思いでありますとか、それをちょっと確認したいということ。","respondent":"谷口交通安全担当課長","answer":"で、今回つくったからといって、では放置自転車がなくなるのかと。それは、私自身もまずゼロにはならないと思っています。しかしながら、区としましては一歩一歩、放置自転車対策につきまして取り組んで、地域の社会のために貢献していきたいと考えております。","id":"exchange-029"},{"speaker":"西本委員","kind":"質問・要望","question":"で、今、どうもこの議論を聞いていると、それが、何というのでしょうか、その議論が、さも何か積み上げて、やっとここまで来たのにというところの思いが、何となくマイナス方向に行っているような気がして残念なのですが、それだけに住民さんたちのご理解というのがやはりきちんとしていかなければならないのだろうなと、非常に私も考えさせられた事案かなと思っています。その辺について。","respondent":"松代防災まちづくり事業部長","answer":"先ほどから申し上げていますが、重ねて、あすの説明会も含め、しっかりと誠意を持ってお話を続け、ご理解を得るように努めてまいります。","id":"exchange-030"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"今、ほかの委員さんたちからの質問もお聞きしながらですが、この大森駅前周辺の駐輪場の増設は、私どもとしても大変要望しておりましたし、スピード感を持ってという、ほかの委員さんのお言葉をかりれば、そういったことも要望してきた。現時点で、その進め方でどのような状況になっているのか。そこをお聞きしたいと思います。","respondent":"谷口交通安全担当課長","answer":"その場で、いろいろご要望、ご不満、撤回論も含めてお話を聞いたところです。あした予定されております説明会におきましては、地域の皆様、多くの方にご出席いただきまして、その場で、１１日に頂戴しましたご要望、ご意見、一つ一つ丁寧に不安を解消できればと考えております。","id":"exchange-031"},{"speaker":"こんの副委員長","kind":"提案","question":"そこで、いろんな要請の項目が出ておりますけれども、先ほどもご答弁いただいたんですけれども、改めて、大事なことなので確認させていただきたいのですが、そのご不安なり、また皆さん方のご提案なり、そうした具体的な項目でどのように対処し、どのように対応され、どのようにしていこうとお考えなのか、恐れ入りますが、もう一度ご項目別にご答弁いただければと思いますが。","respondent":"谷口交通安全担当課長","answer":"防犯上の問題は、今度の拡張予定の場所につきましては、防犯カメラを設置したりですとか、夜間帯は音の出ない機器を使ったりだとか、放置利用の増える状態も想定されますので、それは警備員の配置だったりシルバー人材センターの配置だったり。","id":"exchange-032"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"ご理解を得て進めていくというのが大事であろうと思いますが、この項目、皆さん方から、例えばこの項目に対して先ほどからもご答弁、ほかの委員からの質問に対してご答弁されていたのも伺っているので、そのことに対して誠意を持って答えていくという姿勢も伺っております。決して、ほかのところでもそのご理解を求めずして進めたところというのはないと思うんですよね。意見にとどめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"木村委員","kind":"質問・要望","question":"大変、放置自転車が多いという地域であれば、やっぱり駐輪場というのが全体に必要になってくるだろうと思います。ただ、住民の方々の心配というものも幾つか挙げられておりますけれども、そういうことに対して、先ほど、しっかりと考えをあすの説明会でお話をするということを聞きました。ぜひ、そのことに対してお聞かせいただきたいと思います。","respondent":"谷口交通安全担当課長","answer":"ただ、手前みそですが、一応、工事に関しましては、事前にご質問をしたり、あと各町会、関係する町会には事前にご説明に上がったりとか、そういう手続も踏んでいるところですので、どうか明日の説明会につきましては、一つ一つ不安の解消に努めてまいりたいと思います。","id":"exchange-034"},{"speaker":"木村委員","kind":"質問・要望","question":"ご答弁で十分、そういう意味では通知をしてということを言っておりますけれども、その地域の住民の方々にしてみれば、本当に突然そういうことがあるということを知ったと。驚いたというようなことを聞いております。その点をこれからしっかりとやっていただきたいなと思っています。これは要望ですけれども、そういう意味では、もっとしっかりと住民の方々に説明をしていただきたい。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"こんの副委員長","kind":"質問","question":"動議を出します。その理由は、今回設置するに当たっての、先ほども質問をしてまいりましたけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"こんの副委員長","kind":"意見","question":"いわゆる、今回のここの採決に関して、私どもは住民の方へのご理解をいただかないまま、これが設置されていくというところでは、今現時点で、あすの説明会もありますので、その説明会の皆様のご理解も聞いた後に採決をしても、結論を出すということでもいいのではないかという考えを持っておりますので、ここで、また別途委員会を設けて結論を出すという考えのもと、動議を出したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"},{"speaker":"飯沼委員","kind":"質問","question":"すみません。質問なのですが、保留となると、今後どういう扱いになるのか、ちょっと具体的に教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"こんの副委員長","kind":"質問","question":"今回、今ここでというのは、説明会があしたあることから、いわゆるこの説明会でどのようなご理解を得られ、どのような形だったのかをお聞きするために、その後いわゆる最終本会議の間までにまた別途委員会を設けて、そこの状況をお聞きして、そして決めていくという形で考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"西本委員","kind":"質問","question":"これは、審査予定表というのを渡されて、それで議案の審査ということがあって今に至っているわけですよ。で、ここで議論するのに、いろいろお時間を使って議論したわけですよ。であるならば、一番初めに諮るべきなのではないのですか。皆さんしっかりと議論されているではないですか。それと本会議の間にまた再度、議決しましょうという話になるわけじゃないですか。私は意味がないと思うんですけど。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"原委員","kind":"確認","question":"当然、議員ですから、議会の運営のやり方とか段取りはご理解されていると思うので、ほかに動議を、同調される方がいるかいないかの確認と、それからあとは実際の問題としては、いつ出されても構わないので、それはそれで。ですから粛々と委員長方で対処されればいいのではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"伊藤委員","kind":"質問","question":"今の動議でありますけれども、当委員会に今度の本件委託をされたわけでありますので、今日の委員会の中で決を出していきたいというのが私の意見になります。ですから動議に反対いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"西本委員","kind":"質問","question":"動議に反対です。やはり、散々今まで議論していたわけですから、この中でやはりこの結論を出す。付託をされたという私たちの使命もありますので、きっちりと今の審議の中で結論を出すべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"ただいまの私の動議に対しての否決という形になりましたので、私どもは現段階として結論は出せないという姿勢です。ですので、態度は保留とさせていただきたいと思いますので、ご了承いただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"伊藤委員","kind":"意見","question":"ですが、この中にはやはり十分な説明をする案件と、それから先ほど部長がお話しされたように、特に１８番地につきましては緊急避難的なものであるということ、それから管理・防犯・セキュリティーに対しても十分していただくこと、それから適地がほかに見つかったら即、撤去するような、特別な配慮をしていただくことを改めて自民党としてお願いさせていただいて、賛成であります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"},{"speaker":"原委員","kind":"質問・要望","question":"ですから、全体のメリット、各委員、ほかの委員が皆さんおっしゃっているとおりだと思います。全体のものと、それから約８００戸の世帯との問題。ですから、その手順としてはもう少し段階をうまい形での対処、事前事前でやってほしかったと。ですから、あくまでもここの個別のいわば８００世帯の、言葉表現は適切かどうかわかりませんけど、価値観を落とさないようにしていただきたい。それが要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"飯沼委員","kind":"意見","question":"駐輪場の必要性については、この会議、同意がとれている。これは確かです。しかし、この場所でいいのかということが、理解が得られていないことが今日明らかになったと思います。おっしゃっておられること、ごもっともであると思っています。そういった意味では、明日、２６日、話し合いがあると言われていますので、今日は決定できないといったことで、反対の立場を出します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"},{"speaker":"西本委員","kind":"質問・要望","question":"いろいろご意見、状況も確認させていただきました。やはり、やり方論になるのかな。こういう問題があって、他の地域からも要望がたくさんありましたと。それはもう仕方ないですね。ここに駐輪場が必要ですから。ということが今回、明らかになったわけですから、それはしっかり伝えていただいて、何とかご理解いただけるように最善を尽くしていただきたいということで、７１号議案については賛成します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"あべ委員長","kind":"質問・要望","question":"ここで委員長として一言申し上げたいと思います。もう、これが終わったから、あすから工事、あさってから工事ということではなくて、きちんと手続を踏んでいただきたいと思います。それから二つ目。これは区からも答弁がありましたけれども、駅周辺での総合的な対策ということを、引き続き熱心に進めていただきたいと思います。そういう考えですが、皆様いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"}]},{"id":"topic-04","title":"第７８号議案 指定管理者の指定","agenda":"第７８号議案 指定管理者の指定","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"選定理由のところなんですが、５番目のところ、管理経費、コスト削減案、滞納対策と書いてあるのですが、この経費、コスト縮減というのがどういう意味なのか、額が出ているのだったら幾らか縮減しているのかという、ちょっとこの中身を一遍教えていただきたいのと、共産党としては直営を求めているのですが、改めて指定管理者の制度をとっている理由を聞かせてください。","respondent":"大串住宅担当課長","answer":"額につきましては、あくまでもプロポーザルというところで各３社のほうからご提案をいただいているものですので、ちょっとこの場でお幾らというのは、なかなか答えにくいのかなと。","id":"exchange-050"},{"speaker":"飯沼委員","kind":"質問","question":"ご説明の中で、額は示せないと。どこをどう工夫して削減をしているのか。やっぱり例えば滞納一つをとってみても、やっぱり困難が始まった区民の方に対して、自治体のいろいろ手だて、特に福祉面での手だてができるというのがとても重要であると思うのですが、その辺が、私たちはやはり、直営でない、指定管理者のところでは、不十分ではないかなと思っているのですが、その点はいかがでしょうか。","respondent":"大串住宅担当課長","answer":"基本的には皆さん同じ回答です。丁寧に対応していく。初期段階のところからなるべく、要するに滞納額の小さなところから小まめに対応していく。これしか方法はないよというお話でございました。","id":"exchange-051"},{"speaker":"飯沼委員","kind":"質問","question":"ローテーションの見直しで給与のところが縮減できているということなのですけれども、なかなかつかめないと思うのですが、お一人一人、働いている方の給与に響いているのかどうか、そこまで把握しているのでしょうか。人員は変わりないということなのですが、やはり一番関心事は、プロポーザルをやるたびに下がっているという声も聞いているのですが、その辺はいかがでしょうか。","respondent":"大串住宅担当課長","answer":"ですので、例えば西五反田の東館、西館だけのローテーションということではなく、ほかの地域のほかの物件、あるいは東急がほかに手がけていらっしゃる分譲住宅ですとか、そういったところのローテーション、こういったものを活用しながらというふうに伺っているところです。","id":"exchange-052"},{"speaker":"西本委員","kind":"質問","question":"指定期間が４年間。指定管理者はたしか５年ぐらいだったかなと思って、なぜ今回４年間なのかなということ。西館のほうはまたこれから指定管理者の期限が来るのかな、どういう感じになっているのかなと思って。で、それと、今回決めた中での補完的な何かメリットがあるのかどうか。同じような効果が上がるような対処がされるのかどうかをお聞きしたいです。","respondent":"大串住宅担当課長","answer":"４年間としたところですが、これは公募のときにも１度、委員会でご説明させていただいたかと思いますが、西館と東館は、それぞれ開設の年次が１年ずつずれております。で、東急コミュニティーが最初に指定管理に入ったのが、平成２０年の西館から入ったんですね。","id":"exchange-053"},{"speaker":"西本委員","kind":"確認","question":"わかりました。１点だけ確認します。４年間にして、平成３０年以降は、一体的な形で指定管理という形になるのですけれども、そうすると西館のほうの指定管理というのは、５年になるのですよね。これはどういうふうになっていくのかなというか。","respondent":"大串住宅担当課長","answer":"西館のほうは昨年、プロポーザルを実施しまして、平成２５年４月から平成３０年３月３１日までという５年間で、昨年は議決をいただいております。ですので、西館は５年間、今度の東館は４年間ということで１年のずれが解消されるといった流れです。","id":"exchange-054"},{"speaker":"飯沼委員","kind":"質問・要望","question":"反対します。ちょっと意見を述べさせていただきたいのですが、先ほども述べましたけれども、住まいは人権ということで、ぜひ区で直営でやっていただいて、区民の住環境、しっかりと実態をつかんでいただきたいのと、やはり福祉の充実などとぜひ結びつけていただきたいということで、区営住宅の指定管理者には反対なので、本条例に反対いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"}]},{"id":"topic-05","title":"第６６号議案、平成２５年度品川区一般会計補正予算（歳出、建設委員会所管分）","agenda":"第６６号議案、平成２５年度品川区一般会計補正予算（歳出、建設委員会所管分）","exchanges":[{"speaker":"飯沼委員","kind":"意見","question":"道路改良費の追加分なのですけれども、予算では３,８３８万６,０００円。これの、当初、何件ぐらい見込んでいたのか、どのぐらい件数的に増えていくのか、そこをあわせてお聞かせください。","respondent":"中村建築課長","answer":"で、当初の予定といたしましては、委託料、現地の測量の委託ですが、これが、２２０件が１７件増加見込みで２３７件あります。そして、工事のほうですけれども、こちらが、当初見込みが２６０件が、これもまた年度内での決算見込みとして２９７件と見込んでおります。","id":"exchange-056"},{"speaker":"飯沼委員","kind":"質問・要望","question":"それぞれ増えるわけですけれども、これの増える要因、何が背景にあるのかを教えていただきたいのと、あと事業の概要を見たら、助成金と奨励金と、二つ、２段階に件数がなっていたのですけれど、ちょっと助成金と奨励金の違いを教えていただきたいのと、その辺の件数の変化、推移をどう見ているのかも教えてください。","respondent":"中村建築課長","answer":"増えた要因ですけれども、こちらの、今までの年度当初からの実績の見合いから今年度の年度内のこれからの部分は推測しているわけですけれども、要因としましては、これははっきり申し上げることはできませんけれども、今、確認申請数なども。","id":"exchange-057"},{"speaker":"飯沼委員","kind":"質問","question":"助成金と奨励金のところというか、だからこの間の件数の変化に対する評価をあわせてお伺いしたいなと。今回だけの、増えているのか、今までの経年的なものも含めてどうなのかなと思ってお聞きしたんですけれど。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"飯沼委員","kind":"質問","question":"その下の段の、都市防災まちづくり事業費の追加分についてお伺いしますけれども、補正で前倒しでやっていくということなんですけれども、中身的に、これは専門家派遣と、あと除去助成ということになっていますけれども、基本的に不燃化の取り組みの中で、コア事業、今までと新しい部分がありますよね。除去はいいんだけど、更地にするだけではなくて建て替えの支援がどうなっているのかとか。","respondent":"品川木密整備担当課長","answer":"これを前倒しということで、今回、補正予算を上げているのですが、まず１点目、コア事業のほうですが、今回、コア事業のほうは主に、これは東京都のほうの不燃化特区のルールの中であるのですが、戸別訪問をやることによってコア事業とみなすという条項が。","id":"exchange-059"},{"speaker":"飯沼委員","kind":"提案","question":"そういった面では、今回、１０年プロジェクトをかけたということは、２０２０年までに進めるというところですよね。私、その辺では大変、困難さが。木密を解決するという点ではやっていただきたい思いもあるのですが、そういった面では強引というか、困難を地域に起こしてしまうのではないかなという、すごい懸念を持っているのですが、その点はいかがでしょうか。","respondent":"品川木密整備担当課長","answer":"そんな中で、やはり反対者の意見というのは非常に大切にして、よく話を聞いて、その反対者の方が一体何に不満を持っているのか、どうすれば解消できるのかというところは十分聞いて、こちらもできる限りの対応はしていきたいと考えています。","id":"exchange-060"},{"speaker":"飯沼委員","kind":"提案","question":"もう一点なんですけれども、今回提案の地域、２９号線沿道が広く含まれているといった意味では、道路に反対の声が多数あるということと、やはり道路に合わせて沿道を耐火づくりの建物にしていくということに対して、まちの違和感が大変大きいというか、そういったがっちりとしたまちは望まないという声もたくさんあるんですけれども、またそういった中で、やはりこれを進めていくことが、本当に。","respondent":"品川木密整備担当課長","answer":"ただ、どうも説明会等で出る写真が、道路の沿道が非常に高層ビルになっているようなイメージの写真しか出ないというところもあります。ただ、我々が東京都と一緒に説明している中では、まあ東京都もそうなんですけども、補助４６号線のようなイメージですね。","id":"exchange-061"},{"speaker":"飯沼委員","kind":"質問","question":"たびたびやっているので終わろうかなと思ったんですが、ちょっと、補助４６号線が出たのでね。補助４６号線、すぐ近くなんです。私、毎日通ってるぐらいよく知っていて、高いイメージではない。そうですよね。普通の住宅。延焼遮断帯効果があるからという言葉で、仕方がないなと思って賛成してらっしゃる方もいるんだけれども、実態がどうかというのも正しく伝えるべきだと思うんですけど、いかがでしょうか。","respondent":"品川木密整備担当課長","answer":"たびたびご説明があまりよくないようで、非常に私の説明を、もう少しわかりやすく説明しないといけないなと反省はしているのですが、耐火建築物イコール高層ビルというような形で考えているように思われてしまうのですが、耐火建築物というのは、現在では。","id":"exchange-062"},{"speaker":"飯沼委員","kind":"質問・要望","question":"もちろんそういった認識を持っていますけれども、東京都が初め、高層の図を示してしまいましたよね。あれが影響しているのと、補助４６号線が今後。とてものどかな、補助４６号線、沿道ですよ。耐火づくりの２階、３階で固めた道路では決してないんですよ。そこのところをやっぱりきちんと伝えていただきたいな。そのことは、だから区民にわかりやすく説明をしていただきたいなと思います。答えは求めません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"西本委員","kind":"質問","question":"一般財源があってということなんですけれども、これは全額出るわけではないんですか、東京都のほうは。そうすると、もっとこれが予算的にかけなきゃいけないことになると思うので、それは東京都との関係では、すぐ、申請すれば出してもらえるのか、一般財源からある程度出さなきゃいけないとなると、基金から出していくのか、出どころはどこから出していくのかという、その辺を教えてください。","respondent":"中村建築課長、品川木密整備担当課長","answer":"ですので、細街路の拡幅整備事業につきましては、大体、前年度の見込みをもとに次年度の予算を算出してという姿勢を変えないでいこうと考えております。今回の補正予算も、基本的にはこれに合わせた形で要求をしていくというような形になっています。まだ前倒しのほうは東京都がやると言っておりませんので、区のほうでこういうふうに補正予算を積んで要望をしていきたいと考えております。","id":"exchange-064"},{"speaker":"西本委員","kind":"質問・要望","question":"拡幅整備事業についてはわかりました。それと、密集住宅市街地ですけれども、多分これは、かなりいろんな動きが出てこようかと思いますので、やはり財源的にちょっと厳しいとなって、なかなか、とまってしまうようにならないように、ちょっといろいろ工夫していただいて、速やかに進められるところは進めていっていただきたいと思いますので。意見という形で終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"伊藤委員","kind":"提案","question":"自民党としては、今回の補正予算、賛成いたします。ここに提案されております防災まちづくりについては、さまざまな意見がありますけれども、私ども自民党としては延焼遮断帯の効果はあるということ、それからこのことについての事業を進めていることによって、多くの区民の方々の生命が救えると考えていますので、ぜひ積極的に進めていただきたいところをお願いして賛成いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-066"},{"speaker":"飯沼委員","kind":"意見","question":"意見を添えて反対します。細街路の拡幅整備事業は賛成します。もう一つの密集住宅市街地整備促進事業についてですけれども、補助２９号線が木密の地域を救う状況にないということが明らかになりつつある中で、道路づくりと不燃化を一体で進めるもので、地域の住民の方からたくさんの反対が出ていますので、この点は賛成できないので反対です。あわせて、だから態度としては反対いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-067"},{"speaker":"西本委員","kind":"質問・要望","question":"この間、いろいろと地域の中で進めようとされていて、やはり早く考えようかなという方たちもいらっしゃるんですよね。なので、不安な方もたくさんいらっしゃると思うんですけれども、そういう方たちの要望があったら、それに対応していただく形で、財源確保もしっかりとしていただくようにということで、賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"}]},{"id":"topic-06","title":"平成２５年請願第１５号、八潮から区役所などに行けるコミュニティーバスを求める請願","agenda":"平成２５年請願第１５号、八潮から区役所などに行けるコミュニティーバスを求める請願","exchanges":[{"speaker":"伊藤委員","kind":"質問・要望","question":"あれはどのぐらいのコストがかかっていたのでしょうかとの確認。つまり、全く無料のバスですから、その地域を回してどれだけの費用がかかるかという算定モデルもあるので、そのことを教えていただきたいのと、それから現況、大井町から今でも走ってますけど、大井町からしながわ水族館まで走っている、その年間コストがわかれば教えていただきたいのですが、いかがですか。","respondent":"多並公園課長、藤田都市計画課長","answer":"詳しい、今、資料は手元にございませんが、数千万程度の運行経費をかけながら。百万単位ではなくですね。一つ上の桁ぐらいの運行経費ということで運行したかと記憶しています。同様な金額が、走っていた荏原の路線だと思いますが、それについてはなかなか乗降客が増えず、最終的には大井町からの直行便だけに変更したという経緯があります。","id":"exchange-069"},{"speaker":"伊藤委員","kind":"質問","question":"しながわ水族館までのバスは無料ですから、つまり全額が税金の負担となっているわけですからね。それは皆さんご承知のとおりであって。だから、そういうことを冷静に考えていくと非常に厳しいと判断するのだけれども、改めて品川区のお考えをお聞かせください。お願いいたします。","respondent":"藤田都市計画課長","answer":"これまでの間、区で数年前に何度かまとめていただいた……まとめていただいたというか、陳情や請願が重なった時期がございまして、その時期に検討したようなこともありますけれども、そのときにも、約２,０００万から４,０００万近くの金額が、赤字が。","id":"exchange-070"},{"speaker":"伊藤委員","kind":"提案","question":"そういうことを冷静に考えていくと、この請願の紹介議員が言った提案なんだけれども、どういったルートを開拓して、どういうコストで、どういう料金設定をもとにしてバスの運行会社と協議をしていくかが全く書かれていないわけですよ。まして、今お話がありましたように、１路線４,０００万ですか、年間。１９区と、今、お話しされましたけれども、成功しているものがあれば教えてください。参考までに。","respondent":"藤田都市計画課長","answer":"すみません。ちょっと答えが、違う、反対側の話になってあります。","id":"exchange-071"},{"speaker":"飯沼委員","kind":"質問・要望","question":"これはちょっと意見なのですが、質問をします。品川は、駅に着いても駅の構内が延々と長いので、何百メートルあるんでしょうか、５００メートルあるとか言っていると思いますけれども、駅の構内を歩くだけでも大変だと言われています。こういった声が届いているのですが、八潮の方からさまざまな不便を解消してほしいという声が本請願なのですが、これに対してどう受けとめていらっしゃるのかが１点です。","respondent":"藤田都市計画課長","answer":"それからコミュニティーバスのほうですけれども、何度かご説明されていますとおり、既存のバス等も、それから鉄道も充実している中でのコミュニティーバスについては、その検討については慎重に行うべきと考えています。","id":"exchange-072"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この考えは私、やさしくないと思うんですね。で、一般質問でも行いました、既存のバス路線で補えるところは大いに補ってほしい。ですから、検討は幾らでもできると思うんですよね。あまりかたく考えないで、やわらかい頭でいろいろ検討していただきたいなと思っているんですけれども、その点、特に社会的要因考慮というあたりで、やはり見直していただきたいと思うんですけれども、いかがでしょうか。","respondent":"藤田都市計画課長","answer":"困難地域に対してですけれども、これも、なぜ困難なのかというのが、理由がいろいろあると思いますので、その辺を十分考えながら、慎重な議論をしていく必要があると考えています。","id":"exchange-073"},{"speaker":"飯沼委員","kind":"確認","question":"社会的な要因を考える。慎重に考えるということは、検討の余地があるということと捉えていいのでしょうかね。先ほどから、今回は八潮の方たちから出された請願ということで、八潮の地域の方が区内で移動するのに困難を抱えているという認識があると捉えてよろしいのでしょうか。その点を確認していきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"飯沼委員","kind":"提案","question":"すみません。最初のご説明は伺ったんです。１点です。ぜひ、そこに注目してほしいのは、私は、だから私が聞いたのはごく一部の方の意見だと思います。だから、コストの面っていろいろあるかもしれませんけれども、ぜひ工夫をして、まちを元気にするという立場でとっても有効だと思うので、ぜひこの請願の趣旨を受けとめていただいて、区も考えて、交通会議に提案してほしいなと思うのですがいかがでしょうか。","respondent":"藤田都市計画課長","answer":"やさしいまちづくりというお話がございましたけれども、やさしいまちづくりは、私ども、これをやめてしまったということではなく、しっかりこれは進めていかなければいけない事業だと考えてございまして、今年度・来年度を含めて。","id":"exchange-075"},{"speaker":"こんの副委員長","kind":"質問","question":"この請願に関連して、今定例会のときにもご質問が若干ありましたけれども、現状をちょっとお聞きしたいのですけれども、地域公共交通会議、これの今の進捗状況、それからスケジュール的にはどうなっているか。あのときたしか、学識経験者の方等のことがあったかと思いますけど、もう一度そこのところを教えてください。","respondent":"藤田都市計画課長","answer":"おおむねその辺も見通しがついてきてありますので、今、最終的に現況報告がきっちりできるような準備を進めまして、いつというお約束をすると、また時期がずれてしまうと大変申しわけなく思うのですが、少なくとも当初の予算の中では。","id":"exchange-076"},{"speaker":"こんの副委員長","kind":"提案","question":"私どもも、このバスという観点、それから公共の交通というところでは、非常に大事であるといったことから、地域公共交通会議で提案をさせていただいて、そこで慎重に今後のあり方というのをぜひ検討していただきたいということを考えます。ですので、この八潮の地に限らず、品川区全体のことを考えていただくということが大事かなと考えていますので、その状況をお聞きしたところであります。結構です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-077"},{"speaker":"伊藤委員","kind":"質問・要望","question":"これから少子高齢化が進む中では、国、東京都、それから品川区が一丸となった福祉のまちづくり、総合的なまちづくりを展開していってくださいということを改めて要望すると同時に、八潮地区の交通での改修については、せっかくオリンピックの会場にホッケー場ができるわけですから、そういう時期を捉まえて、これこそ国、東京都と連携をとって、例えば新駅をつくっていくなり。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-078"},{"speaker":"こんの副委員長","kind":"質問","question":"私どもは、先ほども少し状況をお聞きしました地域公共交通会議、この中でしっかり慎重に決めていただくというのが大事であるという、こうした姿勢から、八潮に限らずという、区全体の会議が必要ということから、本請願に対しては不採択といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-079"},{"speaker":"飯沼委員","kind":"質問・要望","question":"採択を主張します。ちょっと意見。コミュニティーバスは区民が求めています。区内移動、不便なところがあります。介在して、ぜひ区内移動がスムーズにできるように。特に高齢者、体の不自由な方々、妊婦さん、お子様連れなど、外出が楽しめるようなやさしいまちをつくっていくというところで、ぜひコミュニティーバス路線の確保を必要と認識していますので、採択を主張いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"},{"speaker":"西本委員","kind":"提案","question":"ただ単に１日に２本とか３本では意味をなさない。ただ、税金を使っても効果があるんだよということであれば、それは前向きに考えていただきたいと思いますし、それでもほかの公共施設があるので、交通がいろいろあるので、それをもっとうまく組み合わせながら使っていただくような工夫があってもいいんじゃないかというところでの、改善提案も含めてお願いしたいなと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-081"}]},{"id":"topic-07","title":"平成２５年請願第１８号、「容器包装リサイクル法を改正し、発生抑制と再使用を促進するための法律の制定を求める意見書」の採択を求める請願","agenda":"平成２５年請願第１８号、「容器包装リサイクル法を改正し、発生抑制と再使用を促進するための法律の制定を求める意見書」の採択を求める請願","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"請願要旨のところについて、ちょっと区の認識をお伺いしたいなと思います。環境によいリユース容器が激減しているということと、リサイクルに適さない容器包装がいまだに使われているのが社会の実態ですと書いてあるんですが、この辺の認識をお伺いしたいのが１点と、先ほどご説明の中で、自治体の負担が大きいと。ちょっとその大もとのところをお聞きしたいと思います。","respondent":"小林品川区清掃事務所長","answer":"それから今期のものは、１２月までに各業界のヒアリングを五、六回やって、それからその役割分担も含めたところに検討の駒を進めていくというふうに聞いておりますので、その中で、そういった課題、役割分担といいますか。","id":"exchange-082"},{"speaker":"飯沼委員","kind":"質問","question":"こういった意味で、自治体のコストもそうですけど、環境対策にもすごく役立つという意味では、リサイクル中心ではなくて大もとのところを減らしていくという意味では、とても、拡大した製造者の責任を追及していくというのは、拡大生産者責任を追及していくというのは、自治体にとってもすごく大事なことでもあるので、ぜひ力を入れていくべきだろうと思うんですが、その点はいかがでしょうか。","respondent":"小林品川区清掃事務所長","answer":"確かに、流通経路云々ということですが、考えようによりますと、売れないものはつくらない、売れるようにつくるというのが、事業者の基本的な、利益追求の基本ですので、それから言うと、それは全て事業者の責任なのかなというところから言うと、やはり消費者も含めて。","id":"exchange-083"},{"speaker":"飯沼委員","kind":"質問","question":"地方自治体がどんどん意見を言っていくことだと私は思っているので、この意見書を出していくのもすごく大事だと思うのですが、とにかくごみ行政で、出たごみをどうするのかでは解決しないと思うんですね。そういった意味では本当に、拡大生産者責任を果たしていくということは自治体の共通の願いでもあると思うんですけれども、最後になりますけどいかがでしょうか。","respondent":"小林品川区清掃事務所長","answer":"その辺をもって、事業者にも協力・負担を求めていくと同時に、区も大切な仕事の一つとして、おっしゃるとおり、達成したものをとるだけではなくて、それをどういうふうに社会として活かしていくのか、適正排出していくのか、減量していくのかというところの意識。","id":"exchange-084"},{"speaker":"飯沼委員","kind":"質問・要望","question":"意見を一つだけ。今のに関連。すみません。最後と言ったんですけれども。拡大生産者責任は、ごみ問題解決の切り札と言われているんですね。回転にとってもプラスになるし環境負荷も少ないと。それでごみが減っていくということなのでね。ぜひこの点を皆さんにもしっかり受けとめていただきたいなと思います。意見で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"},{"speaker":"伊藤委員","kind":"質問・要望","question":"非常に難しい判断を求められたと思っています。そういう可能性は当然あるわけであって。だけれども、ここで言っているのは、拡大生産者責任を盛り込むこととイコールだから、それだけで私たちは解決すると思っていないんだけれども、難しい言い方かもしれないけれども、この問題の解決といいましょうか、品川区が今現在考えているベストな解決方法はどうお考えなんでしょうか、お答えください。","respondent":"小林品川区清掃事務所長","answer":"この辺に、今ご質問いただきましたことの回答のヒントがあるように思います。つまり、一定の可能性を決めたら、それに対する準備期間を持って、そして、それに対する三者のそれぞれの合意形成の期間を持って、一歩前に踏み出していく。","id":"exchange-086"},{"speaker":"伊藤委員","kind":"質問","question":"まあそうですね。三者の合意形成。やっぱりやるとなれば、区に全体の制度があって、その中で、例えば飲料会社ですか、そういうところと、例えばこういうことを契約していくとか、そういうふうに話をやっぱり具体化していかないと、この話はどんなに地方自治体が頑張ったとしても、態度、出ないんじゃないでしょうか。ですから、たしかこれは平成２２年に同趣旨の請願を趣旨採択されたかと思います。","respondent":"小林品川区清掃事務所長","answer":"その辺の一つ一つの動きについては今後の検討を待ち、前回のときも、三つほど大きな、一つ一つは小さいけれど全体としては大きな合意形成をしてまいりましたし、今回も今、作業状態は、その課題の抽出を、前回、９月にはなさったというふうに会議録では読めましたので。","id":"exchange-087"},{"speaker":"西本委員","kind":"質問","question":"この請願の請願事項ですね。では、物が、ペットボトル１００円、１５０円ですかね、としたときに、ではその維持をしていく。で、今度消費税も上がるという状況を踏まえた中で、誰が犠牲になるのかなと思うと、私はちょっと、もっと広い意味で考えていかないと、ただ単に拡大生産者責任だけで追及できるものではないだろうなと思うんですが、その辺はどういうふうに考えられていますでしょうか。","respondent":"小林品川区清掃事務所長","answer":"で、そこでほぼリサイクルの費用は一時的には賄っているというところまでは、既に事業者は拡大生産者責任を果たしておりますので、その後の費用案分の負担も含めて、どう今後、考えていくのかというのが、次期のテーマになってくるだろうと考えております。","id":"exchange-088"},{"speaker":"西本委員","kind":"質問・要望","question":"かなり今、拡大生産者責任も負っていただいているよという現状もある。で、消費税も上がっていく。一応、会派で議論されての紹介議員になっていると思うので、どういう観点でどこまでのものを意見書として提出すべきと思っているのか、ちょっと確認をさせていただきたいと思うんですけどいかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-089"},{"speaker":"西本委員","kind":"質問","question":"いや、それはわかるんです。だから、何ですかね、今、いろいろな問題点があって、行政側の立場も考え、品川区として意見書を出す上で、どういう観点を持って、考え方で、意見書を提出できるのかどうか。どういうふうに皆さん考えて、この紹介議員になられている会派の方々が紹介議員になっておられるのかというのをちょっとお聞きしたいのですけど、だめでしょうかね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-090"},{"speaker":"大沢委員","kind":"質問・要望","question":"で、次に、上から７行目の、約８割が製品価格に内部化されていないという云々。それと、その２行下の、負担のあり方について不公平感が高まっていますと。こういう事実が三つ並べてありますけれども、このことに関して行政側の考えなり、現状というか、これを教えていただきたいと思います。","respondent":"小林品川区清掃事務所長","answer":"この請願、余談なんですけれど、意見書ということでは、法律の背景、ご説明させていただきましたように、容器包装リサイクル法の条項改正をもって法律としてしようとしているのか、そうではなくて、性格が違うので、趣旨はわかっているけれど、委員長がおっしゃいましたように。","id":"exchange-091"},{"speaker":"木村委員","kind":"質問","question":"この３Ｒというのはもともと、順位が違うというのは、多分、本来の目的というのは、物を減らす、ごみを減らすということではないかと思うんですよ。それで、リデュース、リユース、それからリサイクルですよね。そしてごみを減らすことによって、今の、何というんですか、環境ですか、そういうものを守っていく、維持していくということが目的だと思うんですけども、それはどうなんでしょうか。","respondent":"小林品川区清掃事務所長","answer":"おっしゃるとおりだと思います。","id":"exchange-092"},{"speaker":"木村委員","kind":"質問","question":"そういうことで、消費者が本当に不公平感を感じるというのは、消費者はそういう意味ではものすごく、このリサイクルに対してというか、分別とか、いろんなことに対して努力をしていただいているということを考えても、そしてまたこれが内部化されることによって料金が上がっていくと考えると、やはり一番損をするというのもおかしいですけども、消費者が一番損をするのではないかなと思っているんですけど。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-093"},{"speaker":"こんの副委員長","kind":"確認","question":"さまざまな質問が出ていましたので、１点だけ、ちょっと現状を確認というか、先ほどのご説明の中に、区長会でも、そういう関係のことが出されていたと。ここら辺の様子をちょっと、わかる範囲で、どんな形で議論があるいはされているか、少しわかる範囲でご答弁いただければと思うんですが、いかがでしょう。","respondent":"小林品川区清掃事務所長","answer":"この間、毎年、区長会が国に出していく要望事項をまとめていく時期があります。そのときに、既にもう数年にわたって、この役割分担のあり方、とりわけその役割分担の中を構成する費用分担のあり方についての検討を進めてくださいという意見を上げてまいりました。","id":"exchange-094"},{"speaker":"こんの副委員長","kind":"質問","question":"様子がよくわかりました。そういう様子とともに、本請願で出されている、あらゆる、ほかの議員の質問のご答弁も伺いながら、やはり一定の、区長会で出される、いわゆる自治体としてどうしていくかということの動きも見ますと、そこら辺の動きは一定の理解をするところであります。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-095"},{"speaker":"伊藤委員","kind":"意見","question":"本請願は、私どもも随分議論させていただきましたけれども、この請願が掲げているとおり動いていきますと、拡大生産者責任がことさら強調されている感じがします。これだけでは、私どもとしてはこの目的を達成することは難しいと判断しましたので、本請願については不採択として主張いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-096"},{"speaker":"こんの副委員長","kind":"意見","question":"私どもの会派としても、今回、この請願に対して、実は前回、平成２２年のときにもこのような内容のものが出される中で、また区長会での今のご答弁も見る中で、一定のこの取り組みということに対しては理解をするというところで、本請願に対しては採択をします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-097"},{"speaker":"飯沼委員","kind":"提案","question":"採択を主張します。本請願は、リサイクルでよしではなくて、先に進めるための提案であると受けとめています。先日、ＣＯＰ１９でも、世界から日本のＣＯ２削減、反対に増えてしまうといったことで、世界から批判を受けているところで、やはり環境問題からしても、これは早急に取り組むべきことであるので、意見書を上げていくことという、大変重用なことであると思って、採択を主張いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-098"},{"speaker":"西本委員","kind":"意見","question":"非常に難しいな、判断に難しいなと思っているところです。ただ、拡大生産者責任というところというのは、それだけではなくて、もっと、合意形成という話もありました。やっぱり、ちゃんと深いところでのメリット・デメリットも含めて、しっかりと見据えた形で意見等を出すべきではないだろうかというふうな意見を申し上げて、不採択といたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-099"},{"speaker":"こんの副委員長","kind":"意見","question":"まあ、意見書が、出す、出さないという、それに対しての採択というふうには申し上げましたが、気持ちはよくわかりますし、議会として気持ちはわかり、そして一歩でも進めてもらいたいという、意見をまとめるということでは、趣旨というところでもあり得るのかなと思いますが。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-100"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この大きな趣旨は、国のところに意見を入れていくというところなので、ぜひ、まとめて、意見書を提出していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-101"},{"speaker":"伊藤委員","kind":"質問・要望","question":"たしか、後日確認していただきたいんですけれども、今までの議会の流れからすると、意見書を提出するに当たっては、全会派一致が望ましい形になっているはずですので、それはぜひ確認しておいてくださいということだけお話をしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-102"},{"speaker":"西本委員","kind":"質問・要望","question":"ただ、できる限り、意見書を出すということであれば、全会派一致で出していくべきものだと私も思っていますので、やはり私たち、いろいろなことを考えて、今回はというふうにさせていただいた経緯もありますので、皆さん合意の中で出すんだったら出していただきたい。ただ、今の状況だと合意には至っていないというのが現状だと思いますので、そこを配慮していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-103"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/483820?Template=document&Id=4092#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":85713,"voices":298}},{"id":"h25-20131125-9","meetingId":"h25-cm11","date":"2013年11月25日","dateIso":"2013-11-25","committee":"文教委員会","time":"午前１０時００分～午後１時４６分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を64件抜き出しています。","topics":[{"id":"topic-01","title":"の第７２号議案、指定管理者の指定","agenda":"の第７２号議案、指定管理者の指定","exchanges":[{"speaker":"本多委員","kind":"質問","question":"この候補者の選定理由について３点挙がっていまして、どれも理解できます。それで、これまで指定管理をされていて、これ、議決がされれば、また引き続きということなんですが、予算面はどうなのかなと。やっぱりこの人員配置とか財務状況の維持できるというようなところで、その辺がしっかり区としての体制というのでしょうか、環境整備というのはどうなのかなと、概算で結構なので、その辺を教えてください。","respondent":"立川保育課長","answer":"ぷりすくーるの予算についてですが、現在の運営費につきましては、５年前に国、都の基準等を参考にいたしまして算定したところですので、この間、国の運営費等についても、いわゆる保育単価ですけれども、改定がございましたので。","id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"この説明を読んでみると、選定の方針のところに、運営者に連続性が要求されるというふうに書いてあって、事業の内容からして、保育教育ですから連続性があるのは当然だというふうに思うんですね。うまくいっていると想像はするんですけれども、わからないから、そのあたりについて、どうなっているのかについて、また、問題点がもしあるとしたら、どんな内容なのかを教えていただきたいと思います。","respondent":"立川保育課長","answer":"ぷりすくーる側としましては、このご指摘を受けて、預かり保育の体制を整備するということと、また、保育園については、その都度、丁寧に対応するということで、これまでこの辺の課題については改善を図ってきたです。","id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"具体的に今の答弁で、例えば、２歳児が終了して３歳児への進級に向かって一定のインターバルというと、何日かわからないけれども、保育園をお休み、春休みとか、そういうイメージかなというふうに思って聞いたんですけれども、そういう期間を設ける、そのこと自体が就労に支障されて、何とか解消してほしいというご意見が幾つか出ているという、そういうことだと理解したんですけれども。","respondent":"立川保育課長","answer":"このインターバル期間につきましては、実際はお願いをするということでありまして、当然、保護者の個々の事情によりましては、お子さんをお預かりするという体制を整えましたので、この辺についてはきちんと対応ができるというふうに考えております。","id":"exchange-003"},{"speaker":"南委員","kind":"確認","question":"そこをお願いするものでというふうな表現で、それがどういう内容かちょっとよくつかめなかったので、もう一度そこを質問しなくてはいけないんですけれども、選択できるわけですか。それは別に否定することではないと私は思うんですけれども、しかし、選択できない、休めない方については、その３日間についても預かることができるのか、そこを確認したいんです。","respondent":"立川保育課長","answer":"保育料につきましては、いわゆる条例で定める幼児教育部門の保育料と、預かりの保育料をいただくということになります。選択ができるのかですけれども、こちらについては体制を整えておりますので、預かりについては実施しています。","id":"exchange-004"},{"speaker":"南委員","kind":"質問","question":"わかりました。預かり保育料を別途、その期間の３日分ですか、時間にもよってだとは思うんですけれども、とると。３月いっぱいの保育料は当然お払いし、４月の保育料も払うわけですよね、当然、進級にしていく上に当たっては。それにプラス、この３日間の預かり保育料を払うというふうに私は理解したんですけれども、そうじゃないのか、なかったら、その辺もう少しわかりやすく整理して教えてください。","respondent":"立川保育課長","answer":"保育部門は３月で終わりますので、保育園保育料はそこで終わりまして、４月から新しく幼児教育部門になりますので、こちらは条例で定める幼児教育部門の保育料をいただくということになります。","id":"exchange-005"},{"speaker":"南委員","kind":"確認","question":"その期間の、ここの場合は３日間なんだと思うんだけれども、普通は４月１０日ぐらいが入園式で、それからずっと生活が始まっていきますけれども、ここのぷりすくーるの場合は、１０日間とかではなくて３日間と、そういうことで３日間分のお預かり体制はとるから、預かり保育料はいただきますよと、こういうことだということですか。確認をしたいんですけれども。","respondent":"立川保育課長","answer":"それ以外の預かり、時間的に言いますと、午後２時からの時間については、通常の公立と同じように預かりの保育料をいただくというものです。","id":"exchange-006"},{"speaker":"南委員","kind":"質問","question":"こういうスタイルをとっていたということは、ちょっと不勉強で、初めて３日間のインターバルがあるということは知りました。そういう点について、保護者の方々から改善も含めて意見が出ていたというのは、今年度に限らず、ずっと何年か前からあったのかなと推測するんですけれども、ようやく改善も含めてされたというふうに理解していいでしょうかね。改めてその見解を聞いて終わりにしたいと思います。","respondent":"金子子ども未来事業部長","answer":"今、先ほど来、ご説明しているのは、この特定非営利活動法人、ＮＰＯ法人の子育て品川が、この３日間の、言ってみればチェンジ期間を設けようというふうに設定してきたわけです。","id":"exchange-007"},{"speaker":"南委員","kind":"意見","question":"言いにくいからずっともうこういう状況で来ているわけだなというふうに思うわけです。ほかの保育園と違ってはならない、同じように穴を埋めていくという、そういうことはしっかり努力していただかないと、お願い程度にとどめてくれというふうに言ってきたという、そういうことでは、私は区はもっとしっかりはっきりと指導するべきだというふうに思います。そのことは意見として言っておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"塚本委員","kind":"質問","question":"質問は、指定期間なんですが、平成３１年３月３１日までということで、５年間ということになっておりますが、これは本会議などでも質問がありましたけれども、子ども・子育て支援新制度によっていろいろな変化が起こり得るであろうということが予測される中で、この５年間という中で指定管理がいろいろそういう制度との整合性の中で、何か５年間でもちょっと大丈夫なのかなと思ったんですけれども。","respondent":"立川保育課長","answer":"こちらにつきましては、今後、国のほうから新しい幼保連携型認定こども園の基準や法定価格、また、法のインセンティブ等も示されてくるということになりますので、それらを踏まえまして慎重に検討してまいりたいというふうに考えております。","id":"exchange-009"},{"speaker":"塚本委員","kind":"質問","question":"そうすると、これはいわゆる柔軟に、場合によっては、この指定管理というような制度を見直したりとか何とかというのは、特別ハードルがないというか、制限とか規制とかという部分で、子ども・子育て支援新制度との障害的なものというのは、あまり考えなくてもよいということでしょうか。施設運営側にとって、いろいろな柔軟な判断ということを妨げるものではないという認識でよろしいんでしょうか。","respondent":"立川保育課長、金子子ども未来事業部長","answer":"今回、５年間ということで議決をいただくということになりますので、やはり制度的に変更するということになりましたら、また改めて議会のほうにお諮りするということにはなるかなというふうには考えております。ただ、国のほうが新しい形を示したときに、私ども区としまして、この施設がどうあるべきかということを検討した際に、もし仮に違うような選択肢をとる場合には、またこれは議会にお諮りすべきものというふうに考えているところです。","id":"exchange-010"},{"speaker":"高橋委員","kind":"質問","question":"それからもう一つは、今、平成２７年からの新制度について、いろいろな選択肢があるというお話があったんですが、仮に、もし違った形態がということになった場合は、これまであったぷりすくーるの条例でしょうか、それを変えたりなくしたりということも視野に入れていくことになるのかと思うんですが、その点についての見通しというか、そういったところです。","respondent":"立川保育課長","answer":"今後、平成２７年の制度変更に伴って、ぷりすくーるの形態等を変えていく必要があるというときに、条例等の関係はどうなるのかというところのご質問ですけれども、こちらは、現行の条例のままでは。","id":"exchange-011"},{"speaker":"高橋委員","kind":"提案","question":"条例については、これは仮定の話になってしまうので、新しい仕組みになったとすると、また検討が必要になってくると思いますが、これは先ほどの国の基準とかともかかわってくると思うので、そこではまた議会のほうで提案していくことになるかと思います。最後、行革の視点というのをもうちょっと詳しく言っていただけると、行革担当課長が入っているというところで。","respondent":"立川保育課長","answer":"実際にどういった効果があったかですけれども、繰り返しになりますけれども、民間のノウハウ等を導入しまして、よりよい施設運営をしていくというところで、それなりの効果があるというふうに認識しています。","id":"exchange-012"},{"speaker":"南委員","kind":"質問・要望","question":"やっぱり区民にとって利用しやすいものに区としては指定管理してお願いしているわけですから、住民の、そういう利用者の方々の意向をしっかり受けとめて、お願いするという、そういう弱腰ではなくて、きちんと指摘、指導するべきだというふうに思うんです。改善をするべきだというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"}]},{"id":"topic-02","title":"第６６号議案、平成２５年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第６６号議案、平成２５年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"本多委員","kind":"質問・要望","question":"このＪＴＥのことをもう少し詳しく教えていただきたいんですけれども、これはあえて補正で取り組まれるというところ、新年度から実質的に速やかにスタートするその準備期間なのかなと思うんですが、この補正であえて組んで、年度内にやるというのは、まずＪＴＥの配置、グローバル人材養成塾ですか、この辺を立ち上げていく、その辺のところをもう少し詳しく教えていただきたいんですけれども。","respondent":"渋谷指導課長","answer":"中学校のほうのグローバル人材養成塾についても、基本的には４校を拠点にして、全中学生を対象に募集をするようなイメージで考えておりますので、実際に運営するために場所はどうするのかとか、他校生が来るときにどうなのかだとか。","id":"exchange-014"},{"speaker":"本多委員","kind":"質問・要望","question":"それと、小学校の４年生を対象に英語漬けの一日を過ごす日帰りのイングリッシュ・キャンプなんですけれども、大体時期が３月で、場所未定ということなんですけれども、文字通り英語漬けで、基本的には日本語を使わないで全て英語でやるという、本当に英語を楽しむとか、英語の音に慣れるとか、まさにそうだと思うんですけれども、この辺の取り組みというのは、４年生対象で、規模とか。","respondent":"渋谷指導課長","answer":"今年度のモデル実施については、現在、場所も含め選定中です。","id":"exchange-015"},{"speaker":"本多委員","kind":"意見","question":"わかりました。モデル校が対象ということ。これ、補正でモデル校、小学校３校、中学校４校ということですけれども、最初はこうやってモデル校で始めていくということなんでしょうけれども、充実して、いずれ全区展開等をうまく目指していっていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"南委員","kind":"質問・要望","question":"１年生から年２０時間ある、あと３５時間というふうになってはきていても、単語ぐらいはいろいろ記憶力も豊かな時期ですから覚える、いいのだろうと思うけれども、一日とはいっても、日本語は使ってはいけないという、こういう状況が、どういうあれかなと、全然想像ができないので、その辺、ひとつどういうふうなレベルまで皆さん行けているのかというのが知りたいなと。","respondent":"渋谷指導課長","answer":"１点目のどういうレベルかということについては、まさにこのレベルについては、これから検討課題になってくる部分で大きいところです。","id":"exchange-017"},{"speaker":"南委員","kind":"質問","question":"希望者なのか、今回はモデル校の４年生全員なのか、そこの辺を知りたいなと思いました。それで聞いているんですけれども、そのあたりはどんなふうに検討されて、実際、日本語による読解力の促進をどういうふうに果たしてきているか、そこでの今回のこれをどういうふうに見てこういうふうにしたのかというところを改めて伺いたいと思います。","respondent":"渋谷指導課長","answer":"せっかくこういった取り組みをして英語嫌いの子をつくってしまっては、これは元も子もありませんで、子どもたちが意欲的に、積極的に、モチベーション高く学べるような、そういうプログラムをぜひしっかり考えていきたいというふうに思います。","id":"exchange-018"},{"speaker":"南委員","kind":"質問","question":"当然、小学生、中学生ですから、そういうことは心配はないと思うんだけれども、しかし、理解力だとか、そういうことが、率直に言って、品川の子どもというわけではないですよ、これも一般論なんだけれども、なかなか劣っているという状況も少なからず見受けられるという中では、やっぱり私は、あんまり急いでいるのかなと、今やっていることで十分ではないかなと思うので。","respondent":"渋谷指導課長","answer":"これも今回、補正を通していただければ、モデル実施する中で、子どもたち全体でどのぐらいの需要があるのか、そういったものをつかんで、また、中学校は部活によって曜日が違いますので、例えば、同じ内容で週に何講座か開設して、月曜日の都合のいい子は月曜日に出るし。","id":"exchange-019"},{"speaker":"塚本委員","kind":"質問","question":"私は、自分の時代の英語というのは、中学まで出ても、単語は知っているんだけれども、全然会話ができない、いざ外国人の方と話しても何を言っているか全然わからないということで、全然使えないということでよく揶揄をされた世代でもあるんですけれども、ちゃんと話ができて、コミュニケーションがとれるという能力をつけていくという観点で進めていくということは。","respondent":"渋谷指導課長","answer":"今回はモデル校に１週間から１０日ぐらい実際に入っていただく経費になりますので、その部分の報償費ですので、全体の額としてはあまり大きくないです。","id":"exchange-020"},{"speaker":"塚本委員","kind":"質問","question":"通常はどういう形になりますか。ＪＴＥというのは、普段はどういうことをされている方たちが来られるんですか。塾か何かで英語の指導をやっていらっしゃる方とか、そういう感じなんですか。","respondent":"渋谷指導課長","answer":"今後はそういった方たちの養成をということをまた考えているわけですが、とりあえず今回、３月にモデル校へ来ていただく方につきましては、今、実際、小山台小学校に入っている大学でその先生のご指導を受けている中高の英語の教員免許を持った大学院生を想定しています。","id":"exchange-021"},{"speaker":"塚本委員","kind":"質問","question":"今までは学級担任が主導してやっていたということなので、今回でもＪＴＥが主になるということで、授業をいわゆる仕切る、担任の方が補佐はされるのだと思うんですけれども、その辺の、今、大学院の方ということで専門性は高いと思うんですが、やっぱり経験という意味では、やや初めてということになるので、その辺の配慮というか、やっていただくにあたっての研修と言うと大げさかもしれませんが。","respondent":"渋谷指導課長","answer":"今、予定されている方は、もう既に小山台小学校でご指導をしていただいたりだとかというようなことで経験を積まれている方を今のところ、まだ確定はしておりませんけれども、やっていただけるように交渉をしています。","id":"exchange-022"},{"speaker":"塚本委員","kind":"質問","question":"わかりました。こういうＪＴＥ、Ｔ１、Ｔ２という体制がいいのか、やっぱり一人の人が能力を持ってやっていくほうがいいのか、そういう人材を今後募っていくというか、両方で構成するのがいいのかというのは、どのようにお考えでしょうか。","respondent":"渋谷指導課長","answer":"これも今後、英語推進会議で検討しなければいけない事項ではありますが、今の品川の体制で言うと、特に英語に限らず、５年生以上は教科担任を進めて、より専門的な学びができるような環境を整える方向ですので、英語についても。","id":"exchange-023"},{"speaker":"大倉委員","kind":"質問・要望","question":"確認と教えていただきたいんですが、４年生を対象にイングリッシュ・キャンプ体験教室なんですが、これはどういう形でやるのかというご説明をちょっと、あまりイメージが湧かないので教えていただければと思います。","respondent":"渋谷指導課長","answer":"本当に詳細については、今まさに検討中ということで、先ほどもちらっとご説明しましたが、自校でそのまま会場にするのがいいのか、または全然別の環境のところでやることがいいのか、本当に考えているところです。","id":"exchange-024"},{"speaker":"大倉委員","kind":"質問","question":"例えば、これが実際やることになったときに、参加する方の参加費が、保護者の方たちの負担というのはどうなってくるのかなというところだけ教えていただけますか。","respondent":"渋谷指導課長","answer":"その場所だったり、提供できるプログラムの中身によって、費用だとか予算の問題も随分関わってくることですので、校長会だとか、そういったところとまた検討しながら進めさせていただきたいというふうに思っているところです。","id":"exchange-025"},{"speaker":"大倉委員","kind":"質問・要望","question":"これから決まっていくことだと思うので、そういった参加費とかも含め、参加しやすいような取り組みというか、体制というか、つくっていただきたいなと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"高橋委員","kind":"質問","question":"その問題があるとして、この日本人の方がやることになったとして、どういう形で雇用していくのかわからないんですけれども、そこの課題が解決していくのか、それともどうしても法的なところからだとすると、それをカバーするような学校体制はどのような形をお考えなのでしょうかということが一つ。","respondent":"渋谷指導課長","answer":"２点目の小中一貫校、特に施設一体型の一貫校で、中学校分を担当している英語科教員の方については、基本的には、その英語の先生の持ち時数は、その中学校分を担当する部分で、少人数等々をやっていますので、もう既に目いっぱいですので。","id":"exchange-027"},{"speaker":"高橋委員","kind":"意見","question":"今、非常勤の形で指導されるようになれれば、先ほどの担任の先生とのコミュニケーションも十分とれるし、学校全体としても進められるのではないかと思うので、せっかくこういった取り組みをされているんですが、それがプラスに行くような体制、ちょっといろいろな法的なあれがあるので難しいですけれども、お願いできればと思います。小中一貫校のほうはわかりました。ありがとうございました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"},{"speaker":"南委員","kind":"質問・要望","question":"聞きそびれてしまったので、もう一度質問したいんですけれども、こういうシステムにレベルアップしていくことについて、ＪＴＥについては現場から歓迎されるというお話だったんですけれども、現場からどのくらいの要望があるのか。三つ目は、先ほど、参加費のことがあったんですけれども、自己負担になっていくのか、そのあたりを教えてください。","respondent":"渋谷指導課長","answer":"事務局で考えて、また、小山台小学校の実践等々を踏まえて検討して出てきた案です。この後、また英語推進会議等で現場の校長先生なんかにも入っていただきながらやりとりをして詳細を詰めていくというふうなことです。","id":"exchange-029"},{"speaker":"沢田副委員長","kind":"質問","question":"検討中ではありますけれども、これは３年生で３５時間というのは、今、大体週１回はやられているということだと思いますけれども、大体どれくらいを増やされるということなのかお伺いしたいと思います。","respondent":"渋谷指導課長","answer":"ただ、今、そうしますと、例えば五、六年生、急に英語を３時間というと、２時間分どこから出すのかというふうな大きな問題が関わってきますので、そういったこの時数については、国の動向を十分に注視しながら。","id":"exchange-030"},{"speaker":"沢田副委員長","kind":"質問・要望","question":"限られた授業時間、日数の中ですから、やはりほかの大きな急激な変化ということはないかと思うんですけれども、英語でコミュニケーションをとれるようになっていく子どもたちを育てていくという意味では、やはりある程度の増加は必要だとは思いますけれども、ほかの授業とのバランスをよく考えながら、ぜひともこの事業を推進していっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"南委員","kind":"質問・要望","question":"ここの中で、例えば認証保育所は株式会社立の認証保育所が何件か、法人がどのくらいか、運営主体の種類別に何カ所あるのかを、認証保育所と保育ママとでそれぞれ教えていただきたいと思います。","respondent":"立川保育課長、今井制度改革・待機児童対策担当課長","answer":"運営主体のご質問ですが、認証保育所は全２０園ございまして……。私のほうで家庭的保育事業のほうを所管しておりますので、家庭的保育事業のほうを先に説明します。認証保育所につきましては、２０園中１５園が株式会社立でございまして、個人立が２カ所、ＮＰＯ法人立が２カ所、あと、有限会社立が１カ所です。","id":"exchange-032"},{"speaker":"南委員","kind":"確認","question":"認証保育所を確認したいんですけれども、法人はなかったでしたか。今、答弁ありましたか。聞き漏らしていたんだったらあれですけれども、そのあたりはもう一回言ってくださいますか。株式以外のところ。","respondent":"立川保育課長","answer":"社会福祉法人立はございません。ＮＰＯ法人立は２カ所あります。","id":"exchange-033"},{"speaker":"南委員","kind":"質問・要望","question":"全般でいいですから教えていただきたいと思います。そういう点で処遇改善しようということで、今回、これ、東京都の補助金として来るものを使っていると思うんですけれども、本来であれば、株式会社ですから、自分のところの利益から人件費として生み出すべきではないかなというふうに思っているんですが、そのあたりについてどういうふうに見解を持っているのかを伺いたいなと思います。","respondent":"立川保育課長","answer":"あくまでも、補助金は処遇改善の一部に充ててほしいという考え方ですので、今回の補助金額を上回る改善計画の提出を求めているものです。２点目の身分ですが、こちらは正規職員または非常勤職員というふうに認識しています。","id":"exchange-034"},{"speaker":"南委員","kind":"確認","question":"事業所で一部プールしてしまうとか、そういうことがあってはならないというふうに思いますので、せっかく公費で定着も含めてそういう目的があって出すわけですから、きちんと目的を果たすというところの確認をどういう形でとろうとしているのかをひとつ伺いたいと思います。","respondent":"立川保育課長","answer":"非常勤職員を多く採用しているところもありますので、一人当たり一律月額９,０００円以上の処遇改善されるというふうには認識していないところです。","id":"exchange-035"},{"speaker":"南委員","kind":"質問","question":"すべての保育者に一定の処遇改善として支給するという前提に立ったときには、９,０００円には当然ならないわけで、低まるということになるんだというふうに思うんですけれども、それはそれとして、東京都との補助金の関係ではあるわけですけれども、その基準以上配置している認証保育所というのが、今の現状で、どこの園なのか、どのぐらいあるのか、それがわかれば教えてください。","respondent":"立川保育課長","answer":"その辺の資料につきましては、現在、持ち合わせておりませんので、わかりません。","id":"exchange-036"},{"speaker":"南委員","kind":"質問・要望","question":"私は、後ででいいですから教えていただきたいというふうに冒頭お願いしておきたいと思います。したがって、実績報告で確認するというお話なんですけれども、それは具体的にどういうことなのか。確認をしたいと思います。","respondent":"立川保育課長","answer":"実績報告の内容につきましては、今回の補正予算が認められましたら、事業者とも協議していくべきというふうに考えております。","id":"exchange-037"},{"speaker":"南委員","kind":"質問・要望","question":"ぜひ確認をして、一園一園確認をしていただいて、きちんとご本人に渡るように指導していただきたいと、強くそれはお願いをしておきたいと思います。それから、今回のこの措置というのは、今回１回限りで、来年度以降の給与にこれが反映するというものではないのかなと思うんですけれども、そのあたりはどうなんですか。","respondent":"立川保育課長","answer":"処遇改善自体は、各事業者において実施されるものです。それに対して、国と都の補助が今後もあるのかですが、それについては、まだ未定です。","id":"exchange-038"},{"speaker":"南委員","kind":"確認","question":"したがって、ちゃんとその次の年度からは、株式会社であればきちんと利益を確保する前に処遇改善を適用しなさいという、そういう指導をするべきだというふうに思うんですけれども、そのあたりの確認をして終わりたいと思います。","respondent":"金子子ども未来事業部長","answer":"これは来年度予算にかかわるものですから、これも今、国や都は明らかにしていないわけですけれども、これは私どもとしては、そういうものについても、つなぐという意味で継続すべきものだというふうには考えているところです。","id":"exchange-039"},{"speaker":"南委員","kind":"質問","question":"そういう方針を持っているわけですから、株式会社で働く方々もしっかりとそこの職場を継続して働き続け、そのことが品川区の保育、子育てによく貢献できるようにするという点では、区のほうの支援は支援として必要だとは思うんですけれども、だからといって、税金を投入するということではなく、やっぱり株式会社たるところの利益を処遇に充てていくと、そういうところをきちんとやるべきだと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"南委員","kind":"質問・要望","question":"今の保育のほうのところは、要望も意見もつけて賛成ですが、英語のほうは、さっき言ったような角度で、今の子どもたちに負担が重なるのではないかなと心配をすごくします。したがって、補正予算の文教委員会分は反対、こういうふうになります。残念ですけれども、そういうことです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"}]},{"id":"topic-03","title":"平成２５年請願第１４号、品川区私立幼稚園児保護者負担教育費軽減の為の請願","agenda":"平成２５年請願第１４号、品川区私立幼稚園児保護者負担教育費軽減の為の請願","exchanges":[{"speaker":"本多委員","kind":"質問・要望","question":"私は聞いていて、区別とか差別は、これはぜひなくて、そういう隔たりをなしにしていただいて、子どもたちのためですから、そういう思いで先ほどは聞いておりました。この請願につきましても同じ思いで、公立、私立の隔てをなくして、子どものために考えていただきたいと思うんですが、その思いを聞かせていただきたいと思います。","respondent":"立川保育課長、金子子ども未来事業部長","answer":"私立については、平成２４年度ですが、区内の平均保育料がおよそ２万６,３００円で、補助額が最も多い階層、年収としまして６８０万円までの世帯ですけれども、こちちについては月額で１万５,７００円の補助を実施していますので。ですので、私どもは今、課長が申し上げたとおり、どの子も同じような教育が受けられるような環境づくりをしていかなければならないと考えていますが、今の大きな国の動きも注視しながら。","id":"exchange-042"},{"speaker":"南委員","kind":"質問・要望","question":"請願項目の１番の所得制限撤廃のところの議論が、今されていると思うんですけれども、私も教育費の負担の公平化というのは当然だというふうに思うし、どれだけ補助していても、現実的には２,６００円の差が出ているというふうな、そういう現状があると、そういうことで所得制限をなくしていただきたいという、そういうご要望だという、それがまず第一のご要望だというふうに思って受けとめているわけです。","respondent":"立川保育課長","answer":"それで、これまで徐々にではありますが所得制限を緩和して対象者の拡大をしてまいりました。今後についても、対象者の拡大の方向で考えていきたいというふうに考えております。","id":"exchange-043"},{"speaker":"南委員","kind":"質問・要望","question":"対象者の拡大、補助を受けられるそういう方々の数を増やしていきたいという、そういう趣旨なのかなと思ったんですけれども、私が質問したかったのは、ここの３ページのところに書いてある、下の段のところに書いてある生活費に占める教育費の負担増という、こういう問題、そういう教育費を捻出するために本当に努力をしているという、こういう区民の実態。","respondent":"立川保育課長","answer":"先ほど部長からも答弁ありましたとおり、国のほうでは幼児教育の無償化という流れがございまして、現在のところ、いわゆる低所得者および多子世帯について軽減を図るということを考えているところですので、区としましても。","id":"exchange-044"},{"speaker":"南委員","kind":"質問・要望","question":"私は、やっぱり全ての子どもが保育、教育を受ける権利を持っているし、最善の条件の中で処遇されていくべきだというふうに思っているわけです。これはいろいろやりとりした中で、それ以上質問しませんけれども、そういう立場にしっかり来年度こそ立つべきだというようなことを強く求めて終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"本多委員","kind":"質問・要望","question":"結論を出していただきたいと思います。態度につきましては、採択を主張いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"南委員","kind":"質問・要望","question":"私も結論を出していただきたいと思います。態度は、採択にしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"}]},{"id":"topic-04","title":"平成２５年請願第１７号、一人ひとりの子どもが大切にされる品川区を求める請願","agenda":"平成２５年請願第１７号、一人ひとりの子どもが大切にされる品川区を求める請願","exchanges":[{"speaker":"南委員","kind":"意見","question":"１番の保育所最低基準以上と、当然なんですけれども、保育所最低基準というのが改めてどういうものか、品川区はこれと対比して、今、どういう現状にあるのか、まずそれをお尋ねしたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"項目２におきます屋外遊戯場につきましては、満２歳児以上で屋外遊戯場を設置する、ただし、付近の適当な場所で代替可とされているところです。","id":"exchange-048"},{"speaker":"南委員","kind":"質問・要望","question":"それが最低基準で、品川区の区立保育園がどうなのかと一園一園聞くことは大変なのであれですけれども、大体職員の配置、そして保育室の広さ等々、園庭もそうなんですけれども、これについて大体どんなような、定員拡大もしているわけだし、弾力化ということで子どもを定員以上に預かっているわけですから、そういう点で現状はどうなっているのか。","respondent":"今井制度改革・待機児童対策担当課長、立川保育課長","answer":"今、詳細なデータは持っておりませんけれども、事務事業概要におきまして、定員と在籍数を比べますと、大体１０６％を超える在籍数ですので、平均するとその程度だです。認可保育園につきましては、定員拡大等していますけれども、全て面積および人員配置につきましては基準をクリアしています。","id":"exchange-049"},{"speaker":"南委員","kind":"確認","question":"改めて再確認なんですが、定員拡大、そして弾力化した上で、この基準にはオーバーしているところはないということでいいわけですか。","respondent":"立川保育課長","answer":"はい、そのとおりです。","id":"exchange-050"},{"speaker":"南委員","kind":"質問","question":"とりわけ公立保育園ですから、それは当たり前だというふうに思います。それで、大事なことは、この基準そのものが決して優れた、そういう基準ではないという、そこのところは認識をしておかなくてはいけない点だというふうに思います。そして、もっと最低基準そのものを広げる、そういう立場に立つべきだというふうに思っているんですが、そのあたりについての区の認識はどうでしょうか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"これは開設に当たりましても、運営に当たりましてでも同じですが、最低基準は、子どもを心身ともに健やかに育成することを保障する基準だというふうに考えております。一定の環境は十分保障しているものと考えております。","id":"exchange-051"},{"speaker":"南委員","kind":"質問・要望","question":"今まで品川に限らず、最低基準をもっと引き上げてほしいという声はたくさん出ていました。品川に限らず、全国的なところの水準も含めてですけれども、そういう点では、今の基準をクリアしているからいいという立場には立っていただきたくないというふうに思うんですね。だけど、そういう制約を乗り越えていこうという、そういう姿勢に立っていただきたいと思うわけです。その辺についての見解はどうですか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"こちらの最低基準につきましては、十分子どもたちの健康、そして心身ともに健康が保障されている基準というふうに認識しておりますので、区としましては、保育所のこちらのほうの基準を満たした認可保育園、そしてさまざまな事業などの基準を満たした家庭的保育事業。","id":"exchange-052"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、そういう点で代替があるからいいというふうに済ませないでいただきたいし、これから園庭のある、そういうことを確保させるような指導を、多様な設置主体が品川区内で保育園を運営していきたいというふうな申し出があった際には、そこはしっかり押さえていただきたいというふうに思っているんですけれども、その点について伺いたいと思うし、先だって、８月だったか９月ごろ。","respondent":"今井制度改革・待機児童対策担当課長","answer":"その面では、委員も今ご指摘されましたように、この品川区でなかなか園庭を確保して、さらに少し保育園の運営が安定できる規模の保育園をつくっていくのは、私どもも含めて、大変難しい条件にあります。","id":"exchange-053"},{"speaker":"南委員","kind":"質問","question":"とりあえずいいです。ほかの方が質問あると申しわけないから。制限されてしまうと、ちょっと嫌な気持ちになってしまうので、ちょっとやめておきます。ほかの方に譲ります。後でやります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"南委員","kind":"質問・要望","question":"今、そのようなご答弁があったんですけれども、私はぜひ必須条件だという、そういう認識に立っていただきたいんです。園庭については必須条件。先だって、保育園を……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"南委員","kind":"質問・要望","question":"いや、大事な最低基準に入っているでしょう。最低基準ですよ、前提は。違うのだったら違う立場で質問してください。確保しなさいということですから。そういうところで子どもを育てていいんでしょうかと思いますので、やっぱり子どもの保育に欠かせない最低基準の園庭を備える、ここはもう最大限頑張っていただきたい、こういうふうに思うんです。改めてその点について見解を伺いたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"大きく２点のご質問です。屋外遊戯場、そしてそれにかわる代替地が果たす役割、これはやはり子どもが自発的に活動できる場所、そして環境に触れ合う場所だというふうに考えております。この保育所保育指針に定められた機能が果たせるように、今後も開設を進めてまいります。","id":"exchange-056"},{"speaker":"南委員","kind":"質問・要望","question":"ぜひ保育園の機能が果たせるように、条件をきちんと全てに網羅できて、整っていけるように、最低基準をしっかり備えつけられた、少なくとも最低基準ですから、備えつけた保育園で開設できるように、品川区としてしっかり対応していただきたいというふうに改めてそこの点はお願いしたいと思います。そういうことも含めて、区立でつくるということについての見解を伺いたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"品川区は、もちろん児童福祉法におきまして実施責任は品川区、区市町村にあるものというふうに十分認識しております。","id":"exchange-057"},{"speaker":"南委員","kind":"質問","question":"今、さまざまな力を集めないとという表現をされたんですけれども、このことは否定していないんです。私は繰り返し言っていると思いますけれども。現実的に４月、３月の初め頃かしら、入園申請の可否が届きますよね。来年度がどうかはわからないですよ。だけど、全然区のほうの答弁も変わらないわけですから、言わなくてはいけないというふうに思っているので言うわけですけれども。答弁をお願いします。","respondent":"金子子ども未来事業部長","answer":"そのように一方できちんと待機児童対策を実施しながら、じゃあ、財政負担は考えなくていいのかということには絶対ならないと思います。私ども、自立した地方自治体です。","id":"exchange-058"},{"speaker":"南委員","kind":"質問・要望","question":"将来の財政負担、働いていただければ税金だって入ってくるじゃないですか。将来の財政負担、財政負担と、かかることばかり強調されるけれども、納税者として働いて税金を納めているじゃないですか、そういう部分を何で差し引きしないの。本当に女性が働き続けられるような環境づくりを、ずっと品川区だって次世代育成の計画を持ってやってきているじゃないですか。土地と財政のことも含めて答弁してください。","respondent":"金子子ども未来事業部長","answer":"繰り返しの部分もあるかと思いますが、まず財政の問題ですけれども、今現在は所管ではありませんので究極なところの答弁はできませんけれども、ただ、各事業部にあったとしても、将来の財政ということも考えないで施策をどんどん進める。","id":"exchange-059"},{"speaker":"南委員","kind":"質問・要望","question":"この間もしてきました、と思います。そういうふうに受けとめています。これ以上は平行線ですから言いませんけれども、ぜひ来年度については、待機児がゼロになるようにしっかりと努力をしていただきたい。最後に、この請願の前文に出ているように、保育園の定員拡大というのが書いてありますけれども、ここについての見解は、私ども共産党とはちょっと違っているということは指摘をしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"本多委員","kind":"質問・要望","question":"本日結論を出していただきたいと思います。態度につきましては、不採択です。それと、また将来の財政等もしっかりと区が見据えてというところも、この辺はやっぱり重要なポイントだと思いますので、理由としてはそういうふうに述べさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"塚本委員","kind":"意見","question":"前文のほうにはいろいろ保育に対することも書かれておりますが、請願項目を見てみますれば、特段採択に値するような、要するに、最低基準と言っていますけれども、これは保たれているという現状があるということですし、公園やなんかについても、もちろん自治体が責任を負って今管理をされているという現状の中で、こういった請願について特段採択をすべき必要はないということで不採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-062"},{"speaker":"大倉委員","kind":"質問","question":"本日結論を出させていただき、態度については、不採択でお願いいたします。公園や広場の環境整備というところでは、確かに子どもたちののびのびと遊べる場所というのは一方では課題かなとも思いますが、しかし、そういった中では取り組みもされているということだったので、この請願項目についても願意に沿いがたいのではないかと思いますので、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"高橋委員","kind":"質問・要望","question":"請願項目の１番については、今の基準で整備しているわけですので、今後、その基準の中で十分配慮しながら保育を行っていっていただきたいというふうに思いますが、それ以上でというこの項目には沿いがたいです。２番のほうは、認可保育園の増設に関しては、さまざまな形態を持ちながら、今お話にあったような数を整備されています。ですから、今後もそういった形で整備をしていっていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/947507?Template=document&Id=4808#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":50915,"voices":170}},{"id":"h25-20131125-5","meetingId":"h25-cm11","date":"2013年11月25日","dateIso":"2013-11-25","committee":"総務委員会","time":"午前１０時００分～午前１１時５２分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を33件抜き出しています。","topics":[{"id":"topic-01","title":"債権の放棄","agenda":"債権の放棄","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"２番のところのこの方も平成２１年の９月に生活保護ということがあったように、今、ちょっと聞いたんですけど、この方が平成２１年ということで、今まで債権の放棄というのが、この間４年ぐらいあったと思うんですけど、なぜ今になったのかというあたりをちょっと教えていただきたいと思います。","respondent":"久保田会計管理者","answer":"その点、今回、条例がつくられたということによって、債権放棄できる根拠になったです。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ちょっと仕組みで教えていただきたいのが、第４号で生活困窮状態にあって、かつ資力の回復が困難ということですけれども、これは例えば、一時的な生活保護を受けるというそういう方もいらっしゃると思うんですけど、そういう方の場合は放棄ということにはならないで、ずっとこの方は生活保護から離脱するのはなかなか難しいだろうという、そういう判断のもとで放棄という仕組みになっているんでしょうか。","respondent":"久保田会計管理者","answer":"この間、ずっとそういう形でお願いはしているんだけれども、やはり生活状態にさほど変化はないということから、おそらく生活保護で、おそらくこのままの状態が続くだろうということも十分に判断されるということで、そういう判断をしております。","id":"exchange-002"},{"speaker":"須貝委員","kind":"質問","question":"さまざまな理由でこういう延滞してしまうということで、最後は返還できないという話なんですが、ちょっとわかる範囲で結構なんですが、この方たちは、やはりご病気等の理由で実際もう返還する力すら、気力すらなくなったのか。それとも、雇用と社会環境の影響でやはりこういう状況に、最後、生活保護という形になったんですが、それは大体どういうような主な理由でなったんでしょうか。","respondent":"久保田会計管理者","answer":"これといって、統一したようなそういうような状況ではない。個々人のいろいろな実情だというふうに思います。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問・要望","question":"これからおそらくこのようなケースも増えてくるのではないかと思うんですが、各担当者、大変だと思うんですが、相手のお気持ち等を配慮して対処していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"}]},{"id":"topic-02","title":"新地方公会計制度に基づく財務４表","agenda":"新地方公会計制度に基づく財務４表","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"改めて教えていただきたいのは、どうしてかというと、よく会計報告書が来ると月次報告が来ても、スタートが２,００４億円だっけ、全部、特別会計も入れると。２,００４億円か何かのところのお金の動きが出てきますよね。そうなったときに、じゃあ、企業で言うならば、完全に例えば子会社とかそういうのが別会社だから別会計になるけれども、内部的だったら部みたいな話になるじゃないですか。","respondent":"本城企画財政課長","answer":"一般の企業の取り扱いと必ずしもパラレルになっているところではないかもしれませんが、基本的な考え方としては、予算の組み方として全体を一覧して見せるということで、いわゆる統計予算比率ということで全体を見せる、１個のお財布として見せるのが基本ですが、その中で。","id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"質問","question":"私の理解が悪くてごめんなさい。だけど、本体の中の１つだよと。お金は本体からだってもう出して使っているんだから、色がないように見えて、その２,００４億円か何かのお金を使っているのは見えているわけだから、それは月次報告もいただいて、これぐらいお金が出てこうなんだなというのはわかるわけじゃないですか。もちろん繰入だって、どうというのはわからないじゃないですか、最後のそこまで、我々。","respondent":"本城企画財政課長","answer":"今、冒頭でも企業会計的な観点から会計を見せるという意味でのお話はさせていただきましたが、ただ、冒頭、私が申し上げた企業会計的な意味というのは、これはご案内のように、いわゆる現金主義ではなく、発生主義で示すとか、そういったあたり。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"とても難しくて、よくわからないんですけれども、この新地方公会計制度に基づく財務４表ということでの、こういう一覧表というか、これは概要ということなんですけれども、私もこれ、全然わからなかったので、いろいろちょっと見たときに、総務省で出したもののところに、財務情報のわかりやすい開示ということの目的のところに、それから、地方自治体における予算。","respondent":"本城企画財政課長","answer":"どこがわかりやすいかということについてですが、先ほど企業会計の関係でもちょっとご説明させていただいたところですが、例えば行政コスト計算書という1)のところがありますが、その中で減価償却費だとかというようなのが出てきていると思います。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この行政コスト計算書、1)のところで、いろいろと書かれていますけれども、これは概要版ということなので、１つ１つ、じゃあ人件費ではどこどこでどういうふうなところ、物件費ではこうで、社会保障ではこうこうこういうふうなところでというふうなことの細かいものというのが、ホームページの中で予算書みたいな、そういうふうな、これの中身が全部出されるという考え方でいいんでしょうか。それが１点と。","respondent":"本城企画財政課長、須藤委員長","answer":"詳細な資料の情報のご提供に関してですが、これについては、先ほどご説明させていただきましたが、１２月２１日に品川区の公会計レポートということで、詳細な原稿をつくっているところですが。毎年もう十何年やっていらっしゃるから、そのとおりの広報とかホームページということですよね。という意味で考えておけばいいだろうと思うので、鈴木委員、どうぞ。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう区民が生活している限り必要なものというところを純資産にして、負債と相殺してこれだけ引き継げますよと言っても、そこのところというのはどういう意味があるのかなという、区民がいる限りはずっと使い続けるというふうなことで純資産としてはあったとしても、それが負債と相殺して区民のために活用はできても、それを売却してお金にするというふうなことはできないというものを。","respondent":"本城企画財政課長","answer":"純資産の意味の関係で売却できないものも載せているという、そういう意味では確かに道路等が売却できるわけではありませんけれども、ただ、行政資源として区民のいろいろな意味の便益に供しているものがトータル資産としてどれぐらいあるかという。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"最後の別紙３のところの行政コスト計算書の社会保障給付費のところに再開発３０億円という、生活保護費というのは社会保障そのものだと思うんですけど、再開発の３０億円というのは、この社会保障給付費のところになぜ入っているのか。ちょっとそこを教えてください。","respondent":"本城企画財政課長","answer":"生活保護費は当然相手に対しての給付費用でして、再開発も再開発組合等に補助をして、区が直接を物を買うのではなくて補助をするという形のものも、いわゆる移転的経費という位置づけの中でこのグループの中に入れているというのが、この会計モデルの考え方なので。","id":"exchange-010"},{"speaker":"須貝委員","kind":"質問","question":"今の貸借対照表の中でお聞きしたいんですが、投資などということで基金積立金、有価証券、これは税金としてこれから投資するということでわかるんですが、出資金などということで入っておりますが、この出資金というのは、ある程度一定の期間、やはり回収ができないというそういうものが相当数あるんでしょうか。ちょっとそれは説明だけお願いします。ちょっと中身を教えてください。","respondent":"本城企画財政課長","answer":"この流動資産の中は、主に基金の関係で、上に投資などにある基金は２つに基金が分かれているんですが、いわゆる財調基金とか減債基金とか一定とっていますが、そこでの保有するものが流動資産の中の２６３億円の中に含まれておりまして、それが一番大きいものです。","id":"exchange-011"},{"speaker":"須貝委員","kind":"質問","question":"投資のほうにはほかの基金がさまざま載っているわけですが、それならば、今の財調の基金なんかも、使い方としては同じような、何か足りないとき、補足するときに出すはずですから、そちらになぜ載せないのかということと。道路を含めて学校等さまざまな施設整備等にお金をかけているんですが、これに対しての、その膨大な金額に対してのリスク回避ということは何かお考えがあるんでしょうか。","respondent":"本城企画財政課長","answer":"資産のリスク管理といいますか、資産として９,３９３億円ということで、これは今までずっと土地、財産ですね、建物を建てたり、道路をつくったり、もろもろしたもののトータルとしてこれだけあるということで。","id":"exchange-012"},{"speaker":"須貝委員","kind":"質問・要望","question":"あまり深くは入りませんが、相当の金額を、今、品川区でも相当の資産を保有しているわけですね。その中で、やはりそれなりの自助ということで、品川区自身もリスクを回避するということも私は考えてほしいなというふうに思いますので、それはちょっと意見だけ述べさせていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"浅野委員","kind":"質問・要望","question":"いろいろ今、皆さんから質問があったんですけれども、今回の資料の１ページ目のところで、目的と経過のところなんですけれども、今後も区の財政状況を、区民によりわかりやすく、より透明性を高めるため、工夫を重ねていくというふうにありまして、私もこれだけの表を見ますと、頭の中がごちゃごちゃになりまして、どこの部分を本当に見ていいのかというのがなかなか思いつかない部分がありますけれど。","respondent":"本城企画財政課長","answer":"よりわかりやすいですが、限られた紙面の中での公表となってまいりますので、言葉をわかりやすくしたり、少なくともそういう観点からの工夫はしながら、今回の１２月はそのような取り組みをしていきたいと考えているところです。","id":"exchange-014"},{"speaker":"浅野委員","kind":"質問","question":"ただ、一般の区民の方がご覧になって、そういう意味では見やすさというんでしょうか、例えばどのような費用が多く歳出の中にあるのか。そういうのもわかりやすくというのは、今後のまたさらなる挑戦かなというふうに考えておりますので、ぜひとも今後もそのような方法で取り組んでいっていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"石田（秀）委員","kind":"質問","question":"１つだけいいですか。先ほどのこれを、決算の審議のときに間に合わすか、間に合わさないかという、それを課題と本当に思っていらっしゃるのか。その位置づけを準じるもので区民向けと思うか。この考え方をちょっとはっきり聞いておかないと、ほかのことにも全部関連するからそれはどう思っていらっしゃいますか。","respondent":"本城企画財政課長","answer":"ただ、今、国が財務４表について、これから考え方をかなりいろいろ整理しているところで、その中で可能であれば、予算だとか、そういうことにも反映するような形の仕組みを考えるとか、いろいろちょっと検討している状況もあるようですので、そういうような状況も見ながら。","id":"exchange-016"},{"speaker":"石田（秀）委員","kind":"質問","question":"そこら辺はちょっと明確にしてほしいと思います。特に、資産なんていうのは一番わかりやすいし、流動的なのも、もうこれがこれぐらい見込んでいるんです、投資的経費と経常経費だって、出されるじゃないですか。これはそれのもうちょっと詳しいやつ、だけど本当はもっと詳しいのは予算書があり、決算書があり、監査の報告もありということなわけじゃないですか。変わってくるわけじゃないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"石田（秀）委員","kind":"意見","question":"何度も言うようだけど、これ、区民向けに出すものなのだと。我々は審査はさまざまな資料をいただいたり、いろいろあるわけで、そうしたら、今の資産の話も公共資産、例えば８,９８０億円あるよ。そういうものがだあっとあって、今度、変わるとなると、今みたいに幾らっておっしゃるけれども、そうすると、それは予算書なり何なりに載っているわけでしょう、本当、多分１個１個言えば。言っているのは。","respondent":"桑村企画部長","answer":"ここについては、一定の考え方を少し入れてつくっているものですので、それを厳密にいろいろ資料ということになりますと、なかなかその考え方がはっきりしない部分がありますので、そういう意味では少しこういう議論を重ねながら精査していくことが必要ですので。","id":"exchange-018"},{"speaker":"つる副委員長","kind":"質問","question":"大枠で結構なんですが、そのあたりをまず教えていただけますでしょうか。","respondent":"本城企画財政課長","answer":"今、手元に詳細な資料があるわけではないんですが、社会保障給付費が１つのメーンとなってきます民生費の費目の割合で見ても、この間、数年前に３０％台だったのが今４０％を超える等。","id":"exchange-019"},{"speaker":"つる副委員長","kind":"質問","question":"そうすると、その社会保障給付費の中で、いわゆる民生費のパーセンテージが上がってきて、全体として６５％という数字になっているんですけれども、そういった数字も含めて、囲いの中の現在による負担割合１０４.３％という数字なんですが、それは十数年前ですかね、だから、これを始めてこうやって数字を出すようになったときぐらいからの数字で見ると、少しずつ減ってきているのかなという。","respondent":"本城企画財政課長","answer":"今、ちょっと十数年前のは手元にないんですが、ただ、ここ数年間で基本的には去年との数値もほとんど変わっていない状況で、その間、基本的には将来の負担がない形で資産の形成が続いているという意味では、これが変わっているわけではないと理解しております。","id":"exchange-020"},{"speaker":"つる副委員長","kind":"質問","question":"そうすると、大きい、がくんと今、１０４.３％で例えば極端な話、次年度に４.３％減って、負担が生じるよということが急に発生するということはないと思うんですが、その辺の危機意識というか、マネジメントというか、この辺の感覚というのは常に持ち合わせながらの当然予算編成にはなると思うんですが、その辺の部分の考え方があれば教えてください。","respondent":"本城企画財政課長","answer":"そういう基本姿勢で今までもやってきたところで、これからもやっていかなければいけないと考えているところです。","id":"exchange-021"},{"speaker":"つる副委員長","kind":"質問・要望","question":"現状、その上で総務省の改訂モデルを入れてから５年、６年になると思うんですけれども、また改めてあえて聞くんですが、これまでの財務４表つくってきて、区民の方に対するわかりやすい公表というのが１つのメーンだと思うんですけれども、内部的な部分での活用ですとか、この辺をどのようにやってきたかというのがあれば、教えていただきたいと思います。","respondent":"本城企画財政課長","answer":"内部的な観点からは、対外的に示すとともに、この時期にこういう形で我々内部で一覧という形で今まで予算、決算ベースのフローだけでは見えなかったものも、個々の情報としては当然財務資料を持っているわけですが、一覧にすることによって。","id":"exchange-022"},{"speaker":"つる副委員長","kind":"質問・要望","question":"わかりました。いわゆる使える会計制度というんですかね、またそれを新しいモデルを今、まとめつつある流れがあるんですが、聞いているんですけれども、一応今、現段階で、品川区としてそういうモデル、具体の流れですとか押さえている部分があれば教えていただきたいというのが１つ。なので、そういったことも工夫していただきたい。これは要望なんですけど、前半の部分をお願いします。","respondent":"本城企画財政課長","answer":"区として国の動き等に対してどういうふうに対応しているかということであったかと思います。それにつきましては、当然中間まとめが先日出ましたので、そういうものは私どもの組織だけではなく、関係する組織も一緒に見ながら、フォローしているというところではあります。","id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"こういう財務４表というところでのまとめ方をしている自治体というのは、２３区ではどの自治体でもやっているものなのか。そういう観点で他の自治体とも比べることができるような状況になっているのかどうなのか。そこら辺の２３区の状況をちょっと教えてください。","respondent":"本城企画財政課長","answer":"基本的には２３区どこでも方式の違いは、私どもと同じ方式をとっているところが多数派ですけれども、方式はいろいろですが、どこの区も何らかの形で財務４表的なものをつくっているというのが現実です。","id":"exchange-024"}]},{"id":"topic-03","title":"品川区長期基本計画の中間見直し","agenda":"品川区長期基本計画の中間見直し","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それともう一つ、周知の方法なんですけれども、私は何度も説明会をぜひやってほしいということで求めてきましたけど、それはできないということでの答弁が続いてきたわけですけれども、このところで、全文冊子を各施設に配置したということなんですけれども、区民がこれを見たいということで来られたときには、その冊子そのものをその場で見るというだけではなくて、本当にたくさん、分厚いものですから。","respondent":"黒田長期計画担当課長","answer":"周知の方法としまして、来られた方には冊子の配布をというご質問ですが、今回もお電話で問い合わせをいたしまして、どうしても施設に行くことができないという方には個別に対応させていただいたところではありますが、これを全て希望される方に配布するとなりますと。","id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう点では、私は説明会を改めて数回にわたって、できれば地域センターごとぐらいにやっていただきたいということを改めて求めておきますけれども、それと同時に、素案について差し上げるとしたら、どれぐらい用意したらいいかわからないということですけれども、これは多分そういうふうなことをしたことがないからそういうふうな状況になるのではないかと思うんですけど、まず。","respondent":"黒田長期計画担当課長","answer":"説明会をというご質問ですが、今回、その後の質問でありますが、区としましては広報紙の特集号を発行したということで、広報紙のいわゆる別に長計の特集号をつくりまして、その中に返信用の封筒を印刷して、ご意見が気軽に応募できるというような形で体制をとっております。","id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その中では、この間の日曜日もテレビでも品川区の２９号線が取り上げられて放映がされておりましたけれども、そういう道路に対しての本当に切実な本当に切々と訴えるという、そういう感じのパブリックコメントの中身というのが書かれていたなと思うんですけど、これに対して私は意見への対応というふうなところでは。","respondent":"黒田長期計画担当課長","answer":"今後の改善策として説明会の実施、全文の配布ですが、長期計画の今回の見直しにあたりましては、策定時と同じ枠組みでいろいろなところに団体アンケートを行ったり、改訂委員会を設置して議論をしたということで、さまざまな意見を聴取しながらやってまいりまして。","id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これから区の施策を具体化していくというところなんですが、ここの区民の、説明会とかしない中で、これだけ意見が来たということは、これだけ本当に切実な思いを区民の皆さんが持っているということだなと改めて受けとめましたけれども、そういうところで、区としてもここに真摯に向き合って区政運営をしていただきたいと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"浅野委員","kind":"質問・要望","question":"数字を教えていただきたいんですけれども、わかればで結構です。ホームページに全文を掲載されたということで応募フォームもホームページに掲載されたということなんですけれども、それぞれのその期間中のアクセス数などわかれば、ひとつ参考にできればと考えていますので、教えていただければと思います。わかればで結構です。","respondent":"黒田長期計画担当課長","answer":"済みません、長計の応募フォームにどのぐらいアクセスがあったかという件数はちょっととっておりませんで、実際に送られた件数が３２件ですので、そちらのほうは承知していないところです。","id":"exchange-029"},{"speaker":"浅野委員","kind":"意見","question":"そういう数が出てくるのが少ないけれども、これだけの方が見ているというのは、ある意味では行政としても大きなデータになると思いますので、これはぜひともこのパブコメとかさまざま区が企画として区民の方にホームページを通じて何かお願いするときには、どのくらいのアクセス数がそのバックグラウンドとしてあるかというのは押さえていっていただいたほうが。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"石田（秀）委員","kind":"質問","question":"済みません、ちょっとだけ教えてください。売却に当たっての主な条件なんですが、旅館その他営業行為を目的とはできないということになると、店舗、事務所もできないとなると、これは別荘で買うという理解でいいのかなと思うんですが、これは例えば企業の保養所とかいうのはだめという判断なんでしょうか。それは保養所は別に営業行為じゃないからいいよというのか。そこら辺の条件を教えてください。","respondent":"平澤経理課長","answer":"先ほどご説明いたしましたとおり、主な用途といたしましては、あちらは箱根明神平サニーパークという大きな別荘地でございまして、別荘が一番大きなものになってあります。","id":"exchange-031"},{"speaker":"浅野委員","kind":"質問","question":"これがちょっと見えないので、何か引き続き売却はしたけれども、買ったところが違反をするようなことがあった場合に、どのような形になってしまうのかということも含めて教えていただければと思います。","respondent":"平澤経理課長","answer":"もう１点、これは契約書まだ案の段階なのですが、の中でも、本件契約締結後、維持管理に関する覚書を別荘管理会社と締結することという条件を、契約書の中にも入れるということで担保するです。","id":"exchange-032"},{"speaker":"浅野委員","kind":"質問","question":"間違っても品川区に降ってわいたような形で損害をこうむるというんでしょうかね、責を問われることがないように、十分配慮していただければと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/599487?Template=document&Id=1966#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":36660,"voices":90}},{"id":"h25-20131126-6","meetingId":"h25-cm11","date":"2013年11月26日","dateIso":"2013-11-26","committee":"区民委員会","time":"午前１０時００分～午前１１時４９分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を30件抜き出しています。","topics":[{"id":"topic-01","title":"の第１４回品川区中学生の主張大会","agenda":"の第１４回品川区中学生の主張大会","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"参考程度にですけど、昨年であればどんなテーマだったのか教えていただきたいと思います。それと、そうはいってもこれは地域活動課ということですけれども、これは教育委員会にならない理由というか、それとも青少年活動としてやってきた歴史的な背景があるのか、ちょっとその辺の関係だったり、あと今回１４回目ですけど、始まった動機やきっかけなどもご説明いただけたらと思います。","respondent":"久保田地域活動課長","answer":"本年も同様の内容のものが多いと思いますけども、やはり友人関係のこととか社会について考えていることとか、あとは地域と中学生のかかわりといったような発表をする予定です。","id":"exchange-001"},{"speaker":"中塚委員","kind":"意見","question":"やはり東日本大震災を経験したり、またそのボランティアにかかわったり、中学生自身もいろいろ考えることが多いご時世だと思います。ただ、品川で言えばこのいじめ克服にかかわっても友情だったり、連帯だったり、学級活動だったり、そういうところの一翼を子供たち自身が考え、見つめ直して主張をするということにつながっていればと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"私もこれ、第１回目から何回も見に行っています。ただ、議会側としてほとんど議員は来ていないというのが現状だと思う。やはりこれは議会としてもできる限り出て、中学生の主張を、すばらしく５分間原稿を読まないでしゃべっている子もいるので、そのぐらい中学生一生懸命やっている。その辺でこれからも行政側として教育委員会と提携して長くやっていっていただきたいと思う。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"吉田委員","kind":"質問・要望","question":"各中学校代表者ということですが、人選というのは学校でどのように行われているか、ご存じなら教えていただきたいのですけれども。","respondent":"久保田地域活動課長","answer":"基本的にはそういった選考を経て選んでくださいということをお願いはしていますが、細かいやり方まではちょっと私どものほうでは把握してございません。","id":"exchange-004"},{"speaker":"吉田委員","kind":"質問・要望","question":"ちょっと聞いたところによりますと、各学校で発表が行われ、その中で生徒たちが投票によって決まる学校が何校かある。これは要望ですけど、お願いしていきたいと。ここまでに上がってくるまでに、子どもたちの気持ちも含めて指導していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"}]},{"id":"topic-02","title":"の若者就業体験事業","agenda":"の若者就業体験事業","exchanges":[{"speaker":"石田（し）委員","kind":"質問・要望","question":"対象者のことですが、３１名いて、企業で実習中２７名というふうになっているではないですか。当初は３６名いたわけですよね。それで５名の方が何らかの理由で辞めてしまったと。３１名ということですけど、その方たちにもこの就業実習中だったり基礎研修の期間、その間にどういうバックアップ体制をとられていたのか教えてください。","respondent":"山崎ものづくり・経営支援課長","answer":"実際、７月１５日以降、区内企業に就業実習に行ってもらっていまして、そのうち内定をいただいた方が２４名という先ほどの説明ですけれども、一旦行って、１社で現在まで至って内定をもらえたパターンの方もいますし、また、Ａ社というところに行って。","id":"exchange-006"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"それと、これは要望ですが、やはり最近よく言われるのが、就職をされてもすぐに何ヶ月かたったら離職をしてしまうという方たちが多いという今の社会傾向がどうしても見られる中で、ぜひその点は区としても内定をされた方たち、実際に就職をされた後も可能な限りそういった離職しないような支援もしていただきたいと思いますので、これは要望ですが、よろしくお願います。２点お願いします。","respondent":"山崎ものづくり・経営支援課長","answer":"現在実習中の方が２７名。それで、そのうち内定者が２４名です。それと、３１名と実習中の相差の部分がありますよね。こちらの４名が今大井町のほうでこの事業を行う事務室がありまして、そちらのほうでいわゆる支援を受けている方というような形です。","id":"exchange-007"},{"speaker":"石田（し）委員","kind":"意見","question":"実習の人で内定してない人の人数と、それの差の関係についてはどうなっていますか。","respondent":"山崎ものづくり・経営支援課長","answer":"恐れ入ります。それで、２７名は現場に、企業に行かれているのですけど、そのうち内定をいただいた方が２４名。企業に行っているのですけれども、まだ内定のご返事をいただいていない方が３名いらっしゃいます。その方々、２７名は企業に実際は行っています。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問","question":"伺いたいのは、今回体験を通じて就労に促していこうと、またそのいわば体験というか研修だったり実習中は区が委託事業者を通じて給料を支払うと。つまり、本来仕事の紹介はハローワークでしたよね。つまり、この事業をステップワン、ステップスリーという、要するに少しずつ積み上げていくというのは当初予算で説明がありましたけれども、今後の方向も含めてどういうふうにお考えなのか伺いたいと思います。","respondent":"山崎ものづくり・経営支援課長","answer":"ただ、ご希望によっては、就業という観点で申し込み、あるいは区としてのコミュニケーションができた方ですので、そうした方については本事業とはまた違いますけれども、企業側の支援に立った合同就職説明会とか。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"もう一つは、区内の会社、３６５社が協力していただいて、求人の規模も１８０名規模だと随分確保できたと考えていますけれども、何ていうのでしょうか、どういうものというか、ノウハウとか、正直すごいと思ったところですけども。これは単年度で終わってしまうのか、それとも今後の取り組み、方向についてどういうふうに積み重ねていこうと思っていらっしゃるのか。今後の方向を伺いたいと思います。","respondent":"山崎ものづくり・経営支援課長","answer":"今後の取り組みにつきましては、事業終盤に来ておりますけれども、まだまだ本事業の最終的な成果でありますとか、先ほど企業のほうのご意見なども確認をしながら。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後にもう一点だけ。具体的には、しっかり法律で定められている協議会を設置して学校だったり、ＮＰＯだったり、いろいろな団体と情報共有しながら支援策を組んでいくと、こういうスキームが必要ではないのかと思いますけれども、今後の方向についてその点についてはどのようにお考えなのか伺いたいと思います。","respondent":"山崎ものづくり・経営支援課長","answer":"それからさきほど雇用に関しての協議会のお話もありましたけれども、その辺も検討段階では視野に入れながら総合的な支援に努めていくというようなことで今検討を進めさせていただいている途中です。","id":"exchange-011"},{"speaker":"山元委員","kind":"質問・要望","question":"今回、８３名中６４名が説明会に来て３６名ということでしたけれども、ある程度定数というか、決められているのかということと、それから基礎研修をいろいろなさるということですけれども、実際のお仕事をしている方とかいろいろありますけれども、１カ月ぐらい基本で、何かどういうふうにやるのかというのも、それが役に立つための研修だろうと思いますけれども。","respondent":"山崎ものづくり・経営支援課長","answer":"定数です。先ほど事業の予算フレームはご説明をさせていただいたとおりでございまして、当初４月に全戸配布をさせていただいたチラシのほうにも参加募集数として３５名程度ということで制度の設計をしています。","id":"exchange-012"},{"speaker":"山元委員","kind":"質問・要望","question":"落ちた人にしてはショックだろうと思いますけれども。何で落ちたって変ですけれども、いろいろさまざま理由があると思いますけれども、どういう理由で今回不採用というか、なったのか、その辺をちょっと教えていただきたい。","respondent":"山崎ものづくり・経営支援課長","answer":"そうではない方につきましては、先ほど本事業につきましては研修をしてスキルアップをしていただいて企業に行っていただくということですので、そういう機会に恵まれないスキルアップの支援という、考えていたメニュー以外のところに少し問題というか。","id":"exchange-013"},{"speaker":"山元委員","kind":"意見","question":"では最後に。そういう後々のフォロー、バックアップ、いろいろ考えていただいて力強いと思いましたけれども、一応３５名程度ということで、次回はもう少し増やそうかという、そんなお考えはありますか。","respondent":"山崎ものづくり・経営支援課長","answer":"本事業だけの人数としましては、本事業として抱えるべき人数と、それからほかの新規というか周辺のことも考えさせていただいて、事業定員というかフレームのほうは今後予算編成の中で検討させていただきたいというふうには思っております。","id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"確認","question":"当然そんなことはないということを前提にいきたいのですけど、今後、就職なさった方を企業との間でどのぐらいの追跡というか、チェック、検証していくのかという、そこら辺を確認しておきたいのと、なるべくこれからも続けられるような形に指導していってもらうことをお願いするということだと思いますけど、今後の検証状況だけちょっと教えてください。","respondent":"山崎ものづくり・経営支援課長","answer":"ただ、本事業を通じたこの事業の同期といいますか、仲間づくりといいますか、その辺が今まで中小企業に就職したときに、先輩なり同僚の方がいていろいろ育てられるというところがなくて、ひとり孤立してしまうようなことで離職してしまうことも多いというふうに聞いていますので。","id":"exchange-015"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"一般財源の持ち出しをやっていく形になっていくと、月１７万円という金額が多いのか、区の中で多いのか少ないのか、個人としてはやっていける数字かと思いますけど、そこら辺は非常に不安を感じるところがあるので、決してこの事業に反対するわけではないし、しっかり就職していただくことが望ましいとは思っていますが、そこだけどうしても気になるので、あえて要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"}]},{"id":"topic-03","title":"の２、所管事務調査","agenda":"の２、所管事務調査","exchanges":[{"speaker":"石田（し）委員","kind":"質問・要望","question":"ちょっと確認ですが、２枚目の予約利用申込で、区内団体と区外団体という分け方をされているではないですか。どういう人がいないと区外団体になるのかというのを少し教えていただきたいのです。これは全部が全部常に活動しているわけではないと思うので、わかる範囲で構いませんので、このうち男性が何％程度、主に活動しているよというのがわかれば教えていただきたいと思います。よろしくお願いします。","respondent":"安藤文化スポーツ振興課長兼オリンピック・パラリンピック推進担当課長","answer":"そういうところで、まず非常に申し込みが多いものですから、そこら辺を徹底的にやっているです。それから、学校体育館のスポ・レクの６１２団体。これは、スポ・レクのほうから私どものほうで調査をした結果、ほぼ６１２団体で全てが活動しています。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"これは要望だけにしておきたいと思います。ほかのいろいろな、大小それぞれありますので、固定式ではない移動式の磁気ループも今できておりますので、それをぜひ導入していただきたいと思いますけれども、ここを伺いたいと思います。その点磁気ループだと電波といいますかラジオ電波といいますか、耳に直接鳴りますので、そういうのをぜひ検討していただきたいと思いますけれども、いかがでしょうか。","respondent":"安藤文化スポーツ振興課長兼オリンピック・パラリンピック推進担当課長","answer":"それで、荏原文化センターの改築にあわせてですけれども、今後検討させていただきまして、できる限りはしていきたいと思っていますけれども、検討させていただきたいと思っています。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひそういう支援を強めていただきたいのと、あと移動式のやつも、そこだけもう一度ご答弁後でいただきたいと思います。その点について区はどんなふうにお考えなのか伺いたいと思います。ちょっと僕、ホッケーには疎いので、要するに、今後のスポーツの発展に寄与できるようなことを区の立場としてもやはり求めていくという、それについてはどういうスタンスなのか伺いたいと思います。","respondent":"安藤文化スポーツ振興課長兼オリンピック・パラリンピック推進担当課長","answer":"荏原文化センターの磁気ループについては、入れる入れないを含めて検討します。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"野球場、少年野球場については青空野球場の流れから見ると数は減っておりますので、代替地を求めるのは当然でしょうが、ホッケー場にかかわる代替地を求めるのはぜひ進めていただきたいと思いますけれども、青空野球場と比べる数が減っておりますので、ぜひ増やすのも検討していただけたらと、これは要望しておるところです。","respondent":"安藤文化スポーツ振興課長兼オリンピック・パラリンピック推進担当課長","answer":"新人の育成ですが、区として明確に新人を育成するとか発掘するとか、そういうことを計画では述べていません。これは、まず文化振興事業団が文化の振興をしていく上で平成２１年度からこういう事業をやっていまして、そしてあわせて区が平成２２年度から芸術祭を行いました。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問","question":"位置づけがないのはなぜなのかと聞くのか、位置づけないのかと聞くのか、ぜひそこについて区の考えを伺いたいと思います。どうしても後景に追いやられる文化や芸術やスポーツ、しっかり位置づけて多様な区民の活動や発表や自由な活動を保証していくということをまず位置づけることが大事だと思いますけれども、改めてその点を伺いたいと思います。","respondent":"安藤文化スポーツ振興課長兼オリンピック・パラリンピック推進担当課長","answer":"私、先ほどそういう区の計画の中で、明確な位置として位置づけているかというようなご質問でしたので、そこにはそういうような形では書いてございませんが、その施策の体系の中で先ほど申しましたように多様な活動を支援するだとか、それから生涯・スポーツなど。","id":"exchange-021"},{"speaker":"山元委員","kind":"質問・要望","question":"一つお伺いしたいのは、各スタジオ等には鏡があり、それからバレエ用のバーがあると書いてあります。こみゅにてぃぷらざも鏡があり、実はここは鏡のところに２つバーがあるのですよね。それともまた何かお考えがあって小さい子用とか何かつけられたのか、そういう当初つけるに当たって何かあったのか、もしあれば教えていただきたいと思いますけども。","respondent":"安藤文化スポーツ振興課長兼オリンピック・パラリンピック推進担当課長","answer":"しかし、今バーの高さの位置についてはどういうような背景があってここにつけたかということは今私は承知していませんので、利用の実態を含めて今後検討させていただきたいというふうには思います。","id":"exchange-022"},{"speaker":"山元委員","kind":"質問","question":"それからすみません、一遍にでよかったのですが、あと、南大井文化センター、この陶芸用の電気炉があるということで、これは実は現場の方から、やはりやっている方から、実は夏場はいいのですけど、冬はやりながら泥というか、お水ではなかなか落ちなくて、それは水道というか、お湯が出るようなものがあると非常に使い勝手がいいのだけどみたいな、そんなご相談があったのですが。","respondent":"安藤文化スポーツ振興課長兼オリンピック・パラリンピック推進担当課長","answer":"」とそういうふうな答えで、２団体の方に直接私が聞いたところ、そういうようなこともあって、ご意見を伺ってまず技術的に可能かどうかということを検証させてもらいたいと思います。","id":"exchange-023"},{"speaker":"山元委員","kind":"質問・要望","question":"ぜひお考えいただきたいと思います。もう一点すみません、ごめんなさい。その辺、そういう競技をなさる方たちも汗を流しながらやっておりますけれども、実際そこの戸越体育館にクーラーをつけるというのは、大きな扇風機をいただいているのですけども、現実的にはクーラー設置というのはどうですかね。","respondent":"安藤文化スポーツ振興課長兼オリンピック・パラリンピック推進担当課長","answer":"戸越体育館でこれまで、今の体育館は昭和６２年にできまして、そういうようなご意見もありますけれども、どうでしょうか、今のところ庁内として、全体的な問題として検討というか研究を進めさせていただきたいというふうに思います。","id":"exchange-024"},{"speaker":"山元委員","kind":"質問・要望","question":"これ、呼ぶというか、それなりのいろいろ予算もあるのでしょうけれども、この呼ぶ基準というか、何か今世間的にこういう人たちとか、決めるに当たってどんなふうな基準、来年もいろいろな人、アーティストを呼ぶと思いますけれども、それをやって人もつながる、どんどん入ってくるということもあるので、基準というか、何かそういうものがあるのであれば教えていただきたいと思います。","respondent":"安藤文化スポーツ振興課長兼オリンピック・パラリンピック推進担当課長","answer":"今後は品川区にゆかりのある方を中心にというふうに聞いてあります。","id":"exchange-025"},{"speaker":"吉田委員","kind":"質問","question":"文化施設とスポーツ施設ですけれども、夏に省エネの照明とか利用時間等のそういう話が前来たと思いますけれども、そういう関連のある考え方を教えてほしいのですけれども。省エネに関してどのような工夫とかいうのを、時間帯等考えていらっしゃるのか。どこがどうというのではなくて、全体的なお話を知りたいと思います。","respondent":"安藤文化スポーツ振興課長兼オリンピック・パラリンピック推進担当課長","answer":"文化スポーツ施設ですけれども、これも３・１１以降、区の取り組みの中でやはり必要以上のものはどんどんどんどん節電をしてまいりました。そんな中で、ここのところ、夏になると、独自に例えばいろいろな蛍光灯を消したりだとかそういうものもやってあります。","id":"exchange-026"},{"speaker":"吉田委員","kind":"質問・要望","question":"時間等の変更等はあったのかを最後に１点。時間等ですよね。夜の時間等の変更があったのかとかそういうのがありましたら教えていただきたいのですけれども、お願いします。","respondent":"安藤文化スポーツ振興課長兼オリンピック・パラリンピック推進担当課長","answer":"今のは時間等の変更というのは、利用時間の変更ということですね。平成２３年度以降、区の計画に基づき、先ほど言ったパーセンテージも区の基本方針をもとにやってきてあります。","id":"exchange-027"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"その点まず区はどのように考えているのか教えていただきたいのと、ここに育成という部分が出ていますが、僕はそういった事業にそういう若手アーティストたちがボランティアでも参加をする、もちろん出演も含めてですけれども、そういった事業を組み立てていくところから参加をしていくことに僕は非常に育成という部分では効果があるのかと思うのですが、その点も合わせて区の考えを教えてください。","respondent":"安藤文化スポーツ振興課長兼オリンピック・パラリンピック推進担当課長","answer":"今後は来年５周年を迎えるわけですけれども、参考にして進めていきたいと思います。","id":"exchange-028"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"それと、今さまざま自治体でゆるキャラだったりご当地アイドルみたいな、僕はそれはいいとも悪いとも言わないけど、そうやって手探りで頑張っている自治体もあるわけですよ、今空前のアイドルブームなんて言われている中で、僕はそういったブームとかというのにも、その短い期間かもしれないけど、そういうことに乗っかってわあっと盛り上がるというのもやり方の一つとしてはあるかと思うので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"中塚委員","kind":"意見","question":"いや、資料として出るかと思って。タイに行ってどういう状況になったのか、区のブースを持ってやるということだったので、そこが報告に入ればと思いますので調整していただければと思います。","respondent":"渡辺委員長","answer":"わかりました。ほかにいかがでしょうか。よろしいでしょうか。では、正副で調整していきたいと思います。ほかに何かありますでしょうか。なければ、所管事務調査を終了いたします。","id":"exchange-030"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/972690?Template=document&Id=2684#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":34449,"voices":82}},{"id":"h25-20131126-7","meetingId":"h25-cm11","date":"2013年11月26日","dateIso":"2013-11-26","committee":"厚生委員会","time":"午前１０時００分～午後２時４０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件抜き出しています。","topics":[{"id":"topic-01","title":"はじめに、(1)の上大崎三丁目高齢者福祉等施設の運営事業者の選定","agenda":"はじめに、(1)の上大崎三丁目高齢者福祉等施設の運営事業者の選定","exchanges":[{"speaker":"井上委員","kind":"質問","question":"そもそもなんですけれども、一番最初に選定事業者が指定管理者候補となる予定であると。やりようがこれしかないかもしれないけれども、そこのところは、もう事業者も選定して議会の議決ですといったときに、じゃ、指定管理はこの人たちは認められませんとか、いいとか、結果的に流すしかなくなるんだろうなという、この仕組みについて、どういうふうにお考えなんでしょうか。","respondent":"永尾高齢者福祉課長","answer":"そういう現実的な手続を考えますと、現在のやり方が一番、ご利用者にとっても非常にいい内容になるのかなと考えているところです。そういう方式に対してその都度、議会に対してはご報告、ご説明、ご議論を求めて、委員のご意見を参考にしながら設計に取りかかっているです。","id":"exchange-001"},{"speaker":"井上委員","kind":"質問","question":"実質的にはこうせざるを得ないという、その理由はわかります。だから多分、現場の方よりも区としてどうなんでしょうかというところをお答えいただくほうがいいのかなと思います。","respondent":"永尾高齢者福祉課長","answer":"ですので、福祉施設に関しましては、現在区が実施しているこの方式をとるのが一番効率的、効果的なものであると考えておりますので、この方法をこれからも続けていきたいと考えております。","id":"exchange-002"},{"speaker":"井上委員","kind":"質問","question":"おっしゃることはわかるので、これは部長なんだと思うんですけれども、制度として、議会との関係も含めて、ありきでスタートしているところの議決を得るその仕組みについて、区として課題を持っていませんかということを伺いたい。重々、課長の言うことはわかります。そうせざるを得ないこともわかります。そこに、こうせざるを得ないことについての課題を、区は持たないんですかということ。","respondent":"早津健康福祉事業部長","answer":"非常に不都合な事態が起これば、更新時期を待たずにだってかえなくちゃいけないでしょうし、５年たったから改めて点検してかえられるかといったら、サービスの性質上、極めて難しいと言えるかと思います。","id":"exchange-003"},{"speaker":"井上委員","kind":"質問","question":"わかりました。今回のここの施設も、設置は品川区で、工事も品川区なんですが、その辺でどのぐらいの、以前に土地の購入は書いてありましたけれども、事業経費とか建設経費がどのぐらいになっているのかということと、あと、ちょっと図面で幾つかお伺いしたいので、まずはそこのところをお願いします。","respondent":"永尾高齢者福祉課長","answer":"まだ区で設計しているわけではないので、提案してきた事業者の工事費をご説明します。本体工事につきましては２７億９,８７４万７,０００円で、擁壁工事が８,３５４万７,０００円ということで提示してきております。","id":"exchange-004"},{"speaker":"井上委員","kind":"質問","question":"すいません、前に擁壁工事、２億円ぐらいかかるという答弁があったんですが、それが８,０００万円というのはどういうことですか。","respondent":"永尾高齢者福祉課長","answer":"前にご説明したときは、区の内部での推定でこのぐらいはかかるんじゃないかということをご答弁申し上げております。","id":"exchange-005"},{"speaker":"渡部委員","kind":"質問","question":"先ほど井上委員の質問に対しての回答を聞いていまして、今回、説明を課長にいただいて、指定管理者候補者になるわけですよね。その辺は、どこまで話し合われてきているのか。だって、ここでそういう約束で、指定管理者候補者だからというので、次、平成２９年ですか、できたときに、そこの金額落差が相当あった場合、これは税金を使っていくわけですから、なかなか理解はできなくなると思うんですけれども。","respondent":"永尾高齢者福祉課長","answer":"ただ、この計算のもとになっている部分というのが、本体工事、擁壁工事等、現在の試算の中での金額がもとになっているということで、相手方が提示している金額がそのままになるかというところまでは、区としては把握できないなというところがあります。","id":"exchange-006"},{"speaker":"渡部委員","kind":"質問","question":"税で運営していくわけですから、その辺の整合性も当然、この５者をヒアリングされた中で、ここまでこういうのをやるからそこがいいんだ。そうなると、最後の残りが１者みたいな聞こえ方をするんですけれども、これだけのことをやるわけですから、当然その５者に比較して、ここがよかったんですというものが何も伝わってきていないんですね。名古屋、愛知しか、横浜で１件あるようなところですから。","respondent":"永尾高齢者福祉課長","answer":"先ほどは落ちた理由を幾つか述べさせていただきましたけれども、ほかの４社会福祉法人につきましても、工夫されているところは幾つかございまして、例えば屋外に防災広場を確保している……。","id":"exchange-007"},{"speaker":"渡部委員","kind":"質問・要望","question":"今聞いてみないと、地域の方が使えるんだとわからないじゃないですか。ぜひ委員長、機会があれば、この横浜の事業者のパンフレットもなかなかいいものができているなと思いますから、１回どういうところなんだろうというのは見てみたいような気がいたします。やはり、税の負担が必要以上のものにならないように、それはしっかりとこれからも研究を続けていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今の質問の関連です。クリニックが併設されるのは非常に魅力ということだったんですけれども、クリニックを併設される場所はどちらになられるのか。そのお医者さんはどこから連れてこられるのか。そこら辺も多分、内々のいろいろな話があると思うんですけれども、その辺を教えていただきたいのと、どこにクリニックをつくるのか。この中に。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"あくつ委員","kind":"質問","question":"書いてある？どこから連れてこられるのかというところをお伺いしたいのと、あと、今回、伊藤喜三郎建築研究所というところと区と、一体となって設計されるということでしたけれども、幾つか非常に実績のあるところだということなんですが、今までにここと愛生福祉会が一緒になってつくったところがあるのかどうか。それを実際に区の方が見に行かれているのかどうかというところをお聞きしたいと思います。","respondent":"永尾高齢者福祉課長","answer":"愛生福祉会につきましては、医療のグループもございまして、パンフレットの一番下に医療法人愛生会グループというのがあります。病院、クリニックもこの愛生会グループの中で運営しておりますので、こちらと連携をとりながら、医師等の配置をするということになっております。","id":"exchange-010"},{"speaker":"あくつ委員","kind":"確認","question":"ありがとうございました。実際に愛生福祉会、コラボレーションを既にしているかどうかはまだ未確認ということでしたけれども、愛生福祉会のところは確認されたということですが、これは実際に行かれて見られたということでしょうか。","respondent":"永尾高齢者福祉課長","answer":"現地については、まだ区としては見には行っていないですけれども、今後協議をする中で、見学もしていきたいと考えております。","id":"exchange-011"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ぜひ確認をしていただきたいと思います。内容なんですけれども、ちょっと確認なんですが、選定理由の（２）に、上大崎地区ならびに品川区の地域特性について的確に把握研究しということで、どのように理解されているのかということ。多分、細かいいろいろな提示があると思うんですけれども、大体概要で結構なんですが、どのようにこの法人が捉えているのか、それを教えていただきたいと思います。","respondent":"永尾高齢者福祉課長","answer":"品川区の介護保険事業計画をよくご覧になっているような、プレゼンテーションのときもそういうお話が酌み取れたということと、地域介護の中でもほっと・サロンのことだとか、その他、区がやっている事業について具体的な説明をしておりまして。","id":"exchange-012"},{"speaker":"あくつ委員","kind":"提案","question":"今、品川区としてのいろいろなことは勉強されているということで、ちょっと重箱の隅みたいで申しわけないんですけれども、上大崎地区というところは目黒区との境で、ちょっと特別な地域というか、私の中ではそういうイメージがあるんですけれども、その辺はどのように理解され提案されていたのかというのをお聞きしたかったんですが。","respondent":"永尾高齢者福祉課長","answer":"それと、清閑な住宅地であることから、建設の設計に当たっても騒音だとか排気とかというものに十分注意を払っているというところがございました。","id":"exchange-013"},{"speaker":"たけうち委員","kind":"提案","question":"それから今回の設計の、さっき２次審査ですかね、設計が４５点とかと言っていましたけれども、１次からもう設計も含めて提案してくださいよという公募内容だったのかどうか。それから、設計といっても、今いただいている図面がありますけれども、こういう図面を出してくださいということだったのか、あらあらの概要なのか、どの辺までの設計の点数、評価をされたのかというのを教えていただきたいと思います。","respondent":"永尾高齢者福祉課長","answer":"設計についての審査ですけれども、１次審査でも設計を審査しております。これは図面上での審査です。２次審査におきましては、実際に１次審査で読み取れなかった部分をこちらで質疑しながら確認した上で、審査したです。","id":"exchange-014"},{"speaker":"たけうち委員","kind":"質問・要望","question":"わかりました。それの金額も含めてやりとりされたときに、だとすると、先ほど、区でもある程度もう一回確認しないと、その金額どおりいくかどうかわからないというお話があったんですけれども、金額の面と図面で、そこも含めて判断されたのであれば、本当はもっと事前にそれは確認した上でやらないといけないんじゃないかなという疑問があるんですけれども、そこはどうなんでしょうか。","respondent":"永尾高齢者福祉課長","answer":"説明会には品川区の法人も多く見に来たんですけれども、実際に提案する段階になって、出てこなかったというところが現状です。理由としては、現地の場所の地形の問題等がネックになっているんじゃないかなと感じているところです。","id":"exchange-015"},{"speaker":"鈴木（博）委員","kind":"質問","question":"先ほど選定理由で、一番の理由はクリニックを併設されているということで、採用された事業者も多分、地元の医療状況がよくわかっているというご答弁だったんですけれども、これを見てみると、名古屋の医療グループから医師を引っ張ってきて、どうもそれで派遣で診療するみたいな体制のようなんですが、例えば地元の品川区の医師会と協議したとか、あらかじめ申し入れをしたとか。","respondent":"永尾高齢者福祉課長","answer":"提案の中では、地元の医師会とは、こういうものの推薦が決定した後にご相談に行くという話は、事業者からも説明を受けております。その中で、医師会にも加入していきたいという意見も表明されているところです。","id":"exchange-016"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"ショートステイのところで、２０床が向こうからプラスされたというところで、ショートステイで定員３８名って、結構大きいかなと思うんですけれども、２０名をプラスされた理由があれば教えてください。","respondent":"永尾高齢者福祉課長","answer":"これからの高齢者福祉サービスは、在宅を中心とする方向があります。この社会福祉法人も、その社会的な方向性をにらんだ上で、ショートステイが一番ニーズに合っているんじゃないかということで増床したと聞いております。","id":"exchange-017"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"一つひとつ個室の面積で、今日いただいた資料の中では、有効面積なんでしょうけれども、各１戸で１１.０m2ということなんですが、プロポーザルのときの実施要項には、入所者平均１人当たりの延床面積は４０m2以上としてくださいということが設計条件に書かれているんですけれども、４０m2、結構広いなと思ったんですが、見たときにはあまり取られてないのかなと思ったんですが、４０m2。","respondent":"永尾高齢者福祉課長","answer":"やはり個室に閉じこもるのではなくて、皆さんとユニットの中で家族的な生活をするということで、必要な面積だと考えているところです。","id":"exchange-018"},{"speaker":"井上委員","kind":"提案","question":"品川区は認証された方に介護保険の中で住宅補助を、これは出さないというような提案の中のものなのか、そこのプロポーザルは全て合っていますよということなのか、ちょっと変わったところがあるのか、そこを確認させていただきたいことと、この図面ですけれども、これは提案の図面であって、ここに区が、こういうものはここに置いてくれというような協議の中で、そういうことができるものなのか。","respondent":"永尾高齢者福祉課長","answer":"法人はその２分の１の、さらに２分の１を支出するという制度になっておりますので、こちらは提案と公募の条件とは変わりはございません。これからの図面の変更につきましては、今、まだ本当に白紙の段階ではあります。","id":"exchange-019"},{"speaker":"井上委員","kind":"提案","question":"品川区内の方たちが、ここで多分就労されるのであれば、そういった託児のところで企業内保育という形でここに設けていくとか、いろいろと検討できると思うんですが、提案としては今その２点なんですが、そういったところはいつ私たちは提案できるのか、どういうふうにそういう協議の場があるのか、その辺はどのようなところにあるんでしょうか。そこを教えてください。","respondent":"永尾高齢者福祉課長","answer":"ただ、就労の訓練、また託児所等のご要望がございましたけれども、まず第一段階としては、この地元の地域の皆様のご理解をいただいた上で進めていかないと、これから運営していくに当たって長くおつき合いするわけですので、十分にそこを配慮する必要がありますので。","id":"exchange-020"}]},{"id":"topic-02","title":"のヘルプカードの配布","agenda":"のヘルプカードの配布","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"幾つかお伺いさせていただきたいと思います。先ほど個人情報に配慮するというお話もありましたけれども、そういったところなのかどうか、またそれはどなたのご意見なのか、先ほど障害者団体等の意見をお聞きになったということがあったんですけれども、また公募でもあったということで、まずそこについて教えていただけますでしょうか。","respondent":"中山障害者福祉課長","answer":"外に身につけてわかるようにしてもらわないと支援ができないんですが、一方で落としたとき、あるいは不用意に心ない人が見たときに、それが逆に危険につながらないようにというご意見がありました。","id":"exchange-021"},{"speaker":"あくつ委員","kind":"意見","question":"ということが一つ。それはどういうふうに判断されるのかということが一つと、他区によってはこれを書いていないところもあると。わざわざ入れていただいたと思うんですけれども、そこのご判断のお話と、これはしようがないことだと思うんですが、土日は障害者福祉課はどなたもいらっしゃいませんよね。そのときはどういう対応をされるのか。この二つをお聞かせください。","respondent":"中山障害者福祉課長","answer":"土日につきましては、こちらへご連絡いただいても対応できるところではないんですが、この件につきましては宿直にも話をいたしまして、こういった拾得物があったときに、後々確実に区役所に届くような連絡体制はとりたいと思っているところです。","id":"exchange-022"},{"speaker":"あくつ委員","kind":"質問・要望","question":"先ほどヘルプカード本体はテレホンカードと同じような材質ということがありましたけれども、サブカードの材質、これは常に持ち歩くということで、ぼろぼろになってしまうことも考えられるので、そこら辺を教えていただきたいということと、先ほどの配布の対象者なんですけれども、徘回等で必要な方、高齢障害者という表記がしてありますが、これは希望すればいただけるということなのかどうか。","respondent":"中山障害者福祉課長","answer":"ですので、今後高齢者福祉課とも連携しつつ、またほかにどういった対象の方がいらっしゃるかというのもあるかと思うんですが、庁内でもこちらのヘルプカードをつくった後には全庁的に流しますので、その中でお声があれば。","id":"exchange-023"},{"speaker":"井上委員","kind":"質問","question":"ああいう形でヘルプカードを、個別にこういうふうにいくのではなくて、商店街って、商店街の人たちに通知するということだと思うので、少しお金がかかっても掲示板なんかに周知するような、目に見てあれのことだねということが区民の方に伝わる方法って必要だと思うので、そういった検討も必要ではないかと思いますが、いかがでしょうか。","respondent":"中山障害者福祉課長","answer":"ですので、一律郵送ではなく、窓口配布という手段をとらせていただいているところですので、この２万枚の中で対応はできるのかなと考えています。ただ、それでも足りないということであれば、そこは今後の課題ということで、こちらも対応していきたいと思います。","id":"exchange-024"},{"speaker":"井上委員","kind":"質問","question":"それからあと一点、視覚障害者の方たちにどういう配慮をして、これを渡されようとしているんでしょうか。","respondent":"中山障害者福祉課長","answer":"ただ、そのときに必要な支援ということで、こちらの障害者福祉課の窓口に来ていただければ、ご説明しながら必要な支援について職員が代筆するということは可能ですので、そういった周知もあわせてしていきたいと思っているところです。","id":"exchange-025"},{"speaker":"井上委員","kind":"意見","question":"多分、ヘルプカードのほうは切り込みとか難しいだろうなと思うんですけれども、サブカードのほうだったら切り込みを入れるとか、何かそういう配慮、点字で品川区マークがボンとでこぼこするとか、ああいうことがないと、何の紙だか本人がわからないということでは、何を提示していいか、スイカなんかを出して一生懸命やってしまうとか、そういったところの配慮、切り込みなんかは絶対に必要だと思いますが。","respondent":"中山障害者福祉課長","answer":"大事なのは、これが届いたときに、どういった使い方をするのかということが理解されないと、確実に使っていただけるところにはなりませんので、視覚障害の方の団体にも相談しながら、どういった方法でこちらを配布して周知していくのがいいのかということは。","id":"exchange-026"},{"speaker":"たけうち委員","kind":"質問","question":"周知のところで、今、東京都の都営地下鉄とかでヘルプのストラップですかね、かばんにつけたりする。本当はそういうのがついていると、カードをいつもぶら下げているわけじゃないでしょうから、それもあわせて、もし周知できるならしてあげたほうがいかがなものかと。お考えだけ。","respondent":"中山障害者福祉課長","answer":"ただ、この５０部について、ほかに駅に行けばもらえるということでもありますので、あわせて都でもこういうものを作成していますよということは、通知の中に入れさせていただこうかと思います。","id":"exchange-027"},{"speaker":"井上委員","kind":"質問","question":"今回、厚生委員会では健康づくりについて北九州市に視察に行きまして、いろいろと、きのう報告会であったんですけれども、健康づくり推進協議会というところで集まって協議するというときに、そこでのお話でも健康づくりプランについて、評価がなかなかできるプランではなかったという言葉をいただいて、次につくったのは、評価ができるようにプランをつくったということをいただいて。","respondent":"江部健康課長","answer":"したがいまして、今後次のプランをつくる、つくらないにかかわらず、協議会の委員さん方が具体的に検討できるようなものはつくっていく必要があり、それを目標にやるということで、その効果があがることになるんだと思います。","id":"exchange-028"},{"speaker":"渡部委員","kind":"質問","question":"健康づくり推進委員ですか、各町会から選出されていまして、それぞれ皆様方に活動いただいています。ですから、やっている行事もそういう方々の参加はある程度口コミで、出て、出てと言って、この間の２３日も私たちの地域はウオーキング、イメージとしては「歩け歩け」とみんな言っちゃうんですけれども、ウオーキングに行かれて、うちの町会からも十数名の方が行かれました。","respondent":"江部健康課長","answer":"それが裾野を広げることにつながると認識しております。","id":"exchange-029"},{"speaker":"渡部委員","kind":"質問","question":"そのためにも、いろいろな形でさまざまな活動の連携をとって、例えば、先ほどからスポーツ推進委員って間違えて出てきちゃったりするんですけれども、その辺の分野ともさまざまな連携をとって、もっと全体的な底上げが図れる仕組みづくりを少しずつ構築していって、２０２０年にはそういう形ができていればいいなと思っているんですが、そういう意味でも横の連携とかって、どのようにお考えでしょうか。","respondent":"江部健康課長","answer":"スポーツをするところ、私どものように１次予防をするところ、いきがい課のような介護予防をするところというようなことで、段階的には違うんですけれども、違うためにそれぞれの所管が違っておりますが、全体でどういう事業をやっているかということについては。","id":"exchange-030"},{"speaker":"渡部委員","kind":"質問","question":"ですから、昨日の視察報告会での話になりますけれども、小学校区を単位にやっているというのは新たな切り口として、どういう形で進められるかというのは別問題なんですけれども、狭いコミュニティで物事を進めていくと、結構そこにみんなパワーが集中して、いい形にいくのかななんて思いがありますので、さまざまな角度で研究していただいて、健康づくりにこれからもしっかり取り組んでいきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"たけうち委員","kind":"質問","question":"２番の現在の体制のところで、健康づくりの推進協議会のほうには各推進委員会の代表の方というか、会長がお一人ずつ参加されて、いろいろ研修会ですとか情報交換、また交流会等でやっていらっしゃるということなんですが、健康づくり推進委員の２１５名の方たちに対するモチベーションを高めていくというか、いろいろな面でのバックアップ体制というのは、各地区の会長任せなのか。","respondent":"江部健康課長","answer":"ただいまご指摘いただきました現在の体制の中の(1)の推進協議会の主な事業の中で、研修会などと書いてありますのは、協議会のメンバーだけでやる研修会ではございませんで、全地区を集めた研修会になっております。","id":"exchange-032"},{"speaker":"たけうち委員","kind":"質問","question":"それで、本当に各地域によって、各町会によって、推進委員の動きというのは多分格差があると思うんですけれども、どちらかというと僕のイメージなんですが、防災の係も、町会の中で防災の責任者の方とかそういう方に比べると、なかなか動きが見えにくいというか、なかなか町会に波及していっていないところもあるような感じもするんですけれども、そういう中で、さっきチラシのほうで課長が、今。","respondent":"江部健康課長","answer":"認知という言葉がよく使われるんですけれども、認知されていないという声が、全体ではありません、委員の中で町会の役員をされていたりすると、きちっと活動内容がフィードバックされていまして、今回回っていましても、町会長の中ではもう知っている、わかっているよという方と。","id":"exchange-033"},{"speaker":"たけうち委員","kind":"質問・要望","question":"わかりました。本当にそういう面で大変だと思うんですけれども、そこから広がっていかないとなかなか厳しいと思いますので、ぜひ頑張っていただきたいと思います。最後、ここと関係ないんですけれども、前に４０歳からのふれあい健康塾みたいなのがあったような気がしたんですが、これは推進委員とは違うから出ていなくて、事業自体はあるんでしたっけ。","respondent":"江部健康課長","answer":"多分、８月５日の健康づくり事業の中でご説明いたしました健康塾という、トリム連盟にお願いしている６０歳からという条件でのものだと思いますが、４０歳からという運動教室というのは……。","id":"exchange-034"},{"speaker":"たけうち委員","kind":"質問","question":"今、４０歳からというのは、私たち、結構前にあったような気がしたんですけれども、もう事業自体が名前が変わったのか、なくなっちゃったんですかね。","respondent":"江部健康課長","answer":"事務事業概要７３ページに、４０代からの健康塾、確かにございまして、これは健康センターのプログラムの中に組んでいただいている一つのものです。ちょっと少人数のプログラムに、これは組み込まれました。","id":"exchange-035"},{"speaker":"あくつ委員","kind":"質問・要望","question":"１点だけお伺いします。こういうパンフレットづくり、非常にいいのかなと思います。その上で、いろいろな事業をされて、いろいろな内容で考えてやられているんですけれども、たしか体操教室のところでもいろいろ課長ともやりとりさせていただいた中で、民生委員とか保健師との連携があったと思うんですが、その辺はどういう仕組みになっているのかを教えていただきたいと思います。","respondent":"江部健康課長、亀井品川区保健所品川保健センター所長","answer":"保健師は、保健センターの保健師が各地区で、全部の地区ではありませんけれども、健康課の職員と保健センターの保健師、その他の職員で、事務的なところとかケアの部分はお手伝いしているのが現状です。１３地区に必ず、保健センターは三つに分かれていますけれども、そこの保健師ないし栄養士等の専門職が担当としてついていますので、あくまで推進委員会が主体的に動くんですけれども。","id":"exchange-036"},{"speaker":"あくつ委員","kind":"質問・要望","question":"そういった横のつながりというか、バックアップ体制もあるということで、先ほども各委員からありましたけれども、モチベーションを高めていただく取り組みをぜひ進めていっていただきたいと思います。今、区長のほうでも新しいプランの改訂についてもいろいろお考えになっているようですので、ぜひそこにも的確に位置づけていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"}]},{"id":"topic-03","title":"の３、その他を議題に供します。 まず、(1)の所管質問","agenda":"の３、その他を議題に供します。 まず、(1)の所管質問","exchanges":[{"speaker":"井上委員","kind":"質問","question":"それと、携帯してもらえないとか、課題があるということで、そこのところはわかるんですけれども、そこを何とか利用してもらうように進めていかないと、すごく困難な人がたくさんいるわけで、あることを知らない人もいるかもしれないし、なぜそのことが利用につながらないのかということをもう少し区としてしっかりと把握して、そこの利用をつなげる対策をとらなければいけないというところで。","respondent":"永尾高齢者福祉課長","answer":"ただ、料金につきましては、区では初期経費といたしまして７,３５０円出しておりますので、発見されたときの１万円、税込みですと１万５００円になるんですけれども、こちらの経費についてはご家族等のご負担にせざるを得ないのかなと考えておりますが。","id":"exchange-038"},{"speaker":"井上委員","kind":"質問","question":"前回、当委員会でこの議論をしたときがありまして、そのとき、２０１２年の探索は、実績は１１人ということで、そのときに、辞退する方も何件かいるんですよということだったんですが、どういう理由で辞退されているのかということと、あと、実際にそれを携帯される方で、現場急行した事例が何件あるのか教えてください。","respondent":"永尾高齢者福祉課長","answer":"実際に辞退されたというのは、身につけなかったり、ふらっと出ていってしまうという特質がありますので、なかなか効果的にできないということですね。","id":"exchange-039"},{"speaker":"井上委員","kind":"質問","question":"そういうことをもう少し説明するとか、あるいは、初期投資７,３５０円を区が負担しているということで、どれだけそこに税金を投入するかというのはまた違う問題なんですけれども、何回まではということで、すごく行ってしまう人たちはまた別の方法を考えるとして、１回か２回まではというようなことをすると利用者も増えて、本当に困っている方が救済されるのかなと思うので、そういった一つの考え方と。","respondent":"永尾高齢者福祉課長","answer":"というのは、今、実際の実績がそこまで上がっていない中で、その回数を決めるというのは、１回決めてしまえば、ずっと継続してやらなければいけないことになりますので、それよりももうちょっと、今はケアマネジャーへの周知を中心にやっていますけれども。","id":"exchange-040"},{"speaker":"井上委員","kind":"質問・要望","question":"ちょっと現場がわからないので、在支は確認していると思いますというと、地域包括支援センターは区にあるわけですから、その辺の、きちんとこのぐらいで、この利用が進まないというのが納得できるなら、それはそれで制度としてあることでいいかなと思うんですけれども、そういったところをしっかり把握した上で、そういう事業の評価、見直しが必要だと思うので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/588633?Template=document&Id=3374#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":34441,"voices":117}}]);
